      and recipient_id is distinct from v_user_id
  loop
    perform public.notify_workspace_team_user(
      v_invite.workspace_id,
      v_recipient,
      'team_invite_accepted',
      'Workspace invite accepted',
      v_invite.email || ' accepted access to ' || coalesce(v_workspace_name, 'your workspace') || '.',
      '/workspace/' || v_invite.workspace_id::text || '/settings/team',
      'workspace_member',
      v_membership.id,
      jsonb_build_object('role', v_invite.role)
    );
  end loop;

  return jsonb_build_object(
    'workspaceId', v_invite.workspace_id,
    'membershipId', v_membership.id,
    'relation', 'shared',
    'role', v_invite.role,
    'redirectTo', '/pt-hub/workspaces?acceptedWorkspace=' || v_invite.workspace_id::text
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_paddle_catalogue_mapping_v1(p_mapping_id uuid, p_evidence_id uuid, p_digest text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m public.billing_price_mappings%rowtype;
begin
  perform public.billing_catalogue_authorize_v1();
  perform pg_advisory_xact_lock(hashtextextended('paddle-catalogue-publication-v1:test',0));
  select * into m from public.billing_price_mappings where id=p_mapping_id for update;
  if not found or m.status='retired' then raise exception 'BILLING_CATALOGUE_NOT_DRAFT'; end if;
  if p_evidence_id is null or p_digest is null or m.catalogue_evidence_id is distinct from p_evidence_id or m.verification_sha256::text is distinct from p_digest then raise exception 'BILLING_CATALOGUE_EVIDENCE_REQUIRED'; end if;
  perform public.billing_catalogue_assert_mapping_v1(m);
  update public.billing_price_mappings set status='active',updated_at=clock_timestamp() where id=m.id;
  return m.id;
end $function$

CREATE OR REPLACE FUNCTION public.add_months_clamped(p_date date, p_months integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_month_start date;
  v_month_end date;
  v_day integer;
begin
  if p_date is null then
    return null;
  end if;

  v_month_start := (
    date_trunc('month', p_date)::date + make_interval(months =&gt; p_months)
  )::date;
  v_month_end := (v_month_start + interval '1 month - 1 day')::date;
  v_day := least(
    extract(day from p_date)::integer,
    extract(day from v_month_end)::integer
  );

  return v_month_start + (v_day - 1);
end;
$function$

CREATE OR REPLACE FUNCTION public.admit_account_capacity_subject(p_owner uuid, p_dimension text, p_subject text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  a uuid; e jsonb; r jsonb; existing uuid; operation_id uuid := gen_random_uuid();
  t timestamptz := transaction_timestamp();
begin
  select id into a from public.billing_accounts where owner_user_id = p_owner for update;
  -- Domain identity, never a browser quantity, determines the delta under the lock.
  if exists(select 1 from public.account_capacity_subjects(p_owner,t) s
      where s.dimension=p_dimension and s.subject_key=p_subject) then return null; end if;
  if a is null then
    perform public.account_capacity_mutation_error('ACCOUNT_CAPACITY_UNAVAILABLE',p_dimension);
  end if;
  -- Reuse only this transaction's private, actor-bound domain admission. No GUC,
  -- request header, browser field, or historical granted response is authority.
  select id into existing from public.account_capacity_reservations
    where billing_account_id=a and dimension=p_dimension and subject_key=p_subject
      and source='domain.admission' and status='active' and expires_at&gt;t
      and created_at=t and admission_transaction_id=pg_current_xact_id()
      and created_by_user_id is not distinct from auth.uid();
  if existing is not null then return existing; end if;
  e := public.resolve_account_entitlements(a);
  if e#&gt;&gt;'{subscription,accessMode}' is distinct from 'full' then
    perform public.account_capacity_mutation_error('ACCOUNT_CAPACITY_GROWTH_NOT_ALLOWED',p_dimension);
  end if;
  r := public.reserve_account_capacity(a,p_dimension,1,operation_id::text,
    split_part(p_subject,':',1),p_subject,null,'domain.admission',t+interval '30 seconds',
    jsonb_build_object('operationId',operation_id));
  if not coalesce((r-&gt;&gt;'granted')::boolean,false) then
    perform public.account_capacity_mutation_error(case when r-&gt;&gt;'reasonCode'='capacity_unavailable'
      then 'ACCOUNT_CAPACITY_UNAVAILABLE' else 'ACCOUNT_CAPACITY_LIMIT_REACHED' end,p_dimension);
  end if;
  if r-&gt;&gt;'status' is distinct from 'active' then
    perform public.account_capacity_mutation_error('ACCOUNT_CAPACITY_RESERVATION_CONFLICT',p_dimension);
  end if;
  if (r-&gt;&gt;'expiresAt')::timestamptz&lt;=t then
    perform public.account_capacity_mutation_error('ACCOUNT_CAPACITY_OPERATION_EXPIRED',p_dimension);
  end if;
  return (r-&gt;&gt;'reservationId')::uuid;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_client_account_profile_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_source public.clients%rowtype;
begin
  if new.user_id is null then
    return new;
  end if;

  select *
  into v_source
  from public.clients c
  where c.user_id = new.user_id
    and c.id is distinct from new.id
    and (
      c.account_onboarding_completed_at is not null
      or c.full_name is not null
      or c.display_name is not null
      or c.phone is not null
      or c.email is not null
      or c.avatar_url is not null
      or c.photo_url is not null
      or c.date_of_birth is not null
      or c.dob is not null
      or c.sex is not null
      or c.gender is not null
      or c.height_value is not null
      or c.height_cm is not null
      or c.weight_value_current is not null
      or c.current_weight is not null
    )
  order by
    case when c.account_onboarding_completed_at is not null then 0 else 1 end,
    case when c.workspace_id is null then 0 else 1 end,
    c.updated_at desc nulls last,
    c.created_at desc
  limit 1;

  if v_source.id is null then
    return new;
  end if;

  new.account_onboarding_completed_at := coalesce(
    new.account_onboarding_completed_at,
    v_source.account_onboarding_completed_at
  );
  new.display_name := coalesce(new.display_name, v_source.display_name);
  new.full_name := coalesce(new.full_name, v_source.full_name);
  new.phone := coalesce(new.phone, v_source.phone);
  new.email := coalesce(new.email, v_source.email);
  new.avatar_url := coalesce(new.avatar_url, v_source.avatar_url);
  new.photo_url := coalesce(new.photo_url, v_source.photo_url);
  new.date_of_birth := coalesce(new.date_of_birth, v_source.date_of_birth);
  new.dob := coalesce(new.dob, v_source.dob);
  new.sex := coalesce(new.sex, v_source.sex);
  new.gender := coalesce(new.gender, v_source.gender);
  new.height_value := coalesce(new.height_value, v_source.height_value);
  new.height_unit := coalesce(new.height_unit, v_source.height_unit);
  new.height_cm := coalesce(new.height_cm, v_source.height_cm);
  new.weight_value_current := coalesce(
    new.weight_value_current,
    v_source.weight_value_current
  );
  new.weight_unit := coalesce(new.weight_unit, v_source.weight_unit);
  new.current_weight := coalesce(new.current_weight, v_source.current_weight);
  new.unit_preference := coalesce(new.unit_preference, v_source.unit_preference);
  new.location := coalesce(new.location, v_source.location);
  new.location_country := coalesce(
    new.location_country,
    v_source.location_country
  );
  new.timezone := coalesce(new.timezone, v_source.timezone);

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_program_to_client(p_client_id uuid, p_program_template_id uuid, p_start_date date, p_horizon_days integer DEFAULT 14)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_program_id uuid;
  v_workspace_id uuid;
  v_weeks_count int;
  v_i int;
  v_target_date date;
  v_week_number int;
  v_day_of_week int;
  v_workout_template_id uuid;
  v_is_rest bool;
  v_upserted int := 0;
  v_rowcount int;
begin
  select c.workspace_id
  into v_workspace_id
  from public.clients c
  where c.id = p_client_id;

  if v_workspace_id is null then
    raise exception 'Client not found';
  end if;

  if not exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = v_workspace_id
      and wm.user_id = auth.uid()
      and wm.role::text like 'pt_%'
  ) then
    raise exception 'Not authorized';
  end if;

  select weeks_count
  into v_weeks_count
  from public.program_templates pt
  where pt.id = p_program_template_id
    and pt.workspace_id = v_workspace_id;

  if v_weeks_count is null then
    raise exception 'Program template not found in workspace';
  end if;

  update public.client_programs
  set is_active = false,
      updated_at = now()
  where client_id = p_client_id
    and is_active = true;

  insert into public.client_programs (
    client_id,
    program_template_id,
    start_date,
    is_active
  ) values (
    p_client_id,
    p_program_template_id,
    p_start_date,
    true
  )
  returning id into v_client_program_id;

  for v_i in 0..greatest(p_horizon_days, 0) - 1 loop
    v_target_date := p_start_date + v_i;
    v_week_number := ((v_i / 7) % v_weeks_count) + 1;
    v_day_of_week := (v_i % 7) + 1;

    select o.workout_template_id, o.is_rest
    into v_workout_template_id, v_is_rest
    from public.client_program_overrides o
    where o.client_program_id = v_client_program_id
      and o.override_date = v_target_date;

    if not found then
      select d.workout_template_id, d.is_rest
      into v_workout_template_id, v_is_rest
      from public.program_template_days d
      where d.program_template_id = p_program_template_id
        and d.week_number = v_week_number
        and d.day_of_week = v_day_of_week
      order by d.sort_order asc
      limit 1;
    end if;

    if not found then
      continue;
    end if;

    if v_is_rest or v_workout_template_id is null then
      update public.assigned_workouts
      set status = 'planned',
          workout_template_id = null,
          day_type = 'rest',
          program_id = p_program_template_id,
          program_day_index = v_i
      where client_id = p_client_id
        and scheduled_date = v_target_date
        and workout_template_id is null;

      get diagnostics v_rowcount = row_count;

      if v_rowcount = 0 then
        insert into public.assigned_workouts (
          client_id,
          workout_template_id,
          scheduled_date,
          status,
          day_type,
          program_id,
          program_day_index
        ) values (
          p_client_id,
          null,
          v_target_date,
          'planned',
          'rest',
          p_program_template_id,
          v_i
        );
        v_upserted := v_upserted + 1;
      else
        v_upserted := v_upserted + v_rowcount;
      end if;
    else
      insert into public.assigned_workouts (
        client_id,
        workout_template_id,
        scheduled_date,
        status,
        day_type,
        program_id,
        program_day_index
      ) values (
        p_client_id,
        v_workout_template_id,
        v_target_date,
        'planned',
        'workout',
        p_program_template_id,
        v_i
      )
      on conflict (client_id, scheduled_date, workout_template_id)
      do update set
        status = 'planned',
        day_type = 'workout',
        program_id = p_program_template_id,
        program_day_index = v_i;

      get diagnostics v_rowcount = row_count;
      v_upserted := v_upserted + v_rowcount;
    end if;
  end loop;

  return v_upserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_verified_billing_plan_change(p_operation uuid, p_snapshot jsonb, p_event text, p_invoice jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare o public.billing_plan_change_operations%rowtype; b public.billing_provider_subscriptions%rowtype; m public.billing_provider_variant_mappings%rowtype; s public.account_subscriptions%rowtype; target_id uuid; paid boolean; due boolean; local_status text; stamp timestamptz:=(p_snapshot-&gt;&gt;'updated_at')::timestamptz;
begin
  -- BILLING-DB-02 BEGIN
  perform public.billing_guard_legacy_entry('apply_plan',p_operation);
  -- BILLING-DB-02 END
  select * into strict o from public.billing_plan_change_operations where id=p_operation for update;
  if o.status in ('completed','canceled','failed') then return; end if;
  select * into strict b from public.billing_provider_subscriptions where id=o.billing_provider_subscription_id;
  select * into strict s from public.account_subscriptions where id=o.source_account_subscription_id;
  if stamp&lt;o.provider_requested_at or stamp&lt;b.provider_updated_at then return; end if;
  if o.status='cancel_pending' then
    select * into strict m from public.billing_provider_variant_mappings where id=o.source_variant_mapping_id;
    if (p_snapshot-&gt;&gt;'product_id',p_snapshot-&gt;&gt;'variant_id',p_snapshot-&gt;&gt;'price_id')=(m.provider_product_id,m.provider_variant_id,m.provider_price_id) then
      update public.billing_provider_subscriptions set variant_mapping_id=m.id,provider_product_id=m.provider_product_id,provider_variant_id=m.provider_variant_id,provider_price_id=m.provider_price_id where id=b.id;
      update public.billing_plan_change_operations set status='canceled',canceled_at=now(),updated_at=now(),error_code=null where id=o.id;
      return;
    end if;
  end if;
  select * into strict m from public.billing_provider_variant_mappings where id=o.target_variant_mapping_id;
  if (p_snapshot-&gt;&gt;'product_id',p_snapshot-&gt;&gt;'variant_id',p_snapshot-&gt;&gt;'price_id') is distinct from (m.provider_product_id,m.provider_variant_id,m.provider_price_id) then return; end if;
  if o.effective_timing='period_end' and now()&lt;o.effective_at and p_snapshot-&gt;&gt;'status' in ('active','past_due','unpaid')
    and (p_snapshot-&gt;&gt;'renews_at')::timestamptz is distinct from o.effective_at then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
  paid:=o.effective_timing='immediate' and p_event in ('subscription_payment_success','subscription_payment_recovered')
    and p_invoice-&gt;&gt;'billing_reason'='updated' and p_invoice-&gt;&gt;'status'='paid'
    and p_invoice-&gt;&gt;'subscription_id'=b.provider_subscription_id and p_invoice-&gt;&gt;'customer_id'=b.provider_customer_id and p_invoice-&gt;&gt;'store_id'=b.provider_store_id
    and (p_invoice-&gt;&gt;'test_mode')::boolean=(b.environment='test')
    and (p_invoice-&gt;&gt;'created_at')::timestamptz&gt;=o.provider_requested_at and (p_invoice-&gt;&gt;'updated_at')::timestamptz&gt;=o.provider_requested_at;
  due:=o.effective_timing='period_end' and now()&gt;=o.effective_at and o.status&lt;&gt;'cancel_pending' and not s.cancel_at_period_end and not (p_snapshot-&gt;&gt;'cancelled')::boolean;
  update public.billing_plan_change_operations set status=case when status='cancel_pending' then status when effective_timing='immediate' then 'awaiting_payment' else 'scheduled' end,
    provider_applied_at=coalesce(provider_applied_at,now()),provider_updated_at=stamp,provider_snapshot_sha256=encode(extensions.digest(p_snapshot::text,'sha256'),'hex'),
    error_code=case when p_event='subscription_payment_failed' then 'BILLING_PLAN_CHANGE_PAYMENT_FAILED' else null end,updated_at=now() where id=o.id;
  if coalesce(paid,false) or coalesce(due,false) then
    local_status:=case p_snapshot-&gt;&gt;'status' when 'past_due' then 'past_due' when 'unpaid' then 'grace' when 'expired' then 'expired' else 'active' end;
    if o.source_plan_version_id&lt;&gt;o.target_plan_version_id then
      target_id:=gen_random_uuid();
      update public.account_subscriptions set status='superseded',superseded_at=now(),superseded_by_subscription_id=target_id,status_changed_at=now() where id=s.id;
      insert into public.account_subscriptions(id,billing_account_id,plan_version_id,subscription_kind,status,source,current_period_started_at,current_period_ends_at,expired_at)
        values(target_id,o.billing_account_id,o.target_plan_version_id,'paid',local_status,'billing_provider',
          case when local_status='expired' or (p_snapshot-&gt;&gt;'renews_at')::timestamptz&lt;=now() then null else case when due then o.effective_at else now() end end,
          case when local_status='expired' then (p_snapshot-&gt;&gt;'ends_at')::timestamptz else (p_snapshot-&gt;&gt;'renews_at')::timestamptz end,
          case when local_status='expired' then now() else null end);
      insert into public.account_subscription_events(billing_account_id,subscription_id,event_type,from_status,to_status,source,metadata)
        values(o.billing_account_id,s.id,'subscription.plan_superseded',s.status,'superseded','billing_provider',jsonb_build_object('operationId',o.id));
    else target_id:=s.id; end if;
    update public.billing_provider_subscriptions set account_subscription_id=target_id,variant_mapping_id=m.id,provider_product_id=m.provider_product_id,provider_variant_id=m.provider_variant_id,provider_price_id=m.provider_price_id where id=b.id;
    update public.billing_plan_change_operations set status='completed',completed_at=now(),payment_confirmed_at=case when paid then now() else null end,updated_at=now() where id=o.id;
  else
    update public.billing_provider_subscriptions set variant_mapping_id=m.id,provider_product_id=m.provider_product_id,provider_variant_id=m.provider_variant_id,provider_price_id=m.provider_price_id where id=b.id;
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.apply_verified_billing_seat_quantity(p_subscription uuid, p_snapshot jsonb, p_event text, p_invoice jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.billing_provider_subscriptions%rowtype; o public.billing_seat_quantity_operations%rowtype; paid boolean; due boolean; q integer:=(p_snapshot-&gt;&gt;'quantity')::integer;
begin
  -- BILLING-DB-02 BEGIN
  perform public.billing_guard_legacy_entry('apply_seat',p_subscription);
  -- BILLING-DB-02 END
  select * into strict b from public.billing_provider_subscriptions where id=p_subscription;
  select * into o from public.billing_seat_quantity_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed') for update;
  if o.id is null then return; end if;
  if (p_snapshot-&gt;&gt;'updated_at')::timestamptz&lt;o.provider_requested_at then return; end if;
  if not exists(select 1 from public.billing_quantity_price_contracts where id=o.quantity_price_contract_id and variant_mapping_id=b.variant_mapping_id and status in ('active','retired')) then raise exception 'BILLING_SEAT_QUANTITY_PRICE_CONTRACT_MISMATCH'; end if;
  if o.status='cancel_pending' and q=o.source_quantity and (p_snapshot-&gt;&gt;'updated_at')::timestamptz&gt;=o.cancel_requested_at then
    update public.billing_seat_quantity_operations set status='canceled',canceled_at=now(),error_code=null,updated_at=now() where id=o.id; return;
  end if;
  if q&lt;&gt;o.target_quantity then return; end if;
  if o.direction='reduction' and now()&lt;o.effective_at and p_snapshot-&gt;&gt;'status' in ('active','past_due','unpaid') and (p_snapshot-&gt;&gt;'renews_at')::timestamptz is distinct from o.effective_at then raise exception 'BILLING_SEAT_QUANTITY_MANUAL_REVIEW'; end if;
  paid:=o.direction='increase' and p_event in ('subscription_payment_success','subscription_payment_recovered') and p_invoice-&gt;&gt;'status'='paid' and p_invoice-&gt;&gt;'billing_reason'='updated'
    and (p_invoice-&gt;&gt;'subscription_id',p_invoice-&gt;&gt;'customer_id',p_invoice-&gt;&gt;'store_id')=(b.provider_subscription_id,b.provider_customer_id,b.provider_store_id)
    and (p_invoice-&gt;&gt;'test_mode')::boolean=(b.environment='test') and (p_invoice-&gt;&gt;'created_at')::timestamptz&gt;o.provider_requested_at and (p_invoice-&gt;&gt;'updated_at')::timestamptz&gt;o.provider_requested_at;
  due:=o.direction='reduction' and now()&gt;=o.effective_at and o.status&lt;&gt;'cancel_pending';
  update public.billing_seat_quantity_operations set status=case when status='cancel_pending' then status when direction='increase' then 'awaiting_payment' else 'scheduled' end,
    provider_applied_at=coalesce(provider_applied_at,now()),provider_updated_at=(p_snapshot-&gt;&gt;'updated_at')::timestamptz,provider_snapshot_sha256=encode(extensions.digest(p_snapshot::text,'sha256'),'hex'),
    error_code=case when p_event='subscription_payment_failed' then 'BILLING_SEAT_QUANTITY_PAYMENT_FAILED' when error_code='BILLING_SEAT_QUANTITY_PAYMENT_FAILED' then error_code when direction='increase' then 'BILLING_SEAT_QUANTITY_AWAITING_PAYMENT' else null end,updated_at=now() where id=o.id;
  if (coalesce(paid,false) or coalesce(due,false)) and p_snapshot-&gt;&gt;'status'='active' and (p_snapshot-&gt;&gt;'cancelled')::boolean=false and
    exists(select 1 from public.account_subscriptions where id=b.account_subscription_id and subscription_kind='paid' and status in ('active','past_due','grace') and not cancel_at_period_end) then
    update public.billing_provider_subscriptions set approved_additional_coach_seats=o.target_additional_seats where id=b.id;
    update public.billing_seat_quantity_operations set status='completed',completed_at=now(),payment_confirmed_at=case when paid then now() else null end,error_code=null,updated_at=now() where id=o.id;
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.assert_commercial_action_allowed(p_owner uuid, p_action text, p_workspace uuid DEFAULT NULL::uuid, p_client uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r jsonb; code text; audience text;
begin
  if auth.uid() is null then raise exception 'Authentication required.' using errcode='42501'; end if;
  -- Resolve audience only after a domain access check; never disclose a foreign
  -- owner's subscription to an unauthorized caller.
  if p_client is not null and exists(select 1 from public.clients where id=p_client and user_id=auth.uid()) then audience:='client';
  elsif p_owner=auth.uid() then audience:='owner';
  elsif p_workspace is not null and public.can_access_workspace(p_workspace) then audience:='team';
  else raise exception 'Access denied.' using errcode='42501'; end if;
  r:=public.resolve_account_commercial_access(p_owner);
  if public.is_commercial_action_allowed(r-&gt;&gt;'accessMode',p_action) then return; end if;
  code:=case audience when 'client' then 'CLIENT_COACHING_INTERACTION_UNAVAILABLE' when 'team' then 'WORKSPACE_COMMERCIAL_ACCESS_UNAVAILABLE'
    else case when r-&gt;&gt;'reason'='owner_recovery_required' then 'ACCOUNT_ACCESS_OWNER_RECOVERY_REQUIRED'
      when r-&gt;&gt;'accessMode'='existing_delivery_only' then 'ACCOUNT_ACCESS_EXISTING_DELIVERY_ONLY'
      when r-&gt;&gt;'accessMode'='read_only' then 'ACCOUNT_ACCESS_READ_ONLY'
      when r-&gt;&gt;'accessMode'='none' then 'ACCOUNT_ACCESS_EXPIRED'
      when r-&gt;&gt;'accessMode'='onboarding' then 'ACCOUNT_ACCESS_ONBOARDING_ONLY'
      else 'ACCOUNT_ACCESS_ACTION_NOT_ALLOWED' end end;
  raise exception '%',code using errcode='42501',detail=(jsonb_build_object('code',code,'audience',audience)
    || case when audience='owner' then jsonb_build_object('accessMode',r-&gt;'accessMode','effectiveUntil',r-&gt;'effectiveUntil','recoveryPath',r-&gt;'recoveryPath','recoveryAction',r-&gt;'recoveryAction') else '{}'::jsonb end)::text;
end $function$

CREATE OR REPLACE FUNCTION public.assign_program_to_client(p_client_id uuid, p_program_id uuid, p_start_date date, p_days_ahead integer DEFAULT 14)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_workspace_id uuid;
  v_program_workspace_id uuid;
  v_weeks_count int;
  v_i int;
  v_target_date date;
  v_week_number int;
  v_day_of_week int;
  v_workout_template_id uuid;
  v_is_rest bool;
  v_day_note text;
  v_upserted int := 0;
  v_rowcount int;
begin
  select c.workspace_id
  into v_workspace_id
  from public.clients c
  where c.id = p_client_id;

  if v_workspace_id is null then
    raise exception 'Client not found';
  end if;

  if not public.can_write_client_delivery(p_client_id) then
    raise exception 'Not authorized';
  end if;

  select pt.workspace_id, pt.weeks_count
  into v_program_workspace_id, v_weeks_count
  from public.program_templates pt
  where pt.id = p_program_id;

  if v_program_workspace_id is null then
    raise exception 'Program not found';
  end if;

  if v_program_workspace_id &lt;&gt; v_workspace_id then
    raise exception 'Program not found in workspace';
  end if;

  update public.client_program_assignments
  set is_active = false
  where client_id = p_client_id
    and is_active = true;

  insert into public.client_program_assignments (
    workspace_id,
    client_id,
    program_id,
    start_date,
    is_active
  ) values (
    v_workspace_id,
    p_client_id,
    p_program_id,
    p_start_date,
    true
  );

  if to_regclass('public.client_programs') is not null then
    update public.client_programs
    set is_active = false,
        updated_at = now()
    where client_id = p_client_id
      and is_active = true;

    insert into public.client_programs (
      client_id,
      program_template_id,
      start_date,
      is_active
    ) values (
      p_client_id,
      p_program_id,
      p_start_date,
      true
    );
  end if;

  for v_i in 0..greatest(p_days_ahead, 0) - 1 loop
    v_target_date := p_start_date + v_i;
    v_week_number := ((v_i / 7) % v_weeks_count) + 1;
    v_day_of_week := (v_i % 7) + 1;

    select d.workout_template_id, d.is_rest, nullif(btrim(d.notes), '')
    into v_workout_template_id, v_is_rest, v_day_note
    from public.program_template_days d
    where d.program_template_id = p_program_id
      and d.week_number = v_week_number
      and d.day_of_week = v_day_of_week
    order by d.sort_order asc
    limit 1;

    if not found then
      continue;
    end if;

    update public.assigned_workouts
    set workout_template_id = case when v_is_rest then null else v_workout_template_id end,
        day_type = case when v_is_rest or v_workout_template_id is null then 'rest' else 'workout' end,
        status = 'planned',
        program_id = p_program_id,
        program_day_index = v_i,
        coach_note = v_day_note
    where client_id = p_client_id
      and scheduled_date = v_target_date;

    get diagnostics v_rowcount = row_count;

    if v_rowcount = 0 then
      insert into public.assigned_workouts (
        client_id,
        workout_template_id,
        scheduled_date,
        status,
        day_type,
        program_id,
        program_day_index,
        coach_note
      ) values (
        p_client_id,
        case when v_is_rest then null else v_workout_template_id end,
        v_target_date,
        'planned',
        case when v_is_rest or v_workout_template_id is null then 'rest' else 'workout' end,
        p_program_id,
        v_i,
        v_day_note
      );
      v_upserted := v_upserted + 1;
    else
      v_upserted := v_upserted + v_rowcount;
    end if;
  end loop;

  return v_upserted;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_workout_with_template(p_client_id uuid, p_scheduled_date date, p_workout_template_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_assigned_workout_id uuid;
  v_client_workspace_id uuid;
  v_template_workspace_id uuid;
  v_active_client_program_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_client_id is null or p_scheduled_date is null or p_workout_template_id is null then
    raise exception 'client_id, scheduled_date and workout_template_id are required';
  end if;

  select c.workspace_id
  into v_client_workspace_id
  from public.clients c
  where c.id = p_client_id;

  if v_client_workspace_id is null then
    raise exception 'Client not found';
  end if;

  if not public.can_write_client_delivery(p_client_id) then
    raise exception 'Not authorized';
  end if;

  select wt.workspace_id
  into v_template_workspace_id
  from public.workout_templates wt
  where wt.id = p_workout_template_id;

  if v_template_workspace_id is null then
    raise exception 'Workout template not found';
  end if;

  if v_template_workspace_id &lt;&gt; v_client_workspace_id then
    raise exception 'Template not in client workspace';
  end if;

  if exists (
    select 1
    from public.assigned_workouts aw
    where aw.client_id = p_client_id
      and aw.scheduled_date = p_scheduled_date
      and aw.status = 'completed'
  ) then
    raise exception 'Cannot replace a completed workout day';
  end if;

  select cp.id
  into v_active_client_program_id
  from public.client_programs cp
  where cp.client_id = p_client_id
    and cp.is_active = true
    and cp.start_date &lt;= p_scheduled_date
  order by cp.start_date desc, cp.created_at desc
  limit 1;

  if v_active_client_program_id is not null then
    return public.save_client_program_day_override(
      v_active_client_program_id,
      p_scheduled_date,
      p_workout_template_id,
      false,
      null
    );
  end if;

  select aw.id
  into v_assigned_workout_id
  from public.assigned_workouts aw
  where aw.client_id = p_client_id
    and aw.scheduled_date = p_scheduled_date
    and aw.status &lt;&gt; 'completed'
  order by aw.created_at asc
  limit 1;

  if v_assigned_workout_id is null then
    insert into public.assigned_workouts (
      client_id,
      workout_template_id,
      scheduled_date,
      status,
      day_type,
      program_id,
      program_day_index,
      coach_note
    )
    values (
      p_client_id,
      p_workout_template_id,
      p_scheduled_date,
      'planned',
      'workout',
      null,
      null,
      null
    )
    returning id into v_assigned_workout_id;
  else
    update public.assigned_workouts
    set workout_template_id = p_workout_template_id,
        status = 'planned',
        completed_at = null,
        day_type = 'workout',
        program_id = null,
        program_day_index = null,
        coach_note = null
    where id = v_assigned_workout_id;
  end if;

  delete from public.assigned_workouts aw
  where aw.client_id = p_client_id
    and aw.scheduled_date = p_scheduled_date
    and aw.status &lt;&gt; 'completed'
    and aw.id &lt;&gt; v_assigned_workout_id;

  perform public.materialize_assigned_workout_exercises(v_assigned_workout_id);

  return v_assigned_workout_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_account_commercial_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_type text; v_subscription_id uuid; v_from text; v_to text; v_metadata jsonb := '{}'; v_account_id uuid; v_source text;
begin
  if tg_table_name = 'billing_accounts' then
    v_account_id := new.id;
    v_source := new.requested_plan_source;
    if tg_op = 'INSERT' then
      v_type := 'billing_account.created';
      v_metadata := jsonb_build_object('createdSource', new.created_source);
    elsif new.requested_plan_key is distinct from old.requested_plan_key then
      v_type := 'requested_plan.changed';
      v_metadata := jsonb_build_object('fromPlanKey',old.requested_plan_key,'toPlanKey',new.requested_plan_key);
    end if;
  elsif tg_table_name = 'account_subscriptions' then
    v_account_id := new.billing_account_id; v_subscription_id := new.id; v_source := new.source; v_to := new.status;
    if tg_op = 'INSERT' then
      v_type := case new.subscription_kind when 'trial' then 'subscription.trial_started'
        when 'complimentary' then 'subscription.complimentary_access_created' else 'subscription.created' end;
      v_metadata := jsonb_build_object('planVersionId',new.plan_version_id,'trialPolicyVersionId',new.trial_policy_version_id);
    elsif new.status is distinct from old.status then
      v_type := 'subscription.status_changed'; v_from := old.status;
    end if;
  else
    v_account_id := new.billing_account_id; v_source := new.source;
    v_metadata := jsonb_build_object('overrideId',new.id,'featureKey',new.feature_key,'effect',new.effect);
    if tg_op = 'INSERT' then v_type := 'entitlement_override.created';
    elsif new.revoked_at is distinct from old.revoked_at then v_type := 'entitlement_override.revoked'; end if;
  end if;
  if v_type is not null then
    insert into public.account_subscription_events(billing_account_id,subscription_id,event_type,from_status,to_status,actor_user_id,source,metadata)
    values(v_account_id,v_subscription_id,v_type,v_from,v_to,auth.uid(),v_source,v_metadata);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_billing_plan_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare event text;
begin
  event:=case new.status when 'requested' then 'requested' when 'provider_pending' then 'requested' when 'awaiting_payment' then 'awaiting_payment' when 'scheduled' then 'scheduled' when 'cancel_pending' then 'cancel_requested' when 'completed' then 'completed' when 'canceled' then 'canceled' when 'failed' then 'failed' else 'manual_review' end;
  insert into public.billing_plan_change_events(operation_id,event_type) values(new.id,'billing.plan_change_'||event) on conflict do nothing;
  if new.provider_applied_at is not null then insert into public.billing_plan_change_events(operation_id,event_type) values(new.id,'billing.plan_change_provider_applied') on conflict do nothing; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.auto_materialize_assigned_exercises()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.materialize_assigned_workout_exercises(NEW.id);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.workout_template_id IS DISTINCT FROM OLD.workout_template_id THEN
      PERFORM public.materialize_assigned_workout_exercises(NEW.id);
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.backfill_legacy_billing_accounts()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_scale uuid; v_growth uuid; v_policy uuid; v_owner uuid; v_account uuid;
begin
  select id into strict v_scale from public.commercial_plan_versions where plan_key = 'scale' and version = 1 and status = 'active';
  select id into strict v_growth from public.commercial_plan_versions where plan_key = 'growth' and version = 1 and status = 'active';
  select id into strict v_policy from public.commercial_trial_policy_versions where version = 1 and status = 'active' and feature_plan_version_id = v_growth;
  for v_owner in select distinct owner_user_id from public.workspaces where owner_user_id is not null order by owner_user_id loop
    v_account := public.ensure_commercial_billing_account(v_owner,'legacy_backfill');
    perform 1 from public.billing_accounts where id = v_account for update;
    if not exists(select 1 from public.account_subscriptions where billing_account_id = v_account) then
      insert into public.account_subscriptions(billing_account_id,plan_version_id,subscription_kind,status,source)
      values(v_account,v_scale,'complimentary','active','legacy_beta_backfill');
    end if;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_billing_plan_change(p_owner uuid, p_environment text, p_target_plan text, p_target_cadence text, p_operation uuid, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb; preview jsonb; b public.billing_provider_subscriptions%rowtype; s public.account_subscriptions%rowtype; m public.billing_provider_variant_mappings%rowtype; t public.billing_provider_variant_mappings%rowtype; o public.billing_plan_change_operations%rowtype;
begin
  -- BILLING-DB-02 BEGIN
  perform public.billing_guard_legacy_entry('legacy_plan',p_owner,p_environment,p_operation);
  -- BILLING-DB-02 END
  ctx:=public.billing_plan_change_context(p_owner,p_environment); b:=jsonb_populate_record(null::public.billing_provider_subscriptions,ctx-&gt;'subscription');
  perform 1 from public.billing_accounts where id=b.billing_account_id for update;
  select * into o from public.billing_plan_change_operations where billing_account_id=b.billing_account_id and operation_id=p_operation;
  if o.id is not null then
    if o.target_cadence&lt;&gt;p_target_cadence or not exists(select 1 from public.commercial_plan_versions where id=o.target_plan_version_id and plan_key=p_target_plan) then raise exception 'BILLING_PLAN_CHANGE_OPERATION_CONFLICT'; end if;
    return jsonb_build_object('id',o.id,'status',o.status,'dispatch',false);
  end if;
  preview:=public.preview_billing_plan_change(p_owner,p_environment,p_target_plan,p_target_cadence,p_snapshot);
  if (preview-&gt;&gt;'dataQualityIssue')::boolean then raise exception 'BILLING_PLAN_CHANGE_DATA_QUALITY_BLOCKED'; end if;
  if jsonb_array_length(preview-&gt;'blockers')&gt;0 then raise exception 'BILLING_PLAN_CHANGE_CAPACITY_BLOCKED'; end if;
  s:=jsonb_populate_record(null::public.account_subscriptions,ctx-&gt;'local'); m:=jsonb_populate_record(null::public.billing_provider_variant_mappings,ctx-&gt;'mapping');
  select v.* into strict t from public.billing_provider_variant_mappings v join public.commercial_plan_versions p on p.id=v.plan_version_id where p.plan_key=p_target_plan and p.status='active' and v.status='active' and v.cadence=p_target_cadence and v.environment=p_environment;
  insert into public.billing_plan_change_operations(billing_account_id,billing_provider_subscription_id,source_account_subscription_id,source_plan_version_id,source_variant_mapping_id,source_cadence,target_plan_version_id,target_variant_mapping_id,target_cadence,change_kind,effective_timing,proration_mode,operation_id,status,provider_payment_processor,preflight_snapshot,provider_requested_at,effective_at,created_by_user_id)
    values(b.billing_account_id,b.id,s.id,s.plan_version_id,m.id,m.cadence,t.plan_version_id,t.id,t.cadence,preview-&gt;&gt;'changeKind',preview-&gt;&gt;'effectiveTiming',preview-&gt;&gt;'prorationMode',p_operation,'provider_pending','card',public.billing_plan_change_preflight(p_owner,b.billing_account_id,t.plan_version_id)-&gt;'snapshot',clock_timestamp(),(preview-&gt;&gt;'effectiveAt')::timestamptz,p_owner) returning * into o;
  return jsonb_build_object('id',o.id,'status',o.status,'dispatch',true,'variant',t.provider_variant_id,'product',t.provider_product_id,'price',t.provider_price_id,'timing',o.effective_timing);
end $function$

CREATE OR REPLACE FUNCTION public.begin_billing_seat_quantity(p_owner uuid, p_environment text, p_target integer, p_operation uuid, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb; b public.billing_provider_subscriptions%rowtype; v jsonb; o public.billing_seat_quantity_operations%rowtype;
begin
  -- BILLING-DB-02 BEGIN
  perform public.billing_guard_legacy_entry('legacy_seat',p_owner,p_environment,p_operation);
  -- BILLING-DB-02 END
  ctx:=public.billing_seat_quantity_context(p_owner,p_environment);
  perform 1 from public.billing_accounts where id=(ctx#&gt;&gt;'{subscription,billing_account_id}')::uuid for update;
  ctx:=public.billing_seat_quantity_context(p_owner,p_environment); b:=jsonb_populate_record(null::public.billing_provider_subscriptions,ctx-&gt;'subscription');
  select * into o from public.billing_seat_quantity_operations where billing_account_id=b.billing_account_id and operation_id=p_operation;
  if o.id is not null then
    if o.target_additional_seats is distinct from p_target then raise exception 'BILLING_SEAT_QUANTITY_OPERATION_CONFLICT'; end if;
    return jsonb_build_object('id',o.id,'dispatch',false);
  end if;
  v:=public.preview_billing_seat_quantity(p_owner,p_environment,p_target,p_snapshot);
  if v-&gt;&gt;'errorCode' is not null then raise exception '%',v-&gt;&gt;'errorCode'; end if;
  if v-&gt;&gt;'direction'='no-op' then return jsonb_build_object('dispatch',false); end if;
  insert into public.billing_seat_quantity_operations(operation_id,billing_account_id,billing_provider_subscription_id,account_subscription_id,variant_mapping_id,quantity_price_contract_id,
    direction,effective_timing,source_additional_seats,target_additional_seats,source_quantity,target_quantity,source_effective_limit,target_effective_limit,status,proration_mode,preflight_snapshot,provider_requested_at,effective_at,created_by_user_id)
    values(p_operation,b.billing_account_id,b.id,b.account_subscription_id,b.variant_mapping_id,(select id from public.billing_quantity_price_contracts where variant_mapping_id=b.variant_mapping_id),
      v-&gt;&gt;'direction',v-&gt;&gt;'timing',b.approved_additional_coach_seats,p_target,b.quantity,1+p_target,(v-&gt;&gt;'currentEffectiveLimit')::integer,(v-&gt;&gt;'targetEffectiveLimit')::integer,'provider_pending',
      case when v-&gt;&gt;'direction'='increase' then 'invoice_immediately' else 'disable_prorations' end,
      jsonb_build_object('actual',v-&gt;'actual','pending',v-&gt;'pending','reserved',v-&gt;'reserved','committed',v-&gt;'committed'),clock_timestamp(),(v-&gt;&gt;'effectiveAt')::timestamptz,p_owner) returning * into o;
  return jsonb_build_object('id',o.id,'dispatch',true,'quantity',o.target_quantity,'timing',o.effective_timing);
end $function$

CREATE OR REPLACE FUNCTION public.begin_cancel_billing_plan_change(p_owner uuid, p_environment text, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb; o public.billing_plan_change_operations%rowtype; m public.billing_provider_variant_mappings%rowtype;
begin
  -- BILLING-DB-02 BEGIN
  perform public.billing_guard_legacy_entry('owner_effect',p_owner,p_environment);
  -- BILLING-DB-02 END
  ctx:=public.billing_plan_change_context(p_owner,p_environment);
  perform 1 from public.billing_accounts where id=(ctx#&gt;&gt;'{subscription,billing_account_id}')::uuid for update;
  select * into o from public.billing_plan_change_operations where operation_id=p_operation and created_by_user_id=p_owner and billing_provider_subscription_id=(ctx#&gt;&gt;'{subscription,id}')::uuid for update;
  if o.id is null or o.status&lt;&gt;'scheduled' or o.effective_at&lt;=clock_timestamp() then raise exception 'BILLING_PLAN_CHANGE_CANNOT_CANCEL'; end if;
  update public.billing_plan_change_operations set status='cancel_pending',updated_at=now() where id=o.id;
  select * into strict m from public.billing_provider_variant_mappings where id=o.source_variant_mapping_id;
  return jsonb_build_object('id',o.id,'status','cancel_pending','dispatch',true,'variant',m.provider_variant_id,'product',m.provider_product_id,'price',m.provider_price_id,'timing','period_end');
end $function$

CREATE OR REPLACE FUNCTION public.begin_cancel_billing_seat_quantity(p_owner uuid, p_environment text, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
