  when 'baseline_entries' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'checkins' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'client_coach_tasks' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'client_macro_targets' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'client_medical_documents' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'client_medical_records' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'client_program_assignments' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'client_programs' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'client_targets' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'habit_logs' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'nutrition_day_logs' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'workspace_client_onboardings' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'conversations' then select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid; return public.commercial_row_scope('clients',parent);
  when 'workout_templates' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'program_templates' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'checkin_templates' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'coach_activity_log' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'coach_calendar_events' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'coach_todos' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'invites' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'workspace_members' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'workspace_member_invites' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'workspace_member_client_assignments' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'workspace_invite_client_assignments' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'workspace_wearable_settings' then w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'pt_hub_profiles' then o:=(p_row-&gt;&gt;'user_id')::uuid;
  when 'pt_hub_settings' then o:=(p_row-&gt;&gt;'user_id')::uuid;
  when 'pt_profiles' then o:=(p_row-&gt;&gt;'user_id')::uuid;
  when 'pt_packages' then o:=(p_row-&gt;&gt;'pt_user_id')::uuid;
  when 'pt_hub_leads' then o:=(p_row-&gt;&gt;'user_id')::uuid;
  when 'lead_conversations' then o:=(p_row-&gt;&gt;'pt_user_id')::uuid;
  when 'clients' then c:=(p_row-&gt;&gt;'id')::uuid; w:=(p_row-&gt;&gt;'workspace_id')::uuid;
    if w is null then return jsonb_build_object('independent',true,'client',c); end if;
  when 'workspaces' then w:=(p_row-&gt;&gt;'id')::uuid; o:=(p_row-&gt;&gt;'owner_user_id')::uuid;
  when 'nutrition_templates' then
    if p_row-&gt;&gt;'owner_client_id' is not null then return jsonb_build_object('independent',true,'client',p_row-&gt;'owner_client_id'); end if;
    w:=(p_row-&gt;&gt;'workspace_id')::uuid;
  when 'assigned_nutrition_plans' then
    if exists(select 1 from public.nutrition_templates where id=(p_row-&gt;&gt;'nutrition_template_id')::uuid and owner_client_id is not null) then
      return jsonb_build_object('independent',true,'client',p_row-&gt;'client_id'); end if;
    select to_jsonb(x) into parent from public.clients x where id=(p_row-&gt;&gt;'client_id')::uuid;
    return public.commercial_row_scope('clients',parent);
  when 'exercises','baseline_marker_templates' then
    w:=(p_row-&gt;&gt;'workspace_id')::uuid; o:=(p_row-&gt;&gt;'owner_user_id')::uuid;
    if w is null and o=auth.uid() and not exists(select 1 from public.pt_profiles where user_id=o) then return jsonb_build_object('independent',true); end if;
  else raise exception 'Unclassified commercial write.' using errcode='42501';
  end case;
  if o is null then select owner_user_id into o from public.workspaces where id=w; end if;
  if o is null then return null; end if;
  return jsonb_build_object('owner',o,'workspace',w,'client',c,'independent',false);
end $function$

CREATE OR REPLACE FUNCTION public.commercial_storage_write_allowed(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c public.clients%rowtype; o uuid; first_part text:=split_part(p_name,'/',1);
begin
  if p_bucket not in ('baseline_photos','checkin-photos','medical_documents','workspace_branding') then return true; end if;
  if auth.uid() is null then return false; end if;
  if p_bucket='workspace_branding' then
    select owner_user_id into o from public.workspaces where id::text=first_part and public.can_manage_workspace_team(id);
    if o is null then return false; end if;
    return public.is_commercial_action_allowed(public.resolve_account_commercial_access(o)-&gt;&gt;'accessMode','business_configuration_write');
  end if;
  select * into c from public.clients where id::text=first_part;
  if c.id is null then return false; end if;
  if not (c.user_id=auth.uid() or public.can_access_client(c.id,'clients.view')) then return false; end if;
  if c.workspace_id is null or p_bucket='medical_documents' and c.user_id=auth.uid() then return c.user_id=auth.uid(); end if;
  select owner_user_id into o from public.workspaces where id=c.workspace_id;
  return public.is_commercial_action_allowed(public.resolve_account_commercial_access(o)-&gt;&gt;'accessMode','delivery_write');
end $function$

CREATE OR REPLACE FUNCTION public.complete_workspace_client_onboarding(p_client_id uuid, p_program_template_id uuid DEFAULT NULL::uuid, p_checkin_template_id uuid DEFAULT NULL::uuid, p_first_checkin_date date DEFAULT NULL::date, p_coach_review_notes text DEFAULT NULL::text)
 RETURNS public.workspace_client_onboardings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.workspace_client_onboardings;
  v_client public.clients%rowtype;
  v_baseline_id uuid;
  v_metrics public.baseline_metrics%rowtype;
  v_program_started_at timestamptz := null;
  v_checkin_scheduled_at timestamptz := null;
  v_checkin_start_date date := coalesce(p_first_checkin_date, current_date);
  v_checkin_workspace_id uuid;
  v_display_name text;
  v_goal text;
  v_injuries text;
  v_limitations text;
  v_equipment text;
  v_phone text;
  v_email text;
  v_location text;
  v_location_country text;
  v_timezone text;
  v_gender text;
  v_unit_preference text;
  v_training_type text;
  v_gym_name text;
  v_photo_url text;
  v_dob date;
  v_days_per_week integer;
  v_height_cm integer;
  v_current_weight numeric;
begin
  if p_client_id is null then
    raise exception 'Client is required';
  end if;

  select c.*
  into v_client
  from public.clients c
  where c.id = p_client_id
  limit 1;

  if v_client.id is null then
    raise exception 'Client not found';
  end if;

  select *
  into v_row
  from public.workspace_client_onboardings wco
  where wco.workspace_id = v_client.workspace_id
    and wco.client_id = p_client_id
  limit 1
  for update;

  if v_row.id is null then
    raise exception 'Onboarding row not found';
  end if;

  if not public.is_pt_workspace_member(v_row.workspace_id) then
    raise exception 'Not authorized';
  end if;

  v_baseline_id := v_row.initial_baseline_entry_id;

  if v_baseline_id is null then
    select be.id
    into v_baseline_id
    from public.baseline_entries be
    where be.client_id = p_client_id
      and be.status = 'submitted'
    order by coalesce(be.submitted_at, be.created_at) desc
    limit 1;
  end if;

  if v_baseline_id is null then
    raise exception 'Submitted baseline is required before completion';
  end if;

  if not exists (
    select 1
    from public.baseline_entries be
    where be.id = v_baseline_id
      and be.client_id = p_client_id
      and be.status = 'submitted'
  ) then
    raise exception 'Linked baseline must be submitted before completion';
  end if;

  select *
  into v_metrics
  from public.baseline_metrics bm
  where bm.baseline_id = v_baseline_id;

  if p_program_template_id is not null then
    perform public.assign_program_to_client(
      p_client_id,
      p_program_template_id,
      current_date,
      14
    );
    v_program_started_at := now();
  end if;

  if p_checkin_template_id is not null then
    select ct.workspace_id
    into v_checkin_workspace_id
    from public.checkin_templates ct
    where ct.id = p_checkin_template_id;

    if v_checkin_workspace_id is null then
      raise exception 'Check-in template not found';
    end if;

    if v_checkin_workspace_id &lt;&gt; v_client.workspace_id then
      raise exception 'Check-in template not found in workspace';
    end if;

    v_checkin_scheduled_at := now();
  end if;

  v_display_name := nullif(trim(coalesce(
    v_row.basics -&gt;&gt; 'display_name',
    v_client.display_name
  )), '');

  if coalesce(v_row.basics -&gt;&gt; 'dob', '') ~ '^\d{4}-\d{2}-\d{2}$' then
    v_dob := (v_row.basics -&gt;&gt; 'dob')::date;
  else
    v_dob := v_client.dob;
  end if;

  v_phone := nullif(trim(coalesce(v_row.basics -&gt;&gt; 'phone', v_client.phone)), '');
  v_email := nullif(trim(coalesce(v_row.basics -&gt;&gt; 'email', v_client.email)), '');
  v_location := nullif(trim(coalesce(v_row.basics -&gt;&gt; 'location', v_client.location)), '');
  v_location_country := nullif(trim(coalesce(v_row.basics -&gt;&gt; 'location_country', v_client.location_country)), '');
  v_timezone := nullif(trim(coalesce(v_row.basics -&gt;&gt; 'timezone', v_client.timezone)), '');
  v_gender := nullif(trim(coalesce(v_row.basics -&gt;&gt; 'gender', v_client.gender)), '');
  v_goal := nullif(trim(coalesce(v_row.goals -&gt;&gt; 'goal', v_client.goal)), '');
  v_injuries := nullif(trim(coalesce(v_row.injuries_limitations -&gt;&gt; 'injuries', v_client.injuries)), '');
  v_limitations := nullif(trim(coalesce(v_row.injuries_limitations -&gt;&gt; 'limitations', v_client.limitations)), '');
  v_equipment := nullif(trim(coalesce(v_row.training_history -&gt;&gt; 'equipment', v_client.equipment)), '');
  v_gym_name := nullif(trim(coalesce(
    v_row.training_history -&gt;&gt; 'gym_name',
    v_row.basics -&gt;&gt; 'gym_name',
    v_client.gym_name
  )), '');
  v_photo_url := nullif(trim(coalesce(v_row.basics -&gt;&gt; 'photo_url', v_client.photo_url)), '');

  v_unit_preference := lower(trim(coalesce(
    v_row.nutrition_lifestyle -&gt;&gt; 'unit_preference',
    v_row.basics -&gt;&gt; 'unit_preference',
    v_client.unit_preference
  )));
  if v_unit_preference not in ('metric', 'imperial') then
    v_unit_preference := v_client.unit_preference;
  end if;

  v_training_type := lower(trim(coalesce(
    v_row.training_history -&gt;&gt; 'training_type',
    v_client.training_type
  )));
  if v_training_type not in ('online', 'hybrid', 'in_person') then
    v_training_type := v_client.training_type;
  end if;

  if coalesce(
    v_row.goals -&gt;&gt; 'days_per_week',
    v_row.training_history -&gt;&gt; 'days_per_week',
    v_row.basics -&gt;&gt; 'days_per_week',
    ''
  ) ~ '^\d+$' then
    v_days_per_week := (
      coalesce(
        v_row.goals -&gt;&gt; 'days_per_week',
        v_row.training_history -&gt;&gt; 'days_per_week',
        v_row.basics -&gt;&gt; 'days_per_week'
      )
    )::integer;
  else
    v_days_per_week := v_client.days_per_week;
  end if;

  if coalesce(
    v_row.basics -&gt;&gt; 'height_cm',
    ''
  ) ~ '^-?\d+(\.\d+)?$' then
    v_height_cm := round((v_row.basics -&gt;&gt; 'height_cm')::numeric)::integer;
  elsif v_metrics.height_cm is not null then
    v_height_cm := round(v_metrics.height_cm)::integer;
  else
    v_height_cm := v_client.height_cm;
  end if;

  if coalesce(
    v_row.basics -&gt;&gt; 'current_weight',
    ''
  ) ~ '^-?\d+(\.\d+)?$' then
    v_current_weight := (v_row.basics -&gt;&gt; 'current_weight')::numeric;
  elsif v_metrics.weight_kg is not null then
    v_current_weight := v_metrics.weight_kg;
  else
    v_current_weight := v_client.current_weight;
  end if;

  update public.clients
  set
    display_name = coalesce(v_display_name, display_name),
    goal = coalesce(v_goal, goal),
    injuries = coalesce(v_injuries, injuries),
    equipment = coalesce(v_equipment, equipment),
    height_cm = coalesce(v_height_cm, height_cm),
    dob = coalesce(v_dob, dob),
    phone = coalesce(v_phone, phone),
    email = coalesce(v_email, email),
    location = coalesce(v_location, location),
    timezone = coalesce(v_timezone, timezone),
    unit_preference = coalesce(v_unit_preference, unit_preference),
    gender = coalesce(v_gender, gender),
    training_type = coalesce(v_training_type, training_type),
    gym_name = coalesce(v_gym_name, gym_name),
    photo_url = coalesce(v_photo_url, photo_url),
    limitations = coalesce(v_limitations, limitations),
    location_country = coalesce(v_location_country, location_country),
    days_per_week = coalesce(v_days_per_week, days_per_week),
    current_weight = coalesce(v_current_weight, current_weight),
    checkin_template_id = coalesce(p_checkin_template_id, checkin_template_id),
    checkin_start_date = case
      when p_checkin_template_id is not null then v_checkin_start_date
      else checkin_start_date
    end,
    updated_at = now()
  where id = p_client_id;

  update public.workspace_client_onboardings
  set
    initial_baseline_entry_id = coalesce(initial_baseline_entry_id, v_baseline_id),
    coach_review_notes = coalesce(p_coach_review_notes, coach_review_notes),
    first_program_template_id = coalesce(p_program_template_id, first_program_template_id),
    first_program_applied_at = coalesce(v_program_started_at, first_program_applied_at),
    first_checkin_template_id = coalesce(p_checkin_template_id, first_checkin_template_id),
    first_checkin_date = coalesce(
      case when p_checkin_template_id is not null then v_checkin_start_date else null end,
      first_checkin_date
    ),
    first_checkin_scheduled_at = coalesce(v_checkin_scheduled_at, first_checkin_scheduled_at),
    reviewed_by_user_id = auth.uid(),
    submitted_at = coalesce(submitted_at, now()),
    reviewed_at = coalesce(reviewed_at, now()),
    activated_at = coalesce(activated_at, now()),
    completed_at = coalesce(completed_at, now()),
    status = 'completed'
  where id = v_row.id
  returning *
  into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.converted_lead_history_for_conversation(p_conversation_id uuid)
 RETURNS TABLE(lead_conversation_id uuid, lead_id uuid, message_id uuid, sender_user_id uuid, body text, sent_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_conversation record;
  v_context record;
  v_can_read_history boolean := false;
begin
  if v_actor_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if p_conversation_id is null then
    return;
  end if;

  if not public.can_access_conversation(p_conversation_id, 'clients.message') then
    return;
  end if;

  select conv.id, conv.workspace_id, conv.client_id
  into v_conversation
  from public.conversations conv
  where conv.id = p_conversation_id
  limit 1;

  if not found then
    return;
  end if;

  if exists (
    select 1
    from public.clients c
    where c.id = v_conversation.client_id
      and c.workspace_id = v_conversation.workspace_id
      and c.user_id = v_actor_user_id
      and c.status = 'active'::public.client_status
  ) then
    v_can_read_history := true;
  else
    select *
    into v_context
    from public.workspace_access_context(v_conversation.workspace_id)
    limit 1;

    if found
       and v_context.role in ('owner', 'admin')
       and public.has_workspace_permission(
         v_context.role,
         v_context.member_status,
         'clients.message'
       ) then
      v_can_read_history := true;
    end if;
  end if;

  if not v_can_read_history then
    return;
  end if;

  return query
  select
    lc.id as lead_conversation_id,
    lead.id as lead_id,
    lm.id as message_id,
    lm.sender_user_id,
    lm.body,
    lm.sent_at
  from public.lead_conversations lc
  join public.pt_hub_leads lead
    on lead.id = lc.lead_id
   and lead.status = 'converted'
   and lead.converted_workspace_id = v_conversation.workspace_id
   and lead.converted_client_id = v_conversation.client_id
  join public.lead_messages lm
    on lm.conversation_id = lc.id
  where lc.converted_conversation_id = v_conversation.id
    and lc.archived_reason = 'converted'
  order by lm.sent_at asc, lm.id asc;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_invite(p_workspace_id uuid, p_max_uses integer DEFAULT 1, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(code text, invite_link text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_code text;
begin
  -- Only allow PTs in the workspace to create invites
  if not exists (
    select 1 from public.workspace_members wm
    where wm.user_id = auth.uid()
      and wm.workspace_id = p_workspace_id
  ) then
    raise exception 'Not allowed to create invites for this workspace';
  end if;

  -- Generate a simple 8-char code (retry if collision)
  loop
    v_code := upper(substr(encode(gen_random_bytes(6), 'base64'), 1, 8));
    v_code := replace(replace(v_code, '+', 'A'), '/', 'B');

    exit when not exists (select 1 from public.invites i where i.code = v_code);
  end loop;

  insert into public.invites (workspace_id, code, max_uses, uses, expires_at, created_by_user_id)
  values (p_workspace_id, v_code, greatest(p_max_uses, 1), 0, p_expires_at, auth.uid());

  return query
  select
    v_code as code,
    (current_setting('request.headers', true)::json-&gt;&gt;'origin') || '/join/' || v_code as invite_link;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_my_pt_package(p_input jsonb)
 RETURNS public.pt_packages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.pt_packages;
begin
  if auth.uid() is null or not exists(select 1 from public.pt_profiles where user_id=auth.uid()) then
    raise exception 'PT authentication required.' using errcode='42501';
  end if;
  insert into public.pt_packages(pt_user_id,title,subtitle,description,price_label,currency_code,
    billing_cadence_label,cta_label,features,status,is_public,sort_order)
  values(auth.uid(),p_input-&gt;&gt;'title',p_input-&gt;&gt;'subtitle',p_input-&gt;&gt;'description',p_input-&gt;&gt;'price_label',
    p_input-&gt;&gt;'currency_code',p_input-&gt;&gt;'billing_cadence_label',p_input-&gt;&gt;'cta_label',p_input-&gt;'features',
    coalesce(p_input-&gt;&gt;'status','draft'),coalesce((p_input-&gt;&gt;'is_public')::boolean,false),
    coalesce((p_input-&gt;&gt;'sort_order')::integer,0)) returning * into r;
  return r;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_workspace(p_name text)
 RETURNS TABLE(workspace_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_variable
declare
  v_user_id uuid;
  v_workspace_id uuid;
  v_name text;
  v_member_id uuid;
  v_profile_id uuid;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  perform public.enforce_rate_limit(
    'workspace_create_burst',
    1,
    60,
    v_user_id,
    null,
    null,
    'Please wait a minute before creating another workspace.'
  );

  perform public.enforce_rate_limit(
    'workspace_create_daily',
    3,
    86400,
    v_user_id,
    null,
    null,
    'You have reached the workspace creation limit for today.'
  );

  v_name := nullif(trim(p_name), '');
  if v_name is null then
    raise exception 'Workspace name is required';
  end if;

  if not exists(select 1 from public.pt_profiles where user_id=v_user_id) then
    raise exception 'PT authentication required.' using errcode='42501';
  end if;

  insert into public.workspaces (name, owner_user_id)
  values (v_name, v_user_id)
  returning id into v_workspace_id;

  select wm.id
  into v_member_id
  from public.workspace_members wm
  where wm.workspace_id = v_workspace_id
    and wm.user_id = v_user_id
  limit 1
  for update;

  if v_member_id is null then
    insert into public.workspace_members (workspace_id, user_id, role)
    values (v_workspace_id, v_user_id, 'pt_owner');
  else
    update public.workspace_members wm
    set role = 'pt_owner'
    where wm.id = v_member_id;
  end if;

  select pp.id
  into v_profile_id
  from public.pt_profiles pp
  where pp.user_id = v_user_id
    and pp.workspace_id = v_workspace_id
  limit 1
  for update;

  if v_profile_id is null then
    insert into public.pt_profiles (user_id, workspace_id)
    values (v_user_id, v_workspace_id);
  end if;

  workspace_id := v_workspace_id;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_workspace_team_invite(p_workspace_id uuid, p_email text, p_role text DEFAULT 'assistant_coach'::text, p_client_access_mode text DEFAULT 'assigned_clients_only'::text, p_client_ids uuid[] DEFAULT '{}'::uuid[], p_base_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_email text := lower(trim(coalesce(p_email, '')));
  v_role text := trim(coalesce(p_role, ''));
  v_client_access_mode text := trim(coalesce(p_client_access_mode, ''));
  v_client_ids uuid[] := coalesce(p_client_ids, '{}'::uuid[]);
  v_distinct_client_ids uuid[];
  v_valid_client_count int;
  v_token text;
  v_token_hash text;
  v_invite public.workspace_member_invites%rowtype;
  v_workspace_name text;
  v_owner_name text;
  v_base_url text := nullif(regexp_replace(trim(coalesce(p_base_url, '')), '/+$', ''), '');
  v_accept_url text;
begin
  if v_actor_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  if not public.can_manage_workspace_team(p_workspace_id) then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  if (
    select count(*)
    from public.workspace_member_invites wmi
    where wmi.workspace_id = p_workspace_id
      and wmi.invited_by_user_id = v_actor_user_id
      and wmi.created_at &gt; now() - interval '15 minutes'
  ) &gt;= 20 then
    perform public.workspace_team_operational_error('RATE_LIMITED');
  end if;

  if v_email = '' or position('@' in v_email) = 0 then
    perform public.workspace_team_invite_error('INVALID_INVITE_EMAIL');
  end if;

  if v_role not in ('admin', 'coach', 'assistant_coach', 'viewer') then
    perform public.workspace_team_invite_error('INVALID_INVITE_ROLE');
  end if;

  if v_client_access_mode not in ('all_clients', 'assigned_clients_only') then
    perform public.workspace_team_invite_error('INVALID_CLIENT_ACCESS_MODE');
  end if;

  if exists (
    select 1
    from public.workspace_member_invites wmi
    where wmi.workspace_id = p_workspace_id
      and lower(wmi.email) = v_email
      and wmi.status = 'pending'
  ) then
    perform public.record_workspace_team_audit_event(
      p_workspace_id,
      v_actor_user_id,
      'team.duplicate_pending_invite_attempt',
      'workspace_member_invite',
      null,
      v_email,
      jsonb_build_object('role', v_role)
    );
    perform public.workspace_team_invite_error('DUPLICATE_PENDING_INVITE');
  end if;

  if exists (
    select 1
    from auth.users u
    join public.workspace_members wm
      on wm.user_id = u.id
    where wm.workspace_id = p_workspace_id
      and wm.status = 'active'
      and lower(u.email) = v_email
  ) then
    perform public.workspace_team_invite_error('USER_ALREADY_WORKSPACE_MEMBER');
  end if;

  select coalesce(array_agg(distinct client_id), '{}'::uuid[])
  into v_distinct_client_ids
  from unnest(v_client_ids) as client_id
  where client_id is not null;

  if cardinality(v_distinct_client_ids) &gt; 0 then
    select count(*)
    into v_valid_client_count
    from public.clients c
    where c.workspace_id = p_workspace_id
      and c.id = any(v_distinct_client_ids);

    if v_valid_client_count is distinct from cardinality(v_distinct_client_ids) then
      perform public.workspace_team_invite_error('INVALID_CLIENT_ASSIGNMENT');
    end if;
  end if;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_token_hash := public.hash_workspace_team_invite_token(v_token);

  insert into public.workspace_member_invites (
    workspace_id,
    email,
    role,
    client_access_mode,
    token_hash,
    status,
    invited_by_user_id,
    expires_at
  )
  values (
    p_workspace_id,
    v_email,
    v_role,
    v_client_access_mode,
    v_token_hash,
    'pending',
    v_actor_user_id,
    now() + interval '14 days'
  )
  returning * into v_invite;

  insert into public.workspace_invite_client_assignments (
    invite_id,
    workspace_id,
    client_id,
    assigned_by_user_id
  )
  select
    v_invite.id,
    p_workspace_id,
    client_id,
    v_actor_user_id
  from unnest(v_distinct_client_ids) as client_id
  on conflict (invite_id, client_id) do nothing;

  select w.name
  into v_workspace_name
  from public.workspaces w
  where w.id = p_workspace_id;

  select coalesce(pp.display_name, pp.full_name, u.email)
  into v_owner_name
  from auth.users u
  left join public.pt_profiles pp
    on pp.user_id = u.id
  where u.id = v_actor_user_id
  order by pp.updated_at desc nulls last
  limit 1;

  v_accept_url := coalesce(v_base_url, '') || '/team-invites/' || v_token;

  perform public.set_workspace_team_invite_notification_route(
    v_invite.id,
    v_token
  );

  perform public.queue_workspace_team_email(
    p_workspace_id,
    v_invite.id,
    v_email,
    'team_invite_received',
    'workspace_team_invite',
    jsonb_build_object(
      'workspaceName', v_workspace_name,
      'ownerName', v_owner_name,
      'role', v_role,
      'expiresAt', v_invite.expires_at,
      'mustUseEmail', v_email
    ),
    'workspace-team-invite:' || v_invite.id::text || ':created'
  );

  perform public.record_workspace_team_audit_event(
    p_workspace_id,
    v_actor_user_id,
    'team.invite_created',
    'workspace_member_invite',
    v_invite.id,
    v_email,
    jsonb_build_object(
      'role', v_role,
      'clientAccessMode', v_client_access_mode,
      'clientIds', v_distinct_client_ids,
      'clientCount', cardinality(v_distinct_client_ids),
      'expiresAt', v_invite.expires_at,
      'emailQueued', true
    )
  );

  return jsonb_build_object(
    'inviteId', v_invite.id,
    'workspaceId', p_workspace_id,
    'workspaceName', v_workspace_name,
    'invitedEmail', v_email,
    'role', v_role,
    'clientAccessMode', v_client_access_mode,
    'status', v_invite.status,
    'expiresAt', v_invite.expires_at,
    'acceptUrl', v_accept_url,
    'email', jsonb_build_object(
      'to', v_email,
      'subject', coalesce(v_owner_name, 'A coach') || ' invited you to join ' || coalesce(v_workspace_name, 'a RepSync workspace'),
      'text', concat_ws(E'\n\n',
        coalesce(v_owner_name, 'A coach') || ' invited you to join ' || coalesce(v_workspace_name, 'a RepSync workspace') || ' on RepSync as ' || v_role || '.',
        'Accept invite: ' || v_accept_url,
        'This invite expires on ' || v_invite.expires_at::text || '.',
        'You must sign in or create a RepSync account with ' || v_email || ' to accept.'
      )
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.decline_workspace_team_invite(p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_user_email text;
  v_invite public.workspace_member_invites%rowtype;
begin
  if v_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  select lower(email)
    into v_user_email
    from auth.users
   where id = v_user_id;

  select *
    into v_invite
    from public.workspace_member_invites wmi
   where wmi.id = p_invite_id
   for update;

  if not found then
    perform public.workspace_team_invite_error('INVITE_NOT_FOUND');
  end if;

  if lower(v_invite.email) &lt;&gt; v_user_email then
    perform public.workspace_team_invite_error('INVITE_EMAIL_MISMATCH');
  end if;

  if v_invite.status &lt;&gt; 'pending' then
    perform public.workspace_team_invite_error('INVITE_NOT_PENDING');
  end if;

  update public.workspace_member_invites
     set status = 'declined'
   where id = v_invite.id
   returning * into v_invite;

  update public.workspace_team_email_deliveries
     set status = 'cancelled',
         updated_at = now()
   where invite_id = v_invite.id
     and status in ('queued', 'sending');

  update public.notification_deliveries nd
     set read_at = coalesce(read_at, now()),
         archived_at = coalesce(archived_at, now()),
         updated_at = now()
    from public.notification_events ne
   where nd.event_id = ne.id
     and nd.recipient_user_id = v_user_id
     and ne.entity_type = 'workspace_member_invite'
     and ne.entity_id = v_invite.id::text
     and ne.type = 'team_invite_received'
     and nd.channel = 'in_app';

  perform public.record_workspace_team_audit_event(
    v_invite.workspace_id,
    v_user_id,
    'team.invite_declined',
    'workspace_member_invite',
    v_invite.id,
    v_invite.email,
    '{}'::jsonb
  );

  perform public.notify_workspace_team_user(
    v_invite.workspace_id,
    v_invite.invited_by_user_id,
    'team_invite_declined',
    'Workspace invite declined',
    v_invite.email || ' declined the workspace invite.',
    '/workspace/' || v_invite.workspace_id::text || '/settings/team',
    'workspace_member_invite',
    v_invite.id,
    '{}'::jsonb
  );

  return jsonb_build_object(
    'inviteId', v_invite.id,
    'workspaceId', v_invite.workspace_id,
    'status', v_invite.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_pt_package_guarded(p_package_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor_user_id uuid;
  v_package record;
  v_reference_count bigint;
begin
  v_actor_user_id := auth.uid();
  if v_actor_user_id is null then
    raise exception 'Not allowed to delete this package.'
      using errcode = '42501', detail = 'FORBIDDEN';
  end if;

  select
    pkg.id,
    pkg.pt_user_id
  into v_package
  from public.pt_packages pkg
  where pkg.id = p_package_id
  limit 1;

  if not found then
    raise exception 'Package not found.'
      using errcode = 'P0001', detail = 'PACKAGE_NOT_FOUND';
  end if;

  if v_package.pt_user_id &lt;&gt; v_actor_user_id then
    raise exception 'Not allowed to delete this package.'
      using errcode = '42501', detail = 'FORBIDDEN';
  end if;

  select count(*)
  into v_reference_count
  from public.pt_hub_leads lead
  where lead.package_interest_id = v_package.id;

  if v_reference_count &gt; 0 then
    raise exception 'Package is referenced by existing leads. Archive it instead.'
      using errcode = 'P0001', detail = 'PACKAGE_DELETE_BLOCKED_REFERENCED';
  end if;

  delete from public.pt_packages pkg
  where pkg.id = v_package.id
    and pkg.pt_user_id = v_actor_user_id;

  return v_package.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.draft_paddle_catalogue_mapping_v1(p_evidence_id uuid, p_digest text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare e public.billing_catalogue_evidence_v1%rowtype; c jsonb; m public.billing_price_mappings%rowtype;
begin
  perform public.billing_catalogue_authorize_v1();
  select * into e from public.billing_catalogue_evidence_v1 where id=p_evidence_id;
  if not found or p_digest is distinct from e.normalized_sha256::text then raise exception 'BILLING_CATALOGUE_EVIDENCE_REQUIRED'; end if;
  if e.environment&lt;&gt;'test' then raise exception 'BILLING_CATALOGUE_ENVIRONMENT'; end if;
  perform pg_advisory_xact_lock(hashtextextended('paddle-catalogue-publication-v1:test',0));
  c:=e.proof-&gt;'catalogue';
  select * into m from public.billing_price_mappings where provider=e.provider and environment=e.environment and provider_price_ref=e.provider_price_ref for update;
  if found then
    if m.status&lt;&gt;'draft' then raise exception 'BILLING_CATALOGUE_NOT_DRAFT'; end if;
    -- Never repurpose a price already claimed by a different canonical identity,
    -- even while draft. Refreshing evidence for the same draft is permitted.
    if (m.identity_kind,m.canonical_key,m.cadence,coalesce(m.plan_version_id,m.addon_version_id),m.provider_product_ref::text)
      is distinct from (c-&gt;&gt;'identityKind',c-&gt;&gt;'canonicalKey',c-&gt;&gt;'cadence',(c-&gt;&gt;'canonicalVersionId')::uuid,c-&gt;&gt;'productRef') then raise exception 'BILLING_CATALOGUE_PRICE_CLAIMED'; end if;
    update public.billing_price_mappings set catalogue_evidence_id=e.id,verification_evidence_id=null,verification_sha256=e.normalized_sha256,verified_at=e.observed_at,updated_at=clock_timestamp() where id=m.id returning * into m;
  else
    insert into public.billing_price_mappings(provider,environment,identity_kind,canonical_key,plan_version_id,addon_version_id,cadence,
      provider_product_ref,provider_price_ref,currency_code,unit_amount_minor,recurrence_unit,recurrence_count,
      catalogue_evidence_id,verification_sha256,verified_at,status)
    values(e.provider,e.environment,c-&gt;&gt;'identityKind',c-&gt;&gt;'canonicalKey',case when c-&gt;&gt;'identityKind'='plan' then (c-&gt;&gt;'canonicalVersionId')::uuid end,
      case when c-&gt;&gt;'identityKind'='addon' then (c-&gt;&gt;'canonicalVersionId')::uuid end,c-&gt;&gt;'cadence',c-&gt;&gt;'productRef',c-&gt;&gt;'priceRef',c-&gt;&gt;'currency',
      (c-&gt;&gt;'unitAmountMinor')::bigint,c-&gt;&gt;'recurrenceUnit',(c-&gt;&gt;'recurrenceCount')::integer,e.id,e.normalized_sha256,e.observed_at,'draft') returning * into m;
  end if;
  perform public.billing_catalogue_assert_mapping_v1(m);
  return m.id;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_assigned_nutrition_item_client_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_is_owner_client boolean;
  v_is_pt boolean;
begin
  select exists (
    select 1
    from public.assigned_nutrition_days andy
    where andy.id = old.assigned_nutrition_day_id
      and public.is_client_owner(andy.client_id)
  ) into v_is_owner_client;

  v_is_pt := public.is_pt_workspace_member(old.workspace_id);

  if v_is_pt then
    return new;
  end if;

  if v_is_owner_client then
    if new.id is distinct from old.id
      or new.workspace_id is distinct from old.workspace_id
      or new.assigned_nutrition_day_id is distinct from old.assigned_nutrition_day_id
      or new.assigned_nutrition_meal_id is distinct from old.assigned_nutrition_meal_id
      or new.template_meal_item_id is distinct from old.template_meal_item_id
      or new.name is distinct from old.name
      or new.serving_label is distinct from old.serving_label
      or new.quantity is distinct from old.quantity
      or new.planned_calories is distinct from old.planned_calories
      or new.planned_protein_g is distinct from old.planned_protein_g
      or new.planned_carbs_g is distinct from old.planned_carbs_g
      or new.planned_fat_g is distinct from old.planned_fat_g
      or new.sort_order is distinct from old.sort_order
      or new.notes is distinct from old.notes
      or new.created_at is distinct from old.created_at then
      raise exception 'Clients can only update actual macro fields and is_completed';
    end if;

    return new;
  end if;

  raise exception 'Not authorized to update assigned nutrition item';
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_checkin_write_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_id uuid;
begin
  if new.week_ending_saturday is not null then
    new.week_ending_saturday := public.normalize_checkin_due_date(new.week_ending_saturday);
  end if;

  if (new.reviewed_at is null) &lt;&gt; (new.reviewed_by_user_id is null) then
    raise exception 'Review metadata must be set together';
  end if;

  v_client_id := coalesce(new.client_id, old.client_id);

  if tg_op = 'INSERT' then
    if (
      new.pt_feedback is not null
      or new.reviewed_at is not null
      or new.reviewed_by_user_id is not null
    ) and not public.can_write_client_delivery(v_client_id) then
      raise exception 'Only workspace members with client edit access can write check-in review metadata';
    end if;

    if new.submitted_at is null and (
      new.reviewed_at is not null
      or new.reviewed_by_user_id is not null
    ) then
      raise exception 'Check-ins cannot be reviewed before submission';
    end if;

    if new.submitted_at is not null then
      perform public.validate_checkin_submission_requirements(new.id);
    end if;

    return new;
  end if;

  if old.submitted_at is not null then
    if new.client_id is distinct from old.client_id
       or new.template_id is distinct from old.template_id
       or new.week_ending_saturday is distinct from old.week_ending_saturday
       or new.submitted_at is distinct from old.submitted_at
       or new.created_at is distinct from old.created_at then
      raise exception 'Submitted check-ins are immutable';
    end if;

    if (
      new.pt_feedback is distinct from old.pt_feedback
      or new.reviewed_at is distinct from old.reviewed_at
      or new.reviewed_by_user_id is distinct from old.reviewed_by_user_id
    ) and not public.can_write_client_delivery(v_client_id) then
      raise exception 'Only workspace members with client edit access can review submitted check-ins';
    end if;

    if old.reviewed_at is not null and new.reviewed_at is distinct from old.reviewed_at then
      raise exception 'Reviewed check-ins cannot be unreviewed or re-timestamped';
    end if;

    if old.reviewed_by_user_id is not null
       and new.reviewed_by_user_id is distinct from old.reviewed_by_user_id then
      raise exception 'Reviewed check-ins cannot change reviewer metadata';
    end if;

    return new;
  end if;

  if (
    new.pt_feedback is distinct from old.pt_feedback
    or new.reviewed_at is distinct from old.reviewed_at
    or new.reviewed_by_user_id is distinct from old.reviewed_by_user_id
  ) and not public.can_write_client_delivery(v_client_id) then
    raise exception 'Only workspace members with client edit access can write coach review metadata';
  end if;

  if old.submitted_at is null and new.submitted_at is not null then
    perform public.validate_checkin_submission_requirements(new.id);
  end if;

  if new.submitted_at is null and (
    new.reviewed_at is not null
    or new.reviewed_by_user_id is not null
  ) then
    raise exception 'Check-ins cannot be reviewed before submission';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_client_medical_document_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if coalesce(new.file_name, '') = '' then
    raise exception 'A document file name is required.';
  end if;

  if new.file_size is not null and new.file_size &gt; 15728640 then
    raise exception 'Medical documents must be 15 MB or smaller.';
  end if;

  if new.mime_type is not null and new.mime_type &lt;&gt; all (array[
    'application/pdf',
    'image/jpeg',
    'image/png',
    'image/webp',
    'image/heic',
    'image/heif'
  ]) then
    raise exception 'Unsupported medical document type.';
  end if;

  perform public.enforce_rate_limit(
    'medical_document_insert_hourly',
    10,
    3600,
    v_user_id,
    null,
    new.client_id::text,
    'You have reached the medical document upload limit for now. Please try again later.'
  );

  return new;
end;
$function$

