$function$

CREATE OR REPLACE FUNCTION public.enforce_rate_limit(p_action text, p_max_attempts integer, p_window_seconds integer, p_actor_user_id uuid DEFAULT NULL::uuid, p_actor_key text DEFAULT NULL::text, p_target_key text DEFAULT NULL::text, p_error_message text DEFAULT 'Rate limit exceeded. Please try again later.'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_existing_count integer;
begin
  if coalesce(p_action, '') = '' then
    raise exception 'Rate limit action is required';
  end if;

  if coalesce(p_max_attempts, 0) &lt;= 0 or coalesce(p_window_seconds, 0) &lt;= 0 then
    return;
  end if;

  if p_actor_user_id is null
     and nullif(btrim(coalesce(p_actor_key, '')), '') is null
     and nullif(btrim(coalesce(p_target_key, '')), '') is null then
    raise exception 'Rate limit requires at least one actor or target key';
  end if;

  select count(*)
  into v_existing_count
  from public.rate_limit_events event
  where event.action = p_action
    and event.created_at &gt;= now() - make_interval(secs =&gt; p_window_seconds)
    and (
      (p_actor_user_id is not null and event.actor_user_id = p_actor_user_id)
      or (nullif(btrim(coalesce(p_actor_key, '')), '') is not null and event.actor_key = p_actor_key)
      or (nullif(btrim(coalesce(p_target_key, '')), '') is not null and event.target_key = p_target_key)
    );

  if v_existing_count &gt;= p_max_attempts then
    raise exception using message = p_error_message;
  end if;

  insert into public.rate_limit_events (
    action,
    actor_user_id,
    actor_key,
    target_key,
    metadata
  ) values (
    p_action,
    p_actor_user_id,
    nullif(btrim(coalesce(p_actor_key, '')), ''),
    nullif(btrim(coalesce(p_target_key, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_client_checkins(p_client_id uuid, p_range_start date, p_range_end date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_workspace_id uuid;
begin
  if p_client_id is null then
    raise exception 'Client is required';
  end if;

  select c.workspace_id
  into v_workspace_id
  from public.clients c
  where c.id = p_client_id;

  if v_workspace_id is null then
    raise exception 'Client not found';
  end if;

  if public.is_client_owner(p_client_id)
     or public.can_write_client_delivery(p_client_id) then
    if not coalesce((public.get_client_coaching_access(p_client_id)-&gt;&gt;'canSubmitCheckin')::boolean,false) then return; end if;
    perform public.reconcile_client_checkins(
      p_client_id,
      p_range_start,
      p_range_end
    );
    return;
  end if;

  if public.can_access_client(p_client_id, 'clients.view') then
    return;
  end if;

  raise exception 'Not authorized';
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_commercial_billing_account(p_owner_user_id uuid, p_created_source text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_id uuid; v_intent text;
begin
  select id into v_id from public.billing_accounts where owner_user_id = p_owner_user_id;
  if v_id is not null then return v_id; end if;
  -- Auth metadata is used only as non-privileged plan intent, never authorization.
  select lower(btrim(raw_user_meta_data-&gt;&gt;'requested_plan')) into v_intent from auth.users where id = p_owner_user_id;
  insert into public.billing_accounts(owner_user_id,requested_plan_key,requested_plan_source,created_source)
  values(p_owner_user_id,case when v_intent in ('launch','growth','scale') then v_intent else 'growth' end,
    case when p_created_source = 'legacy_backfill' then 'legacy_backfill'
      when v_intent in ('launch','growth','scale') then 'signup_metadata' else 'default' end,p_created_source)
  on conflict (owner_user_id) do nothing returning id into v_id;
  if v_id is null then select id into strict v_id from public.billing_accounts where owner_user_id = p_owner_user_id; end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_lead_conversation_for_lead(p_lead_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor_user_id uuid;
  v_lead public.pt_hub_leads%rowtype;
  v_conversation public.lead_conversations%rowtype;
  v_now timestamptz := now();
  v_should_open boolean;
  v_archive_reason text;
  v_previous_status text;
begin
  if p_lead_id is null then
    return null;
  end if;

  select *
  into v_lead
  from public.pt_hub_leads lead
  where lead.id = p_lead_id
  for update;

  if not found or v_lead.applicant_user_id is null then
    return null;
  end if;

  v_actor_user_id := auth.uid();
  if v_actor_user_id is not null
     and v_actor_user_id &lt;&gt; v_lead.user_id
     and v_actor_user_id &lt;&gt; v_lead.applicant_user_id then
    raise exception 'Not allowed to access this lead conversation';
  end if;

  v_should_open := public.lead_chat_is_open_lead_status(v_lead.status);

  if not v_should_open then
    v_archive_reason := case
      when v_lead.status = 'converted' then 'converted'
      when v_lead.status = 'declined' then 'declined'
      else 'manual'
    end;
  end if;

  select *
  into v_conversation
  from public.lead_conversations c
  where c.lead_id = v_lead.id
  for update;

  if not found then
    insert into public.lead_conversations (
      lead_id,
      pt_user_id,
      lead_user_id,
      status,
      archived_reason,
      archived_at
    )
    values (
      v_lead.id,
      v_lead.user_id,
      v_lead.applicant_user_id,
      case when v_should_open then 'open' else 'archived' end,
      case when v_should_open then null else v_archive_reason end,
      case when v_should_open then null else v_now end
    )
    returning * into v_conversation;

    perform public.log_lead_chat_event(
      v_lead.id,
      v_conversation.id,
      null,
      'lead_conversation_created',
      jsonb_build_object('status', v_conversation.status)
    );

    if v_conversation.status = 'archived' and v_archive_reason in ('converted', 'declined') then
      perform public.log_lead_chat_event(
        v_lead.id,
        v_conversation.id,
        null,
        case
          when v_archive_reason = 'converted' then 'lead_conversation_archived_converted'
          else 'lead_conversation_archived_declined'
        end,
        jsonb_build_object('reason', v_archive_reason)
      );
    end if;
  else
    v_previous_status := v_conversation.status;

    update public.lead_conversations c
    set
      pt_user_id = v_lead.user_id,
      lead_user_id = v_lead.applicant_user_id,
      status = case when v_should_open then 'open' else 'archived' end,
      archived_reason = case when v_should_open then null else v_archive_reason end,
      archived_at = case
        when v_should_open then null
        else coalesce(c.archived_at, v_now)
      end
    where c.id = v_conversation.id
    returning * into v_conversation;

    if v_previous_status = 'open' and v_conversation.status = 'archived' then
      perform public.log_lead_chat_event(
        v_lead.id,
        v_conversation.id,
        null,
        case
          when v_archive_reason = 'converted' then 'lead_conversation_archived_converted'
          when v_archive_reason = 'declined' then 'lead_conversation_archived_declined'
          else 'lead_conversation_archived_manual'
        end,
        jsonb_build_object('reason', v_archive_reason)
      );
    end if;
  end if;

  insert into public.lead_conversation_participants (conversation_id, user_id, role)
  values (v_conversation.id, v_lead.user_id, 'pt')
  on conflict (conversation_id, user_id) do update
    set role = 'pt';

  insert into public.lead_conversation_participants (conversation_id, user_id, role)
  values (v_conversation.id, v_lead.applicant_user_id, 'lead')
  on conflict (conversation_id, user_id) do update
    set role = 'lead';

  return v_conversation.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_pt_conversation(p_workspace_id uuid, p_client_id uuid)
 RETURNS TABLE(id uuid, client_id uuid, workspace_id uuid, last_message_at timestamp with time zone, last_message_preview text, last_message_sender_name text, last_message_sender_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_conversation public.conversations%rowtype;
begin
  if (select auth.uid()) is null then
    raise exception 'Not authenticated';
  end if;

  if not public.can_access_client(p_client_id, 'clients.message') then
    raise exception 'Not authorized';
  end if;

  if not exists (
    select 1
    from public.clients c
    where c.id = p_client_id
      and c.workspace_id = p_workspace_id
  ) then
    raise exception 'Client not found';
  end if;

  if (public.get_client_coaching_access(p_client_id)-&gt;&gt;'canMessageRelationship')::boolean then
  insert into public.conversations (workspace_id, client_id)
  values (p_workspace_id, p_client_id)
  on conflict do nothing
  returning *
  into v_conversation;
  end if;

  if v_conversation.id is null then
    select conv.*
    into v_conversation
    from public.conversations conv
    where conv.workspace_id = p_workspace_id
      and conv.client_id = p_client_id
    limit 1;
  end if;

  return query
  select
    v_conversation.id,
    v_conversation.client_id,
    v_conversation.workspace_id,
    v_conversation.last_message_at,
    v_conversation.last_message_preview,
    v_conversation.last_message_sender_name,
    v_conversation.last_message_sender_role;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_workspace_checkins(p_workspace_id uuid, p_range_start date, p_range_end date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_client record;
begin
  if p_workspace_id is null then
    raise exception 'Workspace is required';
  end if;

  if not public.can_manage_workspace_delivery(p_workspace_id) then
    if public.can_access_workspace(p_workspace_id) then
      return;
    end if;
    raise exception 'Not authorized';
  end if;

  if not (public.get_workspace_commercial_access(p_workspace_id)-&gt;&gt;'canWriteExistingDelivery')::boolean then return; end if;

  for v_client in
    select c.id
    from public.clients c
    where c.workspace_id = p_workspace_id
  loop
    perform public.reconcile_client_checkins(
      v_client.id,
      p_range_start,
      p_range_end
    );
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_workspace_client_onboarding(p_client_id uuid, p_source public.onboarding_source DEFAULT 'direct_invite'::public.onboarding_source)
 RETURNS public.workspace_client_onboardings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_client public.clients%rowtype;
  v_row public.workspace_client_onboardings;
  v_baseline public.baseline_entries%rowtype;
  v_program public.client_programs%rowtype;
  v_checkin_submitted_at timestamptz := null;
  v_has_program boolean := false;
  v_has_checkin_setup boolean := false;
  v_legacy_status public.onboarding_status := null;
  v_started_at timestamptz := null;
  v_reviewed_at timestamptz := null;
  v_activated_at timestamptz := null;
  v_completed_at timestamptz := null;
begin
  if p_client_id is null then
    raise exception 'Client is required';
  end if;

  select c.*
  into v_client
  from public.clients c
  where c.id = p_client_id
  limit 1;

  if v_client.id is null or v_client.workspace_id is null then
    raise exception 'Client not found';
  end if;

  if not (
    public.is_client_owner(p_client_id)
    or public.is_pt_workspace_member(v_client.workspace_id)
  ) then
    raise exception 'Not authorized';
  end if;

  select *
  into v_row
  from public.workspace_client_onboardings wco
  where wco.workspace_id = v_client.workspace_id
    and wco.client_id = p_client_id
  limit 1;

  if not public.is_commercial_action_allowed(public.resolve_account_commercial_access((select owner_user_id from public.workspaces where id=v_client.workspace_id))-&gt;&gt;'accessMode','delivery_write') then return v_row; end if;

  if v_row.id is null then
    select *
    into v_baseline
    from public.baseline_entries be
    where be.client_id = p_client_id
      and be.status = 'submitted'
    order by coalesce(be.submitted_at, be.created_at) desc
    limit 1;

    select *
    into v_program
    from public.client_programs cp
    where cp.client_id = p_client_id
      and coalesce(cp.is_active, false) = true
    order by coalesce(cp.updated_at, cp.created_at) desc
    limit 1;

    select max(coalesce(ch.submitted_at, ch.created_at))
    into v_checkin_submitted_at
    from public.checkins ch
    where ch.client_id = p_client_id
      and ch.submitted_at is not null;

    v_has_program := v_program.id is not null;
    v_has_checkin_setup := (
      v_client.checkin_template_id is not null
      and v_client.checkin_start_date is not null
    ) or v_checkin_submitted_at is not null;

    if v_baseline.id is not null and v_has_program and v_has_checkin_setup then
      v_legacy_status := 'completed';
    elsif v_baseline.id is not null and (v_has_program or v_has_checkin_setup) then
      v_legacy_status := 'submitted';
    end if;

    if v_legacy_status is not null then
      v_started_at := coalesce(
        v_baseline.created_at,
        v_client.created_at,
        now()
      );
      v_reviewed_at := coalesce(
        v_program.updated_at,
        v_program.created_at,
        v_checkin_submitted_at,
        v_baseline.submitted_at,
        now()
      );
      v_activated_at :=
        case
          when v_legacy_status = 'completed'
            then coalesce(v_program.created_at, v_checkin_submitted_at, v_reviewed_at)
          else null
        end;
      v_completed_at :=
        case
          when v_legacy_status = 'completed'
            then coalesce(v_program.updated_at, v_program.created_at, v_reviewed_at)
          else null
        end;

      insert into public.workspace_client_onboardings (
        workspace_id,
        client_id,
        source,
        status,
        initial_baseline_entry_id,
        first_program_template_id,
        first_program_applied_at,
        first_checkin_template_id,
        first_checkin_date,
        first_checkin_scheduled_at,
        started_at,
        submitted_at,
        reviewed_at,
        activated_at,
        completed_at
      )
      values (
        v_client.workspace_id,
        p_client_id,
        coalesce(p_source, 'direct_invite'),
        v_legacy_status,
        v_baseline.id,
        v_program.program_template_id,
        case
          when v_has_program
            then coalesce(v_program.updated_at, v_program.created_at, now())
          else null
        end,
        v_client.checkin_template_id,
        v_client.checkin_start_date,
        case
          when v_has_checkin_setup
            then coalesce(v_checkin_submitted_at, now())
          else null
        end,
        v_started_at,
        coalesce(v_baseline.submitted_at, v_started_at, now()),
        v_reviewed_at,
        v_activated_at,
        v_completed_at
      )
      returning *
      into v_row;
    else
      insert into public.workspace_client_onboardings (
        workspace_id,
        client_id,
        source,
        status
      )
      values (
        v_client.workspace_id,
        p_client_id,
        coalesce(p_source, 'direct_invite'),
        'invited'
      )
      returning *
      into v_row;
    end if;
  end if;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_workspace_client_onboardings(p_workspace_id uuid, p_client_ids uuid[])
 RETURNS SETOF public.workspace_client_onboardings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_id uuid;
  v_row public.workspace_client_onboardings;
begin
  if p_workspace_id is null then
    raise exception 'Workspace is required';
  end if;

  if not public.is_pt_workspace_member(p_workspace_id) then
    raise exception 'Not authorized';
  end if;

  if coalesce(array_length(p_client_ids, 1), 0) = 0 then
    return;
  end if;

  foreach v_client_id in array p_client_ids loop
    if exists (
      select 1
      from public.clients c
      where c.id = v_client_id
        and c.workspace_id = p_workspace_id
    ) then
      v_row := public.ensure_workspace_client_onboarding(v_client_id, 'direct_invite');
      return next v_row;
    end if;
  end loop;

  return;
end;
$function$

CREATE OR REPLACE FUNCTION public.evaluate_my_capacity_change(p_dimension text, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s jsonb; d jsonb; projected jsonb; allowed boolean; reason text;
begin
  if p_dimension is null or p_dimension not in ('counted_clients','coach_seats','active_workspaces','published_packages') or p_quantity is null or p_quantity&lt;=0 then raise exception 'Invalid capacity change.' using errcode='22023'; end if;
  s := public.get_my_account_capacity_snapshot();
  select value into d from jsonb_array_elements(s-&gt;'dimensions') where value-&gt;&gt;'key'=p_dimension;
  if p_dimension='coach_seats' then d:=jsonb_set(d,'{limit}',to_jsonb(least((d-&gt;&gt;'limit')::integer,public.billing_seat_effective_limit((s-&gt;&gt;'billingAccountId')::uuid,true)))); end if;
  projected := public.account_capacity_dimension(p_dimension,(d-&gt;&gt;'committed')::bigint+p_quantity,0,0,(d-&gt;&gt;'limit')::integer,d-&gt;&gt;'state'&lt;&gt;'unavailable',false);
  allowed := case when d-&gt;&gt;'state'='unavailable' then null else projected-&gt;&gt;'state'&lt;&gt;'over_limit' end;
  reason := case when d-&gt;&gt;'state'='unavailable' then 'capacity_unavailable' when d-&gt;&gt;'state'='unlimited' then 'capacity_unlimited'
    when d-&gt;&gt;'state'='over_limit' then 'capacity_already_over_limit' when not allowed then 'capacity_would_exceed' else 'capacity_available' end;
  return jsonb_build_object('dimension',p_dimension,'currentCommitted',d-&gt;'committed','proposedQuantity',p_quantity,
    'projectedCommitted',projected-&gt;'committed','limit',d-&gt;'limit','currentState',d-&gt;'state','projectedState',projected-&gt;'state',
    'allowedUnderCurrentContract',allowed,'reasonCode',reason,'computedAt',s-&gt;'computedAt');
end;
$function$

CREATE OR REPLACE FUNCTION public.finish_billing_plan_change(p_owner uuid, p_environment text, p_snapshot jsonb, p_invoice jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb; h text; payload jsonb; event text; d uuid;
begin
  ctx:=public.billing_plan_change_context(p_owner,p_environment);
  if p_snapshot-&gt;&gt;'subscription_id' is distinct from ctx#&gt;&gt;'{subscription,provider_subscription_id}' then raise exception 'BILLING_PLAN_CHANGE_UNAPPROVED_PROVIDER_STATE'; end if;
  event:=case when p_invoice is null then 'subscription_updated' else 'subscription_payment_success' end;
  payload:=coalesce(p_invoice,jsonb_build_object('store_id',p_snapshot-&gt;&gt;'store_id','subscription_id',p_snapshot-&gt;&gt;'subscription_id','customer_id',p_snapshot-&gt;&gt;'customer_id','test_mode',p_environment='test','created_at',p_snapshot-&gt;&gt;'created_at','updated_at',p_snapshot-&gt;&gt;'updated_at'));
  -- API reconciliation uses the same durable inbox and validators. The hash
  -- namespaces this evidence separately from signed webhook deliveries.
  h:=encode(extensions.digest('api-reconciliation:'||p_snapshot::text||payload::text||case when exists(select 1 from public.billing_seat_quantity_operations where billing_provider_subscription_id=(ctx#&gt;&gt;'{subscription,id}')::uuid and status='scheduled' and effective_at&lt;=now()) then ':seat-due' else '' end,'sha256'),'hex');
  d:=public.record_billing_webhook_delivery(p_environment,event,case when p_invoice is null then 'subscriptions' else 'subscription-invoices' end,p_snapshot-&gt;&gt;'subscription_id',h,encode(extensions.digest(p_environment||chr(10)||event||chr(10)||h,'sha256'),'hex'),payload);
  return public.reconcile_billing_provider_subscription(d,p_snapshot);
end $function$

CREATE OR REPLACE FUNCTION public.get_billing_checkout_operation(p_attempt uuid, p_owner uuid, p_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.billing_checkout_attempts%rowtype; m public.billing_provider_variant_mappings%rowtype;
begin
  select * into strict t from public.billing_checkout_attempts where id=p_attempt and created_by_user_id=p_owner and environment=p_environment;
  perform public.expire_stale_billing_checkout_attempts(t.billing_account_id);
  select * into strict t from public.billing_checkout_attempts where id=p_attempt;
  select * into strict m from public.billing_provider_variant_mappings where id=t.variant_mapping_id;
  return jsonb_build_object('attempt',to_jsonb(t),'mapping',to_jsonb(m));
end $function$

CREATE OR REPLACE FUNCTION public.get_billing_portal_subscription(p_owner uuid, p_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a uuid; s uuid; b public.billing_provider_subscriptions%rowtype; local_status text;
begin
  if p_owner is null or not exists(select 1 from public.pt_profiles where user_id=p_owner and workspace_id is null) then
    raise exception 'BILLING_PORTAL_OWNER_REQUIRED' using errcode='42501'; end if;
  select id into a from public.billing_accounts where owner_user_id=p_owner;
  if a is null then raise exception 'BILLING_PORTAL_SUBSCRIPTION_NOT_FOUND'; end if;
  select id,status into s,local_status from public.account_subscriptions where billing_account_id=a and status&lt;&gt;'superseded'
    order by (status in ('trialing','trial_recovery','active','past_due','grace','restricted')) desc,created_at desc,id desc limit 1;
  select * into b from public.billing_provider_subscriptions where billing_account_id=a and account_subscription_id=s
    and provider='lemonsqueezy' and environment=p_environment;
  if b.id is null then raise exception 'BILLING_PORTAL_SUBSCRIPTION_NOT_FOUND'; end if;
  if b.provider_store_id is distinct from public.get_billing_provider_store(p_environment) then
    raise exception 'BILLING_PORTAL_IDENTITY_MISMATCH'; end if;
  if not exists(select 1 from public.account_subscriptions where id=s and subscription_kind='paid') or
    not exists(select 1 from public.billing_provider_customers where billing_account_id=a and provider=b.provider and environment=b.environment
      and provider_store_id=b.provider_store_id and provider_customer_id=b.provider_customer_id) then
    raise exception 'BILLING_PORTAL_IDENTITY_MISMATCH'; end if;
  return jsonb_build_object('provider',b.provider,'environment',b.environment,'store_id',b.provider_store_id,
    'customer_id',b.provider_customer_id,'subscription_id',b.provider_subscription_id,'local_subscription_id',s,'local_status',local_status);
end $function$

CREATE OR REPLACE FUNCTION public.get_client_coaching_access(p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c public.clients%rowtype; o uuid; r jsonb; m text; interactive boolean;
begin
  select * into c from public.clients where id=p_client_id;
  if auth.uid() is null or c.id is null or not (c.user_id=auth.uid() or public.can_access_client(c.id,'clients.view')) then raise exception 'Client access denied.' using errcode='42501'; end if;
  select owner_user_id into o from public.workspaces where id=c.workspace_id;
  r:=public.resolve_account_commercial_access(o);
  -- Unknown lifecycle fails closed; completed/churned retain historical reads.
  m:=case when o is null or c.relationship_status is distinct from 'active'
    or c.lifecycle_state is null or c.lifecycle_state not in ('invited','onboarding','active','paused') then 'unavailable' when r-&gt;&gt;'accessMode'='full' then 'interactive'
    when r-&gt;&gt;'accessMode'='existing_delivery_only' then 'existing_delivery' when r-&gt;&gt;'accessMode'='read_only' then 'read_only' else 'unavailable' end;
  interactive:=m in ('interactive','existing_delivery');
  return jsonb_build_object('schemaVersion',1,'clientId',c.id,'serviceMode',m,'canReadCoachedContent',true,
    'canLogWorkout',interactive,'canSubmitCheckin',interactive,'canSubmitHabitProgress',interactive,'canMessageRelationship',interactive,
    'canUseIndependentSelfService',true,'canBrowseMarketplace',true,'computedAt',transaction_timestamp());
end $function$

CREATE OR REPLACE FUNCTION public.get_effective_client_checkin_template_id(p_client_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_workspace_id uuid;
  v_template_id uuid;
begin
  if p_client_id is null then
    return null;
  end if;

  select c.workspace_id, c.checkin_template_id
  into v_workspace_id, v_template_id
  from public.clients c
  where c.id = p_client_id;

  if v_template_id is not null then
    return v_template_id;
  end if;

  select w.default_checkin_template_id
  into v_template_id
  from public.workspaces w
  where w.id = v_workspace_id;

  if v_template_id is not null then
    return v_template_id;
  end if;

  select ct.id
  into v_template_id
  from public.checkin_templates ct
  where ct.workspace_id = v_workspace_id
  order by ct.created_at desc
  limit 1;

  return v_template_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_account_capacity_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare u uuid := auth.uid(); a uuid;
begin
  if u is null or not exists(select 1 from public.pt_profiles where user_id=u) then raise exception 'PT authentication required.' using errcode='42501'; end if;
  select id into a from public.billing_accounts where owner_user_id=u;
