CREATE OR REPLACE FUNCTION public.get_my_billing_checkout_state(p_attempt uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a uuid; t public.billing_checkout_attempts%rowtype;
begin
  if auth.uid() is null then raise exception 'BILLING_FORBIDDEN' using errcode='42501'; end if;
