CREATE OR REPLACE FUNCTION public.get_my_billing_plan_change_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.billing_subscriptions_v2%rowtype;a public.account_subscriptions%rowtype;o public.billing_operations_v2%rowtype;m public.billing_price_mappings%rowtype;
begin
 if auth.uid() is null or not exists(select 1 from public.pt_profiles where user_id=auth.uid() and workspace_id is null) then raise exception 'BILLING_PLAN_CHANGE_OWNER_REQUIRED' using errcode='42501';end if;
 select b.* into s from public.billing_subscriptions_v2 b join public.billing_accounts account on account.id=b.billing_account_id
 where account.owner_user_id=auth.uid() and b.shadow_status='current' and b.account_subscription_id is not null;
 if s.id is null then return public.get_my_legacy_billing_plan_change_state();end if;
 select * into a from public.account_subscriptions where id=s.account_subscription_id;
 select * into m from public.billing_price_mappings where id=public.billing_paddle_current_mapping_v1(s.id);
 select * into o from public.billing_operations_v2 where subscription_id=s.id order by (status not in ('completed','canceled','failed')) desc,provider_requested_at desc,id desc limit 1;
 return jsonb_build_object('provider','paddle','linked',true,'cadence',m.cadence,'eligible',s.environment='test' and
 (select paddle_reconciliation_enabled and entitlement_environment='test' from public.billing_runtime_policy where id=1)
 and s.provider_status='active' and s.reconciliation_status='processed' and s.approved_additional_coach_seats=0 and a.status='active' and not a.cancel_at_period_end
 and s.scheduled_cancel_at is null and (o.id is null or o.status in ('completed','failed','canceled')),
 'operation',case when o.id is null then null else jsonb_build_object('operationId',o.operation_id,'status',o.status,'targetPlanKey',(select canonical_key from public.billing_price_mappings where id=o.target_base_mapping_id),
 'targetCadence',o.target_cadence,'effectiveAt',o.effective_at,'effectiveTiming',o.effective_timing,'errorCode',o.error_code) end);
end $function$

CREATE OR REPLACE FUNCTION public.get_my_billing_provider_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a uuid; s public.account_subscriptions%rowtype; b public.billing_provider_subscriptions%rowtype;
begin
  if auth.uid() is null or not exists(select 1 from public.pt_profiles where user_id=auth.uid() and workspace_id is null) then
    raise exception 'BILLING_PORTAL_OWNER_REQUIRED' using errcode='42501'; end if;
  select id into a from public.billing_accounts where owner_user_id=auth.uid();
  select * into s from public.account_subscriptions where billing_account_id=a and status&lt;&gt;'superseded'
    order by (status in ('trialing','trial_recovery','active','past_due','grace','restricted')) desc,created_at desc,id desc limit 1;
  select * into b from public.billing_provider_subscriptions where billing_account_id=a and account_subscription_id=s.id;
  return jsonb_build_object('linked',b.id is not null,'status',case when b.id is not null then s.status else null end,
    'cancelAtPeriodEnd',coalesce(s.cancel_at_period_end,false),'currentPeriodEndsAt',s.current_period_ends_at,
    'reconciliationStatus',b.reconciliation_status,'errorCode',case when b.reconciliation_status='manual_review' then
      case when b.reconciliation_error_code='BILLING_UNAPPROVED_PLAN_CHANGE' then 'BILLING_UNAPPROVED_PLAN_CHANGE' else 'BILLING_RECONCILIATION_MANUAL_REVIEW' end else null end,
    'revision',case when b.id is not null then b.latest_snapshot_sha256 else null end,
    'pending',exists(select 1 from public.billing_provider_webhook_deliveries d where d.provider=b.provider and d.environment=b.environment
      and d.provider_subscription_id=b.provider_subscription_id and d.processing_status in ('received','deferred','failed')));
end $function$

CREATE OR REPLACE FUNCTION public.get_my_billing_seat_quantity_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.billing_subscriptions_v2%rowtype;m public.billing_price_mappings%rowtype;p public.commercial_plan_versions%rowtype;o public.billing_operations_v2%rowtype;d jsonb;unit integer;begin
 if auth.uid() is null or not exists(select 1 from public.pt_profiles where user_id=auth.uid() and workspace_id is null) then raise exception 'BILLING_SEAT_QUANTITY_OWNER_REQUIRED' using errcode='42501';end if;
 select bs.* into s from public.billing_subscriptions_v2 bs join public.billing_accounts a on a.id=bs.billing_account_id where a.owner_user_id=auth.uid() and bs.shadow_status='current' and bs.account_subscription_id is not null;
 if s.id is null then return public.get_my_legacy_billing_seat_quantity_state();end if;
 select * into m from public.billing_price_mappings where id=public.billing_paddle_current_mapping_v1(s.id);
 select * into p from public.commercial_plan_versions where id=m.plan_version_id;
 select * into o from public.billing_operations_v2 where subscription_id=s.id and operation_kind='seat_quantity' order by provider_requested_at desc nulls last,id desc limit 1;
 select value into d from jsonb_array_elements(public.resolve_account_capacity(auth.uid(),s.billing_account_id)-&gt;'dimensions') where value-&gt;&gt;'key'='coach_seats';
 unit:=case m.cadence when 'monthly' then 1200 else 12000 end;
 return jsonb_build_object('available',true,'provider','paddle','canCancel',false,
 'blockingOperation',case when exists(select 1 from public.billing_operations_v2 where subscription_id=s.id and operation_kind='plan_change' and status not in ('completed','canceled','failed')) then 'plan_change' end,
 'summary',jsonb_build_object('planKey',p.plan_key,'cadence',m.cadence,'includedSeats',p.included_coach_seats,'currentAdditionalSeats',s.approved_additional_coach_seats,
 'maximumSeats',p.max_coach_seats,'maximumAdditionalSeats',p.max_coach_seats-p.included_coach_seats,'currentEffectiveLimit',public.billing_seat_effective_limit(s.billing_account_id),
 'growthLimit',public.billing_seat_effective_limit(s.billing_account_id,true),'actual',d-&gt;'actual','pending',d-&gt;'pending','reserved',d-&gt;'reserved','committed',d-&gt;'committed',
 'unitPriceMinor',unit,'currentTotalMinor',m.unit_amount_minor+unit*s.approved_additional_coach_seats,'manualReview',s.reconciliation_status='manual_review' or coalesce(o.status='manual_review',false)),
 'operation',case when o.id is null then null else jsonb_build_object('id',o.operation_id,'status',o.status,'direction',case when o.effective_timing='immediate' then 'increase' else 'reduction' end,
 'targetAdditionalSeats',o.target_additional_seats,'effectiveAt',o.effective_at,'errorCode',o.error_code) end);
end $function$

CREATE OR REPLACE FUNCTION public.get_my_effective_account_entitlements()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_user uuid := auth.uid(); a public.billing_accounts%rowtype;
begin
  -- pt_profiles is the canonical identity source, including the repository's
  -- legacy workspace-profile fallback. Metadata alone never establishes PT role.
  if v_user is null or not exists(select 1 from public.pt_profiles where user_id = v_user) then
    raise exception 'PT authentication required.' using errcode = '42501';
  end if;
  select * into a from public.billing_accounts where owner_user_id = v_user;
  return public.resolve_account_entitlements(a.id) || jsonb_build_object('billingAccount',jsonb_build_object(
    'id',a.id,'ownerUserId',v_user,'requestedPaidPlanKey',coalesce(a.requested_plan_key,'growth'),'canManageBilling',true));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_legacy_billing_plan_change_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a uuid; o public.billing_plan_change_operations%rowtype; s public.account_subscriptions%rowtype; b public.billing_provider_subscriptions%rowtype; m public.billing_provider_variant_mappings%rowtype;
begin
  if auth.uid() is null or not exists(select 1 from public.pt_profiles where user_id=auth.uid() and workspace_id is null) then raise exception 'BILLING_PLAN_CHANGE_OWNER_REQUIRED' using errcode='42501'; end if;
  select id into a from public.billing_accounts where owner_user_id=auth.uid();
  select * into s from public.account_subscriptions where billing_account_id=a and status&lt;&gt;'superseded' order by (status in ('active','past_due','grace','restricted')) desc,created_at desc,id desc limit 1;
  select * into b from public.billing_provider_subscriptions where account_subscription_id=s.id;
  select * into m from public.billing_provider_variant_mappings where id=b.variant_mapping_id;
  select * into o from public.billing_plan_change_operations where billing_account_id=a order by (status not in ('completed','canceled','failed')) desc,created_at desc,id desc limit 1;
  return jsonb_build_object('linked',b.id is not null,'cadence',case when o.status not in ('completed','canceled','failed') then o.source_cadence else m.cadence end,
    'eligible',b.id is not null and s.status='active' and not s.cancel_at_period_end and b.provider_status='active' and b.reconciliation_status='processed' and (o.id is null or o.status in ('completed','canceled','failed')),
    'operation',case when o.id is not null then jsonb_build_object('operationId',o.operation_id,'status',o.status,'targetPlanKey',(select plan_key from public.commercial_plan_versions where id=o.target_plan_version_id),'targetCadence',o.target_cadence,'effectiveAt',o.effective_at,'effectiveTiming',o.effective_timing,'errorCode',o.error_code) else null end);
end $function$

CREATE OR REPLACE FUNCTION public.get_my_legacy_billing_seat_quantity_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a uuid; b public.billing_provider_subscriptions%rowtype; p public.commercial_plan_versions%rowtype; m public.billing_provider_variant_mappings%rowtype; o public.billing_seat_quantity_operations%rowtype; d jsonb; unit integer;
begin
  if auth.uid() is null or not exists(select 1 from public.pt_profiles where user_id=auth.uid() and workspace_id is null) then raise exception 'BILLING_SEAT_QUANTITY_OWNER_REQUIRED' using errcode='42501'; end if;
  select id into a from public.billing_accounts where owner_user_id=auth.uid();
  select bp.* into b from public.billing_provider_subscriptions bp join public.account_subscriptions s on s.id=bp.account_subscription_id where bp.billing_account_id=a and s.status&lt;&gt;'superseded' order by s.created_at desc limit 1;
  if b.id is null then return jsonb_build_object('available',false,'summary',null,'operation',null); end if;
  select * into m from public.billing_provider_variant_mappings where id=b.variant_mapping_id;
  select * into p from public.commercial_plan_versions where id=(select plan_version_id from public.account_subscriptions where id=b.account_subscription_id);
  select * into o from public.billing_seat_quantity_operations where billing_provider_subscription_id=b.id order by created_at desc,id desc limit 1;
  select value into d from jsonb_array_elements(public.resolve_account_capacity(auth.uid(),a)-&gt;'dimensions') where value-&gt;&gt;'key'='coach_seats';
  select case m.cadence when 'monthly' then av.monthly_unit_amount_minor else av.annual_unit_amount_minor end into unit from public.billing_quantity_price_contracts c join public.commercial_addon_versions av on av.id=c.addon_version_id where c.variant_mapping_id=m.id;
  unit:=coalesce(unit,case m.cadence when 'monthly' then 1200 else 12000 end);
  return jsonb_build_object('available',true,'summary',jsonb_build_object('planKey',p.plan_key,'cadence',m.cadence,'includedSeats',p.included_coach_seats,'currentAdditionalSeats',b.approved_additional_coach_seats,
    'maximumSeats',p.max_coach_seats,'maximumAdditionalSeats',p.max_coach_seats-p.included_coach_seats,'currentEffectiveLimit',public.billing_seat_effective_limit(a),'growthLimit',public.billing_seat_effective_limit(a,true),
    'actual',d-&gt;'actual','pending',d-&gt;'pending','reserved',d-&gt;'reserved','committed',d-&gt;'committed','unitPriceMinor',unit,'currentTotalMinor',m.unit_amount_minor+unit*b.approved_additional_coach_seats,
    'manualReview',b.reconciliation_status='manual_review'),
    'operation',case when o.id is null then null else jsonb_build_object('id',o.id,'status',o.status,'direction',o.direction,'targetAdditionalSeats',o.target_additional_seats,'effectiveAt',o.effective_at,'errorCode',o.error_code) end);
end $function$

CREATE OR REPLACE FUNCTION public.get_workspace_commercial_access(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare o uuid; r jsonb;
begin
  if auth.uid() is null or not public.can_access_workspace(p_workspace_id) then raise exception 'Workspace access denied.' using errcode='42501'; end if;
  select owner_user_id into o from public.workspaces where id=p_workspace_id;
  r:=public.resolve_account_commercial_access(o);
  return jsonb_build_object('schemaVersion',1,'workspaceId',p_workspace_id,'billingOwnerUserId',o,'accessMode',r-&gt;'accessMode',
    'canReadWorkspace',r#&gt;'{actions,workspace_read}','canWriteExistingDelivery',r#&gt;'{actions,delivery_write}',
    'canWriteBusinessConfiguration',r#&gt;'{actions,business_configuration_write}','canGrowCapacity',r#&gt;'{actions,capacity_growth}',
    'canManageBilling',o=auth.uid(),'recoveryRequired',r-&gt;'recoveryRequired','computedAt',transaction_timestamp());
end $function$

CREATE OR REPLACE FUNCTION public.get_workspace_effective_entitlements(p_workspace_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_owner uuid; v_account uuid; v_result jsonb; v_subscription jsonb;
begin
  -- Existing access helper includes role permissions and active-member status.
  -- It is intentionally VOLATILE because denied team access can write its audit.
  if auth.uid() is null or not public.can_access_workspace(p_workspace_id) then
    raise exception 'Workspace access denied.' using errcode = '42501';
  end if;
  select owner_user_id into v_owner from public.workspaces where id = p_workspace_id;
  select id into v_account from public.billing_accounts where owner_user_id = v_owner;
  v_result := public.resolve_account_entitlements(v_account); v_subscription := v_result-&gt;'subscription';
  return jsonb_build_object('schemaVersion',1,'workspaceId',p_workspace_id,'billingOwnerUserId',v_owner,
    'canManageBilling',coalesce(v_owner = auth.uid(),false),'effectiveStatus',v_subscription-&gt;'effectiveStatus',
    'accessMode',v_subscription-&gt;'accessMode','accessLabel',v_subscription-&gt;'accessLabel','planKey',v_subscription-&gt;'planKey',
    'planVersion',v_subscription-&gt;'planVersion','planDisplayName',v_subscription-&gt;'planDisplayName',
    'limits',v_result-&gt;'limits','enabledFeatureKeys',v_result-&gt;'enabledFeatureKeys','computedAt',v_result-&gt;'computedAt');
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_capacity_domain_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare n jsonb; b jsonb; owners uuid[]; s record; a uuid; lost integer;
begin
  if tg_op&lt;&gt;'DELETE' then n:=to_jsonb(new); end if;
  if tg_op&lt;&gt;'INSERT' then b:=to_jsonb(old); end if;
  if tg_op='UPDATE' and not exists (
    (select * from public.capacity_row_subjects(tg_table_name,n)
     except select * from public.capacity_row_subjects(tg_table_name,b))
    union all
    (select * from public.capacity_row_subjects(tg_table_name,b)
     except select * from public.capacity_row_subjects(tg_table_name,n))
  ) then return new; end if;
  if tg_table_name='workspaces' and tg_op&lt;&gt;'DELETE'
    and (tg_op='INSERT' or (n-&gt;&gt;'owner_user_id') is distinct from (b-&gt;&gt;'owner_user_id')) then
    -- Account creation does not itself start a trial. Resolve both accounts first.
    a:=public.ensure_commercial_billing_account((n-&gt;&gt;'owner_user_id')::uuid,
      case when tg_op='INSERT' then 'first_workspace' else 'workspace_transfer' end);
  end if;
  select array_agg(distinct x.owner_id) into owners from (
    select owner_id from public.capacity_row_subjects(tg_table_name,n)
    union select owner_id from public.capacity_row_subjects(tg_table_name,b)
    union select (n-&gt;&gt;'owner_user_id')::uuid where tg_table_name='workspaces'
    union select (b-&gt;&gt;'owner_user_id')::uuid where tg_table_name='workspaces'
  ) x;
  perform public.lock_capacity_owners(owners);
  if tg_table_name='workspaces' and tg_op&lt;&gt;'DELETE'
    and (tg_op='INSERT' or (n-&gt;&gt;'owner_user_id') is distinct from (b-&gt;&gt;'owner_user_id')) then
    perform public.start_account_trial_for_owner((n-&gt;&gt;'owner_user_id')::uuid,
      case when tg_op='INSERT' then 'first_workspace' else 'workspace_transfer' end);
  end if;
  for s in select distinct * from public.capacity_row_subjects(tg_table_name,n)
    order by owner_id,dimension,subject_key
  loop
    -- Identity replacement within one account is neutral when the old identity
    -- has no other commitment. Duplicates in the canonical set remain counted.
    lost:=0;
    if tg_table_name='clients' and tg_op='UPDATE' then
      select count(*) into lost from public.capacity_row_subjects(tg_table_name,b) old_s
        where old_s.owner_id=s.owner_id and old_s.dimension=s.dimension
          and old_s.subject_key&lt;&gt;s.subject_key
          and (select count(*) from public.account_capacity_subjects(s.owner_id,transaction_timestamp()) x
            where x.dimension=s.dimension and x.subject_key=old_s.subject_key)=1;
    end if;
    if lost=0 then
      perform public.admit_account_capacity_subject(s.owner_id,s.dimension,s.subject_key);
    end if;
  end loop;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_commercial_domain_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare n jsonb; b jsonb; row_data jsonb; scope jsonb; action text; o uuid; w uuid; c uuid; k text;
begin
  -- Unauthenticated service/migration writers retain existing privileges. This
  -- is not a browser-controlled bypass; anonymous runtime writes are denied.
  if current_setting('role',true) in ('none','postgres','service_role') then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if auth.uid() is null then
    if current_setting('role',true) in ('anon','authenticated') then raise exception 'Authentication required.' using errcode='42501'; end if;
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op&lt;&gt;'DELETE' then n:=to_jsonb(new); end if;
  if tg_op&lt;&gt;'INSERT' then b:=to_jsonb(old); end if;
  if tg_op='UPDATE' and n=b then return new; end if;
  action:='delivery_write';
  if tg_table_name in ('pt_hub_profiles','pt_hub_leads','pt_hub_lead_notes','lead_messages','lead_conversations','invites') then action:='acquisition_write'; end if;
  if tg_table_name in ('workspaces','workspace_wearable_settings','pt_hub_settings','pt_packages','workspace_members','workspace_member_invites') then action:='business_configuration_write'; end if;
  if tg_table_name='workspaces' and tg_op='INSERT' then
    o:=(n-&gt;&gt;'owner_user_id')::uuid;
    if o=auth.uid() and not exists(select 1 from public.workspaces where owner_user_id=o)
       and public.resolve_account_commercial_access(o)-&gt;&gt;'accessMode'='onboarding' then return new; end if;
    action:='capacity_growth';
  end if;
  -- Explicit reducing transitions only: accompanying unrelated edits remain
  -- subject to their ordinary class. No blanket DELETE exemption for delivery.
  if tg_op='DELETE' and tg_table_name in ('clients','workspaces','workspace_members','workspace_member_invites','invites','pt_packages','workspace_member_client_assignments','workspace_invite_client_assignments') then action:='remediation'; end if;
  if tg_op='UPDATE' then
    if tg_table_name='invites' and (n-'expires_at')=(b-'expires_at') and (n-&gt;&gt;'expires_at')::timestamptz&lt;=transaction_timestamp() then action:='remediation'; end if;
    if tg_table_name='clients' and (n-array['lifecycle_state','lifecycle_changed_at','status','paused_reason','churn_reason','relationship_status','removed_at','removed_by_user_id','updated_at'])=(b-array['lifecycle_state','lifecycle_changed_at','status','paused_reason','churn_reason','relationship_status','removed_at','removed_by_user_id','updated_at'])
      and (n-&gt;&gt;'lifecycle_state' in ('completed','churned') or n-&gt;&gt;'relationship_status' in ('removed','transferred_out')) then action:='remediation'; end if;
    if tg_table_name='workspace_members' and (n-array['status','updated_at'])=(b-array['status','updated_at']) and n-&gt;&gt;'status' in ('suspended','removed') then action:='remediation'; end if;
    if tg_table_name='workspace_member_invites' and (n-array['status','updated_at'])=(b-array['status','updated_at']) and n-&gt;&gt;'status' in ('revoked','declined','expired') then action:='remediation'; end if;
    if tg_table_name='pt_packages' and (n-array['status','is_public','archived_at','updated_at'])=(b-array['status','is_public','archived_at','updated_at']) and (n-&gt;&gt;'is_public'='false' or n-&gt;&gt;'status'='archived') then action:='remediation'; end if;
    if tg_table_name='pt_hub_profiles' and (n-array['is_published','marketplace_visible','published_at','updated_at'])=(b-array['is_published','marketplace_visible','published_at','updated_at']) and n-&gt;&gt;'is_published'='false' then action:='remediation'; end if;
    if tg_table_name='workspaces' and (n-array['owner_user_id','updated_at'])=(b-array['owner_user_id','updated_at']) and n-&gt;&gt;'owner_user_id' is distinct from b-&gt;&gt;'owner_user_id' then action:='remediation'; end if;
    if tg_table_name='workspace_members' and (n-array['theme_preference','compact_density','updated_at'])=(b-array['theme_preference','compact_density','updated_at']) then action:='account_security'; end if;
    if tg_table_name='messages' and (n-'unread')=(b-'unread') then action:='account_security'; end if;
    if tg_table_name='clients' and n-&gt;&gt;'user_id'=auth.uid()::text and (n-array['display_name','full_name','avatar_url','phone','email','location','timezone','unit_preference','gender','photo_url','location_country','height_cm','dob','date_of_birth','sex','height_value','height_unit','weight_value_current','weight_unit','account_onboarding_completed_at','updated_at'])=(b-array['display_name','full_name','avatar_url','phone','email','location','timezone','unit_preference','gender','photo_url','location_country','height_cm','dob','date_of_birth','sex','height_value','height_unit','weight_value_current','weight_unit','account_onboarding_completed_at','updated_at']) then action:='client_self_service'; end if;
  end if;
  -- Personal account identity remains editable independently of public business
  -- publication. Existing RLS and account RPCs still authorize these writes.
  if tg_table_name='pt_profiles' then
    action:='business_configuration_write';
    if tg_op='DELETE' or (tg_op='UPDATE' and (n-array['id','user_id','workspace_id','display_name','full_name','phone','avatar_url','location_country','location_city','onboarding_completed_at','created_at','updated_at'])=(b-array['id','user_id','workspace_id','display_name','full_name','phone','avatar_url','location_country','location_city','onboarding_completed_at','created_at','updated_at']))
      or (tg_op='INSERT' and jsonb_strip_nulls(n-array['id','user_id','workspace_id','display_name','full_name','phone','avatar_url','location_country','location_city','onboarding_completed_at','created_at','updated_at']) &lt;@ '{"languages":[],"specialties":[]}'::jsonb) then action:='account_security'; end if;
  end if;
  if tg_op='INSERT' and tg_table_name='pt_hub_settings' and n-&gt;&gt;'profile_visibility'='draft' and n-&gt;&gt;'subscription_plan' is null and n-&gt;&gt;'subscription_status' is null then action:='account_security'; end if;
  if tg_op='INSERT' and tg_table_name='pt_hub_profiles' and jsonb_strip_nulls(n-array['id','user_id','full_name','display_name','profile_photo_url','created_at','updated_at']) &lt;@ '{"specialties":[],"certifications":[],"social_links":[],"coaching_modes":[],"availability_modes":[],"marketplace_visible":false,"is_published":false,"testimonials":[],"transformations":[]}'::jsonb then action:='account_security'; end if;
  if tg_table_name='pt_hub_settings' and (coalesce(n,'{}')-array['id','user_id','full_name','contact_email','support_email','phone','timezone','city','country','client_alerts','weekly_digest','product_updates','created_at','updated_at'])=(coalesce(b,'{}')-array['id','user_id','full_name','contact_email','support_email','phone','timezone','city','country','client_alerts','weekly_digest','product_updates','created_at','updated_at']) then action:='account_security'; end if;
  if tg_table_name='pt_hub_profiles' and tg_op='UPDATE' and (n-array['full_name','display_name','profile_photo_url','updated_at'])=(b-array['full_name','display_name','profile_photo_url','updated_at']) then action:='account_security'; end if;
  if tg_table_name in ('clients','workspace_members','workspace_member_invites') and tg_op='INSERT' then action:='capacity_growth'; end if;
  if tg_table_name='pt_packages' and n-&gt;&gt;'is_public'='true' then action:='acquisition_write'; end if;
  if tg_table_name='clients' and tg_op='UPDATE' and (n-&gt;&gt;'workspace_id' is distinct from b-&gt;&gt;'workspace_id' or n-&gt;&gt;'user_id' is distinct from b-&gt;&gt;'user_id' or (n-&gt;&gt;'relationship_status'='active' and b-&gt;&gt;'relationship_status'&lt;&gt;'active')) then action:='capacity_growth'; end if;
  if tg_table_name='workspace_invite_client_assignments' and tg_op&lt;&gt;'DELETE' then action:='business_configuration_write'; end if;
  if tg_table_name='workspace_member_client_assignments' and tg_op&lt;&gt;'DELETE' and not exists(
    select 1 from public.workspace_members m join public.clients c on c.workspace_id=m.workspace_id
    where m.id=(n-&gt;&gt;'member_id')::uuid and c.id=(n-&gt;&gt;'client_id')::uuid and m.status='active' and c.relationship_status='active') then action:='business_configuration_write'; end if;
  -- Check both old and new scope: moving a row cannot escape its source policy.
  foreach row_data in array array[b,n] loop
    if row_data is null then continue; end if;
    if action='account_security' and tg_table_name='workspace_members' and row_data-&gt;&gt;'user_id'=auth.uid()::text then continue; end if;
    scope:=public.commercial_row_scope(tg_table_name,row_data);
    if scope is null then
      -- A guarded parent deletion may cascade after that parent is no longer visible.
      if tg_op='DELETE' and pg_trigger_depth()&gt;1 then continue; end if;
      raise exception 'Write scope unavailable.' using errcode='42501';
    end if;
    if (scope-&gt;&gt;'independent')::boolean then continue; end if;
    o:=(scope-&gt;&gt;'owner')::uuid; w:=(scope-&gt;&gt;'workspace')::uuid; c:=(scope-&gt;&gt;'client')::uuid;
    -- Invite consumption happens after the capability RPC establishes the
    -- caller's client relationship. Keep its acquisition check and safe audience.
    if tg_table_name='invites' and tg_op='UPDATE' and (n-array['uses','used_at'])=(b-array['uses','used_at'])
      and (n-&gt;'used_at'=b-&gt;'used_at' or (b-&gt;&gt;'used_at' is null and (n-&gt;&gt;'used_at')::timestamptz=transaction_timestamp()))
      and (n-&gt;&gt;'uses')::integer=(b-&gt;&gt;'uses')::integer+1 then
      select id into c from public.clients where workspace_id=w and user_id=auth.uid() and relationship_status='active' limit 1;
    end if;
    if tg_table_name in ('client_medical_records','client_medical_documents') and exists(select 1 from public.clients where id=c and user_id=auth.uid()) then action:='client_self_service'; end if;
    -- These identity/status columns are not directly writable by authenticated
    -- callers. The existing invite/relationship RPC has already authorized the
    -- capability before inserting/reactivating the actor's new membership.
    if (tg_table_name='clients' and n-&gt;&gt;'user_id'=auth.uid()::text and action='capacity_growth')
      or (tg_table_name='workspace_members' and n-&gt;&gt;'user_id'=auth.uid()::text and n-&gt;&gt;'status'='active' and (tg_op='INSERT' or b-&gt;&gt;'status'&lt;&gt;'active')) then
      if not public.is_commercial_action_allowed(public.resolve_account_commercial_access(o)-&gt;&gt;'accessMode',action) then
        k:=case when tg_table_name='clients' then 'CLIENT_COACHING_INTERACTION_UNAVAILABLE' else 'WORKSPACE_COMMERCIAL_ACCESS_UNAVAILABLE' end;
        raise exception '%',k using errcode='42501',detail=jsonb_build_object('code',k)::text;
      end if;
      continue;
    end if;
    if tg_table_name in ('pt_hub_leads','lead_conversations','lead_messages','pt_hub_lead_notes') and o&lt;&gt;auth.uid() then
      -- The original RPC/RLS authorizes prospects; commercial failure stays
      -- audience-safe even if the authenticated prospect retries a direct call.
      if not public.is_coach_accepting_applications(o) then raise exception 'PUBLIC_COACH_NOT_ACCEPTING_APPLICATIONS' using errcode='42501',detail='{"code":"PUBLIC_COACH_NOT_ACCEPTING_APPLICATIONS","audience":"public"}'; end if;
    else
      perform public.assert_commercial_action_allowed(o,action,w,c);
      if tg_table_name in ('conversations','messages','message_typing') and c is not null
        and not (public.get_client_coaching_access(c)-&gt;&gt;'canMessageRelationship')::boolean then
        raise exception 'CLIENT_COACHING_INTERACTION_UNAVAILABLE' using errcode='42501';
      end if;
    end if;
  end loop;
  if tg_op='DELETE' then return old; else return new; end if;
end $function$

CREATE OR REPLACE FUNCTION public.guard_personal_nutrition_template_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.owner_client_id is null then
    return old;
  end if;

  if exists (
    select 1
    from public.assigned_nutrition_plans ap
    where ap.nutrition_template_id = old.id
  ) then
    raise exception 'Used personal nutrition templates cannot be deleted. Archive this template instead.';
  end if;

  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_assigned_workout_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_user_id uuid;
  v_workout_name text;
  v_date_label text;
begin
  select c.user_id
  into v_client_user_id
  from public.clients c
  where c.id = new.client_id;

  if v_client_user_id is null then
    return new;
  end if;

  v_workout_name := coalesce(nullif(trim(new.workout_name), ''), 'Workout');
  v_date_label := to_char(new.scheduled_date::timestamp, 'Mon DD');

  if tg_op = 'INSERT' then
    perform public.notify_user(
      v_client_user_id,
      'workout_assigned',
      'Workout assigned',
      format('%s is scheduled for %s.', v_workout_name, v_date_label),
      '/app/home',
      'assigned_workout',
      new.id,
      null,
      jsonb_build_object('scheduled_date', new.scheduled_date, 'client_id', new.client_id),
      'workouts',
      'normal'
    );
    return new;
  end if;

  if new.scheduled_date is not distinct from old.scheduled_date
     and new.workout_template_id is not distinct from old.workout_template_id
     and new.day_type is not distinct from old.day_type
     and coalesce(new.workout_name, '') = coalesce(old.workout_name, '')
     and coalesce(new.coach_note, '') = coalesce(old.coach_note, '') then
    return new;
  end if;

  perform public.notify_user(
    v_client_user_id,
    'workout_updated',
    'Workout updated',
    format('Your coach updated your workout for %s.', v_date_label),
    '/app/home',
    'assigned_workout',
    new.id,
    null,
    jsonb_build_object('scheduled_date', new.scheduled_date, 'client_id', new.client_id),
    'workouts',
    'normal'
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_checkin_requested_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_user_id uuid;
  v_workspace_id uuid;
begin
  select c.user_id, c.workspace_id
  into v_client_user_id, v_workspace_id
  from public.clients c
  where c.id = new.client_id;

  if v_client_user_id is null or new.submitted_at is not null then
    return new;
  end if;

  if new.week_ending_saturday &gt; current_date + 7 then
    return new;
  end if;

  if exists (
    select 1
    from public.checkins ci
    where ci.client_id = new.client_id
      and ci.id &lt;&gt; new.id
      and ci.submitted_at is null
      and ci.week_ending_saturday &lt; new.week_ending_saturday
  ) then
    return new;
  end if;

  if auth.uid() is null or not exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = v_workspace_id
      and wm.user_id = auth.uid()
      and wm.role::text like 'pt_%'
  ) then
    return new;
  end if;

  perform public.notify_user(
    v_client_user_id,
    'checkin_requested',
    'Check-in requested',
    format('Your coach requested a check-in due on %s.', to_char(new.week_ending_saturday::timestamp, 'Mon DD')),
    '/app/checkin',
    'checkin',
    new.id,
    null,
    jsonb_build_object('week_ending_saturday', new.week_ending_saturday, 'client_id', new.client_id),
    'checkins',
    'normal'
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_checkin_reviewed_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_user_id uuid;
begin
  if old.reviewed_at is not null or new.reviewed_at is null then
    return new;
  end if;

  if nullif(trim(coalesce(new.pt_feedback, '')), '') is null then
    return new;
  end if;

  select c.user_id
  into v_client_user_id
  from public.clients c
  where c.id = new.client_id;

  if v_client_user_id is null then
    return new;
  end if;

  perform public.notify_user(
    v_client_user_id,
    'checkin_reviewed',
    'Check-in feedback ready',
    'Your coach reviewed your check-in.',
    format('/app/checkins?checkin=%s', new.id),
    'checkin',
    new.id,
    null,
    jsonb_build_object(
      'week_ending_saturday', new.week_ending_saturday,
      'client_id', new.client_id
    ),
    'checkins',
    'normal'
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ingest_verified_paddle_event_v1(p_proof jsonb, p_raw_payload_sha256 text, p_notification_ref text, p_observation jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p jsonb; o jsonb:=p_observation; kind text; logical jsonb; digest text; ev uuid; verified jsonb;
 account uuid; initial_account uuid; sid uuid; cid uuid; tx text; checkout public.billing_checkouts_v2%rowtype;
 sub public.billing_subscriptions_v2%rowtype; old_sub public.billing_subscriptions_v2%rowtype;
 current_customer public.billing_customers_v2%rowtype; snapshot public.billing_paddle_checkout_snapshots%rowtype;
 old public.billing_paddle_event_observations%rowtype; delivery public.billing_paddle_event_deliveries%rowtype;
 item jsonb; mapping public.billing_price_mappings%rowtype; roles text[]:='{}'; cadence text;
 valid_items boolean:=true; state text:='pending'; observed timestamptz; found_checkout boolean; count_items integer:=0;
 supersede boolean:=false; old_cid uuid; old_sid uuid; transition_at timestamptz;
 plan_delta boolean:=false;seat_delta boolean:=false;
begin
 perform public.billing_guard_actor();
 p:=public.billing_v2_proof_validate(p_proof,'event');
 if p-&gt;&gt;'environment'&lt;&gt;'test' or p-&gt;&gt;'provider'&lt;&gt;'paddle' then raise exception 'PADDLE_INGRESS_SCOPE'; end if;
 kind:=o-&gt;&gt;'kind';
 if kind is null or kind not in ('transaction.completed','subscription.created','subscription.updated') then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 perform public.billing_v2_proof_object(o,array['provider','environment','eventRef','notificationRef','eventType','occurredAt','kind','customerRef','subscriptionRef','status','items'] || array(select key from jsonb_object_keys(o) key where key=any(array['planChangeOperationId','seatQuantityOperationId','paymentTotals'])) ||
  case when kind='transaction.completed' then array['transactionRef','currency'] || case when o ? 'origin' then array['origin'] else '{}'::text[] end || case when o ? 'billingPeriod' then array['billingPeriod'] else '{}'::text[] end else array['transactionCorrelationRef'] || case when kind='subscription.updated' then array(select key from jsonb_object_keys(o) key where key=any(array['updatedAt','currentBillingPeriod','nextBilledAt','canceledAt','pausedAt','scheduledChange'])) else '{}'::text[] end end);
 perform public.billing_paddle_lifecycle_shape_v1(o);
 if o ? 'seatQuantityOperationId' and (o ? 'planChangeOperationId' or jsonb_typeof(o-&gt;'seatQuantityOperationId')&lt;&gt;'string'
 or (o-&gt;&gt;'seatQuantityOperationId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then raise exception 'PADDLE_INGRESS_INVALID';end if;
 if o ? 'planChangeOperationId' and (jsonb_typeof(o-&gt;'planChangeOperationId')&lt;&gt;'string' or (o-&gt;&gt;'planChangeOperationId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then raise exception 'PADDLE_INGRESS_INVALID';end if;
 if o ? 'paymentTotals' then
  if kind&lt;&gt;'transaction.completed' then raise exception 'PADDLE_INGRESS_INVALID';end if;
  perform public.billing_v2_proof_object(o-&gt;'paymentTotals',array['total','paid','balance']);
  perform public.billing_v2_proof_money(o#&gt;'{paymentTotals,total}');perform public.billing_v2_proof_money(o#&gt;'{paymentTotals,paid}');perform public.billing_v2_proof_money(o#&gt;'{paymentTotals,balance}');
 end if;

 perform public.billing_v2_proof_ref(o-&gt;'notificationRef');
 perform public.billing_v2_proof_ref(o-&gt;'customerRef',true);
 perform public.billing_v2_proof_ref(o-&gt;'subscriptionRef',kind='transaction.completed');
 if kind='transaction.completed' then perform public.billing_v2_proof_ref(o-&gt;'transactionRef');
 else perform public.billing_v2_proof_ref(o-&gt;'transactionCorrelationRef',true); end if;
 if (o-&gt;&gt;'provider'='paddle' and o-&gt;&gt;'environment'='test' and o-&gt;&gt;'eventRef'=p#&gt;&gt;'{eventEvidence,eventRef}'
 and o-&gt;&gt;'eventType'=kind and kind=p#&gt;&gt;'{eventEvidence,eventName}' and o-&gt;&gt;'notificationRef'=p_notification_ref
 and o-&gt;'customerRef'=p#&gt;'{identity,customerRef}' and o-&gt;'subscriptionRef'=p#&gt;'{identity,subscriptionRef}') is not true
 then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 if jsonb_typeof(o-&gt;'occurredAt')&lt;&gt;'string' or length(o-&gt;&gt;'occurredAt')&gt;64 or (o-&gt;&gt;'occurredAt') !~ '^\d{4}-\d{2}-\d{2}T' then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 observed:=(o-&gt;&gt;'occurredAt')::timestamptz;
 -- PREP proof uses milliseconds; exact provider timestamp is retained separately.
 if date_trunc('milliseconds',observed)&lt;&gt;(p#&gt;&gt;'{eventEvidence,occurredAt}')::timestamptz then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 if kind='transaction.completed' then
  if (o-&gt;&gt;'status'='completed' and o-&gt;&gt;'currency'='USD' and o-&gt;'transactionRef'=p#&gt;'{identity,transactionRef}') is not true then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 else
  if o-&gt;&gt;'status' is null or o-&gt;&gt;'status' not in ('active','trialing','past_due','paused','canceled') or (kind='subscription.updated' and o-&gt;'transactionCorrelationRef'&lt;&gt;'null'::jsonb) then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 end if;
 if jsonb_typeof(o-&gt;'items')&lt;&gt;'array' or jsonb_array_length(o-&gt;'items') not between 1 and 32 then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 -- Validate a closed sanitized shape before any durable retention.
 for item in select value from jsonb_array_elements(o-&gt;'items') loop
  perform public.billing_v2_proof_object(item,array['priceRef','productRef','quantity','unitPrice'] || case when kind='transaction.completed' then array[]::text[] else array['status'] end);
  perform public.billing_v2_proof_ref(item-&gt;'priceRef'); perform public.billing_v2_proof_ref(item-&gt;'productRef',true);
  perform public.billing_v2_proof_object(item-&gt;'unitPrice',array['amount','currency']);
  if (case when kind='transaction.completed' and (o ? 'planChangeOperationId' or o ? 'seatQuantityOperationId') and o-&gt;&gt;'origin'='subscription_update' then
    -- Structural retention only: no zero, fractions, strings or unbounded values.
    jsonb_typeof(item-&gt;'quantity') is distinct from 'number'
    or (item-&gt;&gt;'quantity') !~ '^-?[1-9][0-9]{0,9}$'
    or abs((item-&gt;&gt;'quantity')::numeric)&gt;2147483647
   else public.billing_v2_proof_money(item-&gt;'quantity') not between 1 and 2147483647 end)
   or jsonb_typeof(item#&gt;'{unitPrice,amount}')&lt;&gt;'string' or (item#&gt;&gt;'{unitPrice,amount}') !~ '^(0|[1-9][0-9]{0,15})$'
   or item#&gt;&gt;'{unitPrice,currency}' is null or item#&gt;&gt;'{unitPrice,currency}' !~ '^[A-Z]{3}$'
   or (kind&lt;&gt;'transaction.completed' and (item-&gt;&gt;'status' is null or item-&gt;&gt;'status' not in ('active','inactive','trialing')))
   then raise exception 'PADDLE_INGRESS_INVALID'; end if;
 end loop;
 logical:=o-'notificationRef'; digest:=encode(extensions.digest(logical::text,'sha256'),'hex');
 tx:=case when kind='transaction.completed' then o-&gt;&gt;'transactionRef' else o-&gt;&gt;'transactionCorrelationRef' end;
 select * into checkout from public.billing_checkouts_v2 where provider='paddle' and environment='test' and provider_transaction_ref=tx;
 found_checkout:=found;
 select * into sub from public.billing_subscriptions_v2 where provider='paddle' and environment='test' and provider_subscription_ref=o-&gt;&gt;'subscriptionRef';
 account:=coalesce(checkout.billing_account_id,sub.billing_account_id); initial_account:=account;
 if checkout.billing_account_id is not null and sub.billing_account_id is not null and checkout.billing_account_id&lt;&gt;sub.billing_account_id then raise exception 'PADDLE_INGRESS_IDENTITY_CONFLICT'; end if;
 -- Existing policy -&gt; account -&gt; ingress/logical evidence order. No new account
 -- is acquired after the ingress lock; concurrent identity discovery retries.
 perform public.billing_guard_lock(account,'test');
 perform pg_advisory_xact_lock(hashtextextended('paddle-ingress-test-v1',0));
 select * into checkout from public.billing_checkouts_v2 where provider='paddle' and environment='test' and provider_transaction_ref=tx;
 found_checkout:=found;
 select * into sub from public.billing_subscriptions_v2 where provider='paddle' and environment='test' and provider_subscription_ref=o-&gt;&gt;'subscriptionRef';
 if coalesce(checkout.billing_account_id,sub.billing_account_id) is distinct from initial_account then raise exception 'PADDLE_INGRESS_RETRY'; end if;
 if found_checkout and exists(select 1 from public.billing_paddle_event_observations po where po.checkout_id=checkout.id and po.disposition='correlated' and ((po.observation-&gt;&gt;'subscriptionRef' is not null and o-&gt;&gt;'subscriptionRef' is not null and po.observation-&gt;&gt;'subscriptionRef'&lt;&gt;o-&gt;&gt;'subscriptionRef') or (po.observation-&gt;&gt;'customerRef' is not null and o-&gt;&gt;'customerRef' is not null and po.observation-&gt;&gt;'customerRef'&lt;&gt;o-&gt;&gt;'customerRef'))) then raise exception 'PADDLE_INGRESS_IDENTITY_CONFLICT'; end if;
 if sub.id is not null and (sub.billing_account_id is distinct from account or not exists(select 1 from public.billing_customers_v2 c where c.id=sub.customer_id and c.provider_customer_ref=o-&gt;&gt;'customerRef')) then raise exception 'PADDLE_INGRESS_IDENTITY_CONFLICT'; end if;
 select e.id into ev from public.billing_webhook_events_v2 e where provider='paddle' and environment='test' and provider_event_ref=o-&gt;&gt;'eventRef';
 if ev is not null then
  select * into old from public.billing_paddle_event_observations where event_id=ev;
  -- Pre-lifecycle events retain their original projection forever. A replay
  -- may now expose added fields, but cannot retrofit authority into old rows.
  if old.event_id is null or (old.observation_sha256&lt;&gt;digest and
   old.observation is distinct from (logical-array(select k from unnest(array['planChangeOperationId','seatQuantityOperationId','paymentTotals','origin','billingPeriod','updatedAt','currentBillingPeriod','nextBilledAt','canceledAt','pausedAt','scheduledChange']) k where not (old.observation ? k))))
  then raise exception 'PADDLE_INGRESS_REPLAY_CONFLICT'; end if;
 end if;
 select * into delivery from public.billing_paddle_event_deliveries where notification_ref=p_notification_ref;
 if found then
  if delivery.event_id is distinct from ev or delivery.raw_payload_sha256 is distinct from p_raw_payload_sha256 then raise exception 'PADDLE_INGRESS_REPLAY_CONFLICT'; end if;
  return jsonb_build_object('accepted',true,'reused',true,'eventId',ev,'eventType',kind);
 end if;
 if ev is not null then
  verified:=public.record_verified_billing_event_v2(p,p_raw_payload_sha256,p_notification_ref);
  insert into public.billing_paddle_event_deliveries values(p_notification_ref,ev,p_raw_payload_sha256,(verified-&gt;&gt;'id')::uuid,now());
  return jsonb_build_object('accepted',true,'reused',true,'eventId',ev,'eventType',kind);
 end if;
 -- Only an existing same-account/subscription operation admits multiple plan
 -- mappings at retention. Initial checkouts never enter this branch. Signs and
 -- exact source/target membership are independently checked by settlement SQL.
 plan_delta := coalesce(kind='transaction.completed' and o-&gt;&gt;'origin'='subscription_update'
  and o ? 'planChangeOperationId' and not found_checkout and exists (
   select 1 from public.billing_operations_v2 op
   where op.operation_id::text=o-&gt;&gt;'planChangeOperationId'
    and op.provider='paddle' and op.environment='test' and op.operation_kind='plan_change'
    -- A committed dispatch or unresolved payment may converge from genuine
    -- webhooks, including an ambiguous response; terminal/support states may not.
    and op.status in ('provider_pending','awaiting_payment','ambiguous')
    and op.billing_account_id=account and op.subscription_id=sub.id
    and op.effective_timing='immediate' and op.source_cadence=op.target_cadence
    and op.source_additional_seats=0 and op.target_additional_seats=0),false);
 seat_delta:=coalesce(kind='transaction.completed' and o-&gt;&gt;'origin'='subscription_update'
 and o ? 'seatQuantityOperationId' and not found_checkout and exists(select 1 from public.billing_operations_v2 op
 where op.operation_id::text=o-&gt;&gt;'seatQuantityOperationId' and op.provider='paddle' and op.environment='test'
 and op.operation_kind='seat_quantity' and op.status in ('provider_pending','awaiting_payment','ambiguous')
 and op.billing_account_id=account and op.subscription_id=sub.id and op.effective_timing='immediate'
 and op.source_base_mapping_id=op.target_base_mapping_id and op.source_cadence=op.target_cadence),false);
 -- Unknown/mismatched items are retained as manual-review evidence only.
 for item in select value from jsonb_array_elements(o-&gt;'items') loop
  count_items:=count_items+1;
  select * into mapping from public.billing_price_mappings where provider='paddle' and environment='test' and provider_price_ref=item-&gt;&gt;'priceRef' and status in ('active','retired') for share;
  if not found then valid_items:=false; continue; end if;
  if mapping.catalogue_evidence_id is null or mapping.verification_sha256 is null
   or (mapping.identity_kind=any(roles) and not (plan_delta and mapping.identity_kind='plan') and not (seat_delta and mapping.identity_kind='addon')) or (cadence is not null and mapping.cadence&lt;&gt;cadence)
   or (item-&gt;&gt;'productRef' is not null and item-&gt;&gt;'productRef' is distinct from mapping.provider_product_ref)
   or item#&gt;&gt;'{unitPrice,currency}'&lt;&gt;'USD' or (item#&gt;&gt;'{unitPrice,amount}')::numeric&lt;&gt;mapping.unit_amount_minor
   or (mapping.identity_kind='plan' and not plan_delta and (item-&gt;&gt;'quantity')::int&lt;&gt;1)
   or (plan_delta and (mapping.identity_kind&lt;&gt;'plan' or item-&gt;&gt;'productRef' is distinct from mapping.provider_product_ref::text))
   or (mapping.identity_kind='addon' and (abs((item-&gt;&gt;'quantity')::int)&gt;5 or ((item-&gt;&gt;'quantity')::int&lt;1 and not seat_delta)))
   then valid_items:=false; end if;
  roles:=array_append(roles,mapping.identity_kind); cadence:=mapping.cadence;
  if found_checkout then
   if mapping.status&lt;&gt;'active' or not coalesce(((mapping.id=checkout.base_mapping_id and (item-&gt;&gt;'quantity')::int=1)
    or (mapping.id=checkout.seat_mapping_id and (item-&gt;&gt;'quantity')::int=checkout.requested_additional_seats)),false) then valid_items:=false; end if;
  end if;
 end loop;
 if not ('plan'=any(roles)) and not seat_delta then valid_items:=false;end if;
 if seat_delta and not exists(select 1 from public.billing_operations_v2 op where op.operation_id::text=o-&gt;&gt;'seatQuantityOperationId'
 and jsonb_array_length(o-&gt;'items')=jsonb_array_length(public.billing_paddle_seat_settlement_items_v1(op.id))
 and o-&gt;'items' @&gt; public.billing_paddle_seat_settlement_items_v1(op.id)) then valid_items:=false;end if;
 if found_checkout then
  select * into snapshot from public.billing_paddle_checkout_snapshots where checkout_id=checkout.id;
  if snapshot.checkout_id is null or not exists(select 1 from public.billing_price_mappings m where m.id=checkout.base_mapping_id and m.provider_price_ref=snapshot.base_price_ref and m.provider_product_ref=snapshot.base_product_ref and m.catalogue_evidence_id=snapshot.base_evidence_id) or (checkout.requested_additional_seats&gt;0 and not exists(select 1 from public.billing_price_mappings m where m.id=checkout.seat_mapping_id and m.provider_price_ref=snapshot.seat_price_ref and m.provider_product_ref=snapshot.seat_product_ref and m.catalogue_evidence_id=snapshot.seat_evidence_id)) or count_items&lt;&gt;(case when checkout.requested_additional_seats&gt;0 then 2 else 1 end) then valid_items:=false; end if;
  if valid_items then state:='correlated'; else state:='manual_review'; end if;
 elsif sub.id is not null then
  state:=case when valid_items then 'correlated' else 'manual_review' end;
 end if;
 if not valid_items then state:='manual_review'; end if;
 if kind&lt;&gt;'transaction.completed' and state='correlated' then
  if sub.id is null then
   if o-&gt;&gt;'customerRef' is null then state:='pending';
   else
    if exists(
      select 1 from public.billing_customers_v2 c
      where c.provider='paddle' and c.environment='test'
        and c.provider_customer_ref=o-&gt;&gt;'customerRef'
        and c.billing_account_id&lt;&gt;account
    ) then raise exception 'PADDLE_INGRESS_IDENTITY_CONFLICT'; end if;
    select * into current_customer
    from public.billing_customers_v2 c
    where c.billing_account_id=account and c.provider='paddle'
      and c.environment='test' and c.identity_status='current';
    if current_customer.id is null then
      insert into public.billing_customers_v2(
        billing_account_id,provider,environment,provider_customer_ref,identity_source
      ) values(
        account,'paddle','test',o-&gt;&gt;'customerRef','verified_provider_event'
      ) returning id into cid;
      insert into public.billing_subscriptions_v2(
        billing_account_id,customer_id,provider,environment,
        provider_subscription_ref,provider_status,provider_updated_at
      ) values(
        account,cid,'paddle','test',o-&gt;&gt;'subscriptionRef',o-&gt;&gt;'status',observed
      ) returning id into sid;
    elsif current_customer.provider_customer_ref=o-&gt;&gt;'customerRef' then
      cid:=current_customer.id;
      insert into public.billing_subscriptions_v2(
        billing_account_id,customer_id,provider,environment,
        provider_subscription_ref,provider_status,provider_updated_at
      ) values(
        account,cid,'paddle','test',o-&gt;&gt;'subscriptionRef',o-&gt;&gt;'status',observed
      ) returning id into sid;
    elsif kind&lt;&gt;'subscription.created'
      or not found_checkout
      or exists(
        select 1 from public.billing_paddle_checkout_certification_fixtures f
        where f.checkout_id=checkout.id
      )
      or current_customer.identity_source&lt;&gt;'certification_fixture'
    then raise exception 'PADDLE_INGRESS_IDENTITY_CONFLICT';
    else
      select * into old_sub
      from public.billing_subscriptions_v2 s
      where s.customer_id=current_customer.id and s.shadow_status='current';
      if old_sub.id is null
        or not public.billing_paddle_certification_shadow_v1(current_customer.id,old_sub.id)
      then raise exception 'PADDLE_INGRESS_IDENTITY_CONFLICT'; end if;
      cid:=gen_random_uuid();
      sid:=gen_random_uuid();
      transition_at:=clock_timestamp();
      old_cid:=current_customer.id;
      old_sid:=old_sub.id;
      update public.billing_customers_v2
      set identity_status='superseded',superseded_at=transition_at,
        superseded_by_customer_id=cid,updated_at=transition_at
      where id=old_cid;
      insert into public.billing_customers_v2(
        id,billing_account_id,provider,environment,provider_customer_ref,
        identity_status,identity_source
      ) values(
        cid,account,'paddle','test',o-&gt;&gt;'customerRef',
        'current','verified_provider_event'
      );
      insert into public.billing_subscriptions_v2(
        id,billing_account_id,customer_id,provider,environment,
        provider_subscription_ref,provider_status,provider_updated_at,shadow_status
      ) values(
        sid,account,cid,'paddle','test',o-&gt;&gt;'subscriptionRef',
        o-&gt;&gt;'status',observed,'current'
      );
      update public.billing_subscriptions_v2
      set shadow_status='superseded',superseded_at=transition_at,
        superseded_by_subscription_id=sid,updated_at=transition_at
      where id=old_sid;
      supersede:=true;
    end if;
   end if;
  elsif sub.account_subscription_id is not null then
   -- Linked subscriptions change only through paired lifecycle authority.
   null;
  elsif sub.shadow_status='superseded' then
   state:='stale';
  else
   if sub.provider_updated_at&gt;observed then state:='stale';
   elsif sub.provider_updated_at=observed then
    if sub.provider_status is distinct from o-&gt;&gt;'status' or exists(select 1 from public.billing_paddle_event_observations po where po.observation-&gt;&gt;'subscriptionRef'=o-&gt;&gt;'subscriptionRef' and po.observation-&gt;&gt;'kind' like 'subscription.%' and (po.observation-&gt;&gt;'occurredAt')::timestamptz=observed and po.observation-&gt;'items'&lt;&gt;o-&gt;'items') then state:='manual_review'; end if;
   else
    update public.billing_subscriptions_v2 set provider_status=o-&gt;&gt;'status',provider_updated_at=observed,updated_at=now() where id=sub.id;
   end if;
  end if;
 end if;
 verified:=public.record_verified_billing_event_v2(p,p_raw_payload_sha256,p_notification_ref);
 insert into public.billing_webhook_events_v2(provider,environment,provider_event_ref,provider_event_name,resource_type,resource_ref,occurred_at,first_payload_sha256,subscription_ref,customer_ref,processing_status)
 values('paddle','test',o-&gt;&gt;'eventRef',kind,p#&gt;&gt;'{eventEvidence,resourceType}',p#&gt;&gt;'{eventEvidence,resourceRef}',observed,p_raw_payload_sha256,o-&gt;&gt;'subscriptionRef',o-&gt;&gt;'customerRef',case when state='manual_review' then 'manual_review' else 'deferred' end) returning id into ev;
 insert into public.billing_paddle_event_observations(event_id,observation,observation_sha256,checkout_id,disposition) values(ev,logical,digest,checkout.id,state);
 insert into public.billing_paddle_event_deliveries values(p_notification_ref,ev,p_raw_payload_sha256,(verified-&gt;&gt;'id')::uuid,now());
 if supersede then
  insert into public.billing_provider_identity_transitions_v2(
    billing_account_id,provider,environment,old_customer_id,new_customer_id,
    old_subscription_id,new_subscription_id,triggering_event_id,
    triggering_verified_evidence_id,correlated_checkout_id,transition_reason
  ) values(
    account,'paddle','test',old_cid,cid,old_sid,sid,ev,
    (verified-&gt;&gt;'id')::uuid,checkout.id,
    'certification_identity_superseded_by_verified_provider_identity'
  );
 end if;
 return jsonb_build_object('accepted',true,'reused',false,'eventId',ev,'eventType',kind);
end $function$

CREATE OR REPLACE FUNCTION public.is_client_checkin_due_date(p_client_id uuid, p_due_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_start_date date;
  v_frequency text;
  v_occurrence integer := 0;
  v_calculated_due date;
begin
  if p_client_id is null or p_due_date is null then
    return false;
  end if;

  select c.checkin_start_date, c.checkin_frequency
  into v_start_date, v_frequency
  from public.clients c
  where c.id = p_client_id;

  if v_start_date is null then
    return false;
  end if;

  loop
    v_calculated_due := public.calculate_checkin_due_date(
      v_start_date,
      v_frequency,
      v_occurrence
    );

    exit when v_calculated_due is null or v_calculated_due &gt; p_due_date;

    if v_calculated_due = p_due_date then
      return true;
    end if;

    v_occurrence := v_occurrence + 1;
    exit when v_occurrence &gt; 1000;
  end loop;

  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.is_commercial_action_allowed(p_mode text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if p_action is null or p_action &lt;&gt; all(array['billing_manage','account_security','data_export','remediation','workspace_read','delivery_write','business_configuration_write','acquisition_write','capacity_growth','client_self_service','client_coached_read','client_coached_write']) then
    raise exception 'ACCOUNT_ACCESS_ACTION_NOT_ALLOWED' using errcode='22023';
  end if;
  if p_mode is null or p_mode &lt;&gt; all(array['onboarding','full','existing_delivery_only','read_only','none']) then return false; end if;
  if p_action=any(array['billing_manage','account_security','data_export','remediation','client_self_service','client_coached_read']) then return true; end if;
  if p_mode='full' then return true; end if;
  if p_action='workspace_read' then return p_mode in ('existing_delivery_only','read_only'); end if;
  return p_mode='existing_delivery_only' and p_action in ('delivery_write','client_coached_write');
end $function$

CREATE OR REPLACE FUNCTION public.lead_chat_mark_read(p_lead_id uuid, p_up_to_message_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor_user_id uuid;
  v_conversation public.lead_conversations%rowtype;
  v_message_id uuid;
  v_message_time timestamptz;
begin
  v_actor_user_id := auth.uid();
  if v_actor_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select *
  into v_conversation
  from public.lead_conversations c
  where c.lead_id = p_lead_id
  limit 1;

  if not found then
    return;
  end if;

  if v_actor_user_id &lt;&gt; v_conversation.pt_user_id
     and v_actor_user_id &lt;&gt; v_conversation.lead_user_id then
    raise exception 'Not allowed to access this conversation';
  end if;

  if p_up_to_message_id is not null then
    select m.id, m.sent_at
    into v_message_id, v_message_time
    from public.lead_messages m
    where m.id = p_up_to_message_id
      and m.conversation_id = v_conversation.id
    limit 1;
  else
    select m.id, m.sent_at
    into v_message_id, v_message_time
    from public.lead_messages m
    where m.conversation_id = v_conversation.id
    order by m.sent_at desc, m.id desc
    limit 1;
  end if;

  update public.lead_conversation_participants p
  set
    last_read_message_id = coalesce(v_message_id, p.last_read_message_id),
    last_read_at = coalesce(v_message_time, now())
  where p.conversation_id = v_conversation.id
    and p.user_id = v_actor_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.lead_chat_send_message(p_lead_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor_user_id uuid;
  v_trimmed_body text;
  v_conversation public.lead_conversations%rowtype;
  v_message_id uuid;
  v_message_timestamp timestamptz := now();
  v_pt_message_count integer;
  v_lead_message_count integer;
  v_contacted_rows integer;
begin
  v_actor_user_id := auth.uid();
  if v_actor_user_id is null then
    raise exception 'Not authenticated';
  end if;

  v_trimmed_body := nullif(btrim(coalesce(p_body, '')), '');
  if v_trimmed_body is null then
    raise exception 'Message body is required';
  end if;

  perform public.ensure_lead_conversation_for_lead(p_lead_id);

  select *
  into v_conversation
  from public.lead_conversations c
  where c.lead_id = p_lead_id
  for update;

  if not found then
    raise exception 'Lead conversation not found';
  end if;

  if v_actor_user_id &lt;&gt; v_conversation.pt_user_id
     and v_actor_user_id &lt;&gt; v_conversation.lead_user_id then
    raise exception 'Not allowed to message this lead';
  end if;

  if v_conversation.status &lt;&gt; 'open' then
    raise exception 'Lead conversation is archived';
  end if;

  insert into public.lead_messages (
    conversation_id,
    sender_user_id,
    body,
    sent_at
  )
  values (
    v_conversation.id,
    v_actor_user_id,
    v_trimmed_body,
    v_message_timestamp
  )
  returning id into v_message_id;

  update public.lead_conversations c
  set
    last_message_at = v_message_timestamp,
    last_message_preview = left(v_trimmed_body, 200)
  where c.id = v_conversation.id;

  update public.lead_conversation_participants p
  set
    last_read_message_id = v_message_id,
    last_read_at = v_message_timestamp
  where p.conversation_id = v_conversation.id
    and p.user_id = v_actor_user_id;

  if v_actor_user_id = v_conversation.pt_user_id then
    select count(*)
    into v_pt_message_count
    from public.lead_messages m
    where m.conversation_id = v_conversation.id
      and m.sender_user_id = v_conversation.pt_user_id;

    if v_pt_message_count = 1 then
      perform public.log_lead_chat_event(
        p_lead_id,
        v_conversation.id,
        v_actor_user_id,
        'lead_first_pt_message_sent',
        jsonb_build_object('message_id', v_message_id)
      );
    end if;

    perform public.notify_user(
      v_conversation.lead_user_id,
      'lead_chat_message_received',
      'New message from your coach',
      left(v_trimmed_body, 140),
      '/app/home',
      'lead_conversation',
      v_conversation.id,
      null,
      jsonb_build_object(
        'lead_id', p_lead_id,
        'conversation_id', v_conversation.id
      ),
      'messages',
      'normal'
    );
  else
    select count(*)
    into v_lead_message_count
    from public.lead_messages m
    where m.conversation_id = v_conversation.id
      and m.sender_user_id = v_conversation.lead_user_id;

    if v_lead_message_count = 1 then
      perform public.log_lead_chat_event(
        p_lead_id,
        v_conversation.id,
        v_actor_user_id,
        'lead_first_reply_sent',
        jsonb_build_object('message_id', v_message_id)
      );
    end if;

    perform public.notify_user(
      v_conversation.pt_user_id,
      'lead_chat_message_received',
      'New lead reply',
      left(v_trimmed_body, 140),
      format('/pt-hub/leads/%s', p_lead_id),
      'lead_conversation',
      v_conversation.id,
      null,
      jsonb_build_object(
        'lead_id', p_lead_id,
        'conversation_id', v_conversation.id
      ),
      'messages',
      'normal'
    );
  end if;

  update public.pt_hub_leads lead
  set status = 'contacted'
  where lead.id = p_lead_id
    and lead.status = 'new';

  get diagnostics v_contacted_rows = row_count;
  if v_contacted_rows &gt; 0 then
    perform public.log_lead_chat_event(
      p_lead_id,
      v_conversation.id,
      v_actor_user_id,
      'lead_status_moved_to_contacted',
      jsonb_build_object('message_id', v_message_id)
    );
  end if;

  return v_message_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.link_converted_lead_conversation(p_lead_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_lead record;
  v_active_conversation_id uuid;
begin
  if p_lead_id is null then
    return null;
  end if;

  select
    lead.id,
    lead.applicant_user_id,
    lead.status,
    lead.converted_workspace_id,
    lead.converted_client_id
  into v_lead
  from public.pt_hub_leads lead
  where lead.id = p_lead_id
  limit 1;

  if not found
     or v_lead.status &lt;&gt; 'converted'
     or v_lead.applicant_user_id is null
     or v_lead.converted_workspace_id is null
     or v_lead.converted_client_id is null then
    return null;
  end if;

  if not exists (
    select 1
    from public.clients c
    where c.id = v_lead.converted_client_id
      and c.workspace_id = v_lead.converted_workspace_id
      and c.user_id = v_lead.applicant_user_id
      and c.status = 'active'::public.client_status
  ) then
    return null;
  end if;

  insert into public.conversations (workspace_id, client_id)
  values (v_lead.converted_workspace_id, v_lead.converted_client_id)
  on conflict on constraint conversations_workspace_client_key do nothing;

  select conv.id
  into v_active_conversation_id
  from public.conversations conv
  where conv.workspace_id = v_lead.converted_workspace_id
    and conv.client_id = v_lead.converted_client_id
  limit 1;

  if v_active_conversation_id is null then
    return null;
  end if;

  update public.lead_conversations lc
  set converted_conversation_id = v_active_conversation_id
  where lc.lead_id = v_lead.id
    and lc.converted_conversation_id is distinct from v_active_conversation_id;

  return v_active_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_paddle_checkout_ready_v1(p_actor uuid, p_attempt uuid, p_operation uuid, p_transaction text, p_status text, p_currency text, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a uuid; t public.billing_checkouts_v2%rowtype; s public.billing_paddle_checkout_snapshots%rowtype; expected jsonb;
begin
 perform public.billing_guard_actor();
 select billing_account_id into a from public.billing_checkouts_v2 where id=p_attempt and created_by_user_id=p_actor;
 if a is null then raise exception 'PADDLE_CHECKOUT_FORBIDDEN'; end if;
 perform public.billing_guard_lock(a,'test');
 select * into strict t from public.billing_checkouts_v2 where id=p_attempt for update;
 if t.environment&lt;&gt;'test' or t.status&lt;&gt;'creating' or t.operation_id is distinct from p_operation then raise exception 'PADDLE_CHECKOUT_CONFLICT'; end if;
 select * into strict s from public.billing_paddle_checkout_snapshots where checkout_id=t.id;
 expected:=jsonb_build_array(jsonb_build_object('priceReference',s.base_price_ref,'productReference',s.base_product_ref,'quantity',1));
 if t.requested_additional_seats&gt;0 then expected:=expected||jsonb_build_array(jsonb_build_object('priceReference',s.seat_price_ref,'productReference',s.seat_product_ref,'quantity',t.requested_additional_seats)); end if;
 if p_transaction is null or octet_length(p_transaction) not between 1 and 256 or p_transaction ~ '[[:space:][:cntrl:]]' or p_status is null or p_status not in ('draft','ready')
 or p_currency is distinct from 'USD' or p_items is distinct from expected then raise exception 'PADDLE_CHECKOUT_RESPONSE_MISMATCH'; end if;
 update public.billing_checkouts_v2 set status='ready',provider_transaction_ref=p_transaction,updated_at=clock_timestamp() where id=t.id;
end $function$

CREATE OR REPLACE FUNCTION public.normalize_client_lifecycle_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.lifecycle_state is null or trim(new.lifecycle_state) = '' then
    new.lifecycle_state := coalesce(old.lifecycle_state, 'active');
  else
    new.lifecycle_state := trim(new.lifecycle_state);
  end if;

  if tg_op = 'UPDATE'
     and new.lifecycle_state is not distinct from old.lifecycle_state
     and new.status is distinct from old.status then
    new.lifecycle_state := case new.status::text
      when 'paused' then 'paused'
      when 'completed' then 'completed'
      else 'active'
    end;
  end if;

  new.paused_reason := nullif(trim(coalesce(new.paused_reason, '')), '');
  new.churn_reason := nullif(trim(coalesce(new.churn_reason, '')), '');

  if new.lifecycle_state = 'paused' and new.paused_reason is null then
    raise exception 'Pause reason is required';
  end if;

  if new.lifecycle_state = 'churned' and new.churn_reason is null then
    raise exception 'Churn reason is required';
  end if;

  if new.lifecycle_state &lt;&gt; 'paused' then
    new.paused_reason := null;
  end if;

  if new.lifecycle_state &lt;&gt; 'churned' then
    new.churn_reason := null;
  end if;

  if tg_op = 'INSERT'
     or new.lifecycle_state is distinct from old.lifecycle_state then
    new.lifecycle_changed_at := now();
  elsif new.lifecycle_changed_at is null then
    new.lifecycle_changed_at := coalesce(old.lifecycle_changed_at, now());
  end if;

  new.status := case new.lifecycle_state
    when 'paused' then 'paused'::public.client_status
    when 'completed' then 'completed'::public.client_status
    when 'churned' then 'completed'::public.client_status
    else 'active'::public.client_status
  end;

  return new;
end;
$function$

