CREATE OR REPLACE FUNCTION public.notification_pref_enabled(p_user_id uuid, p_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  prefs public.notification_preferences%rowtype;
begin
  if p_user_id is null then
    return false;
  end if;

  select *
  into prefs
  from public.notification_preferences
  where user_id = p_user_id;

  if prefs.user_id is null then
    return true;
  end if;

  if coalesce(prefs.in_app_enabled, true) = false then
    return false;
  end if;

  case p_type
    when 'workout_assigned' then return coalesce(prefs.workout_assigned, true);
    when 'workout_updated' then return coalesce(prefs.workout_updated, true);
    when 'checkin_requested' then return coalesce(prefs.checkin_requested, true);
    when 'checkin_submitted' then return coalesce(prefs.checkin_submitted, true);
    when 'message_received' then return coalesce(prefs.message_received, true);
    when 'milestone_achieved' then return coalesce(prefs.milestone_events, true);
    when 'workout_due_today' then return coalesce(prefs.reminders_enabled, true);
    when 'checkin_due_tomorrow' then return coalesce(prefs.reminders_enabled, true);
    when 'client_inactive' then return coalesce(prefs.inactivity_alerts, true);
    when 'system' then return coalesce(prefs.system_events, true);
    when 'client_joined_workspace' then return coalesce(prefs.system_events, true);
    when 'invite_accepted' then return coalesce(prefs.system_events, true);
    else
      return true;
  end case;
end;
$function$

CREATE OR REPLACE FUNCTION public.notification_specific_client_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  -- Preserve coach links and specific routes, only repair generic client routes.
  if new.entity_id is null then return new; end if;
  if new.action_url in ('/app/home','/app/checkin','/app/checkins','/app/workouts','/app/messages') then
    if new.entity_type = 'assigned_workout' then
      new.action_url := '/app/workouts/' || new.entity_id::text;
      -- Events store entity_id as text; notifications use uuid.
      new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object('day_type', (select day_type from public.assigned_workouts where id::text = new.entity_id::text));
    elsif new.entity_type = 'checkin' then
      new.action_url := '/app/checkins?checkin=' || new.entity_id::text;
    elsif new.entity_type = 'conversation' then
      new.action_url := '/app/messages?thread=workspace%3A' || new.entity_id::text;
    end if;
  end if;
  return new;
end; $function$

