CREATE OR REPLACE FUNCTION public.preview_billing_plan_change(p_owner uuid, p_environment text, p_target_plan text, p_target_cadence text, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb; b public.billing_provider_subscriptions%rowtype; s public.account_subscriptions%rowtype; m public.billing_provider_variant_mappings%rowtype; t public.billing_provider_variant_mappings%rowtype; c jsonb; pf jsonb; source_key text;
begin
  ctx:=public.billing_plan_change_context(p_owner,p_environment);
  b:=jsonb_populate_record(null::public.billing_provider_subscriptions,ctx-&gt;'subscription'); s:=jsonb_populate_record(null::public.account_subscriptions,ctx-&gt;'local'); m:=jsonb_populate_record(null::public.billing_provider_variant_mappings,ctx-&gt;'mapping');
  perform 1 from public.billing_accounts where id=b.billing_account_id for update;
  if p_snapshot-&gt;&gt;'payment_processor'='paypal' then raise exception 'BILLING_PLAN_CHANGE_PAYPAL_UNSUPPORTED'; end if;
  if p_snapshot-&gt;&gt;'payment_processor' is distinct from 'card' or p_snapshot-&gt;&gt;'status' is distinct from 'active' or (p_snapshot-&gt;&gt;'cancelled')::boolean is distinct from false or
    s.status&lt;&gt;'active' or s.cancel_at_period_end or b.provider_status&lt;&gt;'active' or b.reconciliation_status&lt;&gt;'processed' then raise exception 'BILLING_PLAN_CHANGE_NOT_ELIGIBLE'; end if;
  if (p_snapshot-&gt;&gt;'provider',p_snapshot-&gt;&gt;'environment',p_snapshot-&gt;&gt;'store_id',p_snapshot-&gt;&gt;'subscription_id',p_snapshot-&gt;&gt;'customer_id',p_snapshot-&gt;&gt;'product_id',p_snapshot-&gt;&gt;'variant_id',p_snapshot-&gt;&gt;'price_id',p_snapshot-&gt;&gt;'order_id',p_snapshot-&gt;&gt;'order_item_id',p_snapshot-&gt;&gt;'first_subscription_item_id') is distinct from
    (b.provider,b.environment,b.provider_store_id,b.provider_subscription_id,b.provider_customer_id,m.provider_product_id,m.provider_variant_id,m.provider_price_id,b.provider_order_id,b.provider_order_item_id,b.first_subscription_item_id) or
    (p_snapshot-&gt;&gt;'quantity')::integer is distinct from 1+b.approved_additional_coach_seats or p_snapshot-&gt;&gt;'trial_ends_at' is not null or (p_snapshot-&gt;&gt;'updated_at')::timestamptz&lt;b.provider_updated_at or
    (p_snapshot-&gt;&gt;'updated_at') is null or (p_snapshot-&gt;&gt;'created_at')::timestamptz is distinct from b.provider_created_at or
    m.plan_version_id&lt;&gt;s.plan_version_id or m.status not in ('active','retired') then raise exception 'BILLING_PLAN_CHANGE_UNAPPROVED_PROVIDER_STATE'; end if;
  if exists(select 1 from public.billing_plan_change_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed')) then raise exception 'BILLING_PLAN_CHANGE_ALREADY_PENDING'; end if;
  if exists(select 1 from public.billing_seat_quantity_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed')) then raise exception 'BILLING_PLAN_CHANGE_OPERATION_CONFLICT'; end if;
  if b.approved_additional_coach_seats&gt;0 and ((p_snapshot#&gt;&gt;'{verified_item,item_id}',p_snapshot#&gt;&gt;'{verified_item,subscription_id}',p_snapshot#&gt;&gt;'{verified_item,price_id}',p_snapshot#&gt;&gt;'{verified_item,quantity}') is distinct from
    (b.first_subscription_item_id,b.provider_subscription_id,m.provider_price_id,(1+b.approved_additional_coach_seats)::text) or (p_snapshot#&gt;&gt;'{verified_item,is_usage_based}')::boolean is distinct from false) then raise exception 'BILLING_PLAN_CHANGE_UNAPPROVED_PROVIDER_STATE'; end if;

  select plan_key into source_key from public.commercial_plan_versions where id=m.plan_version_id;
  c:=public.classify_billing_plan_change(source_key,m.cadence,p_target_plan,p_target_cadence);
  select v.* into t from public.billing_provider_variant_mappings v join public.commercial_plan_versions p on p.id=v.plan_version_id where p.plan_key=p_target_plan and p.status='active' and v.status='active' and v.cadence=p_target_cadence and v.environment=p_environment and v.provider_store_id=b.provider_store_id for share of v;
  if t.id is null then raise exception 'BILLING_PLAN_CHANGE_TARGET_MAPPING_UNAVAILABLE'; end if;
  if b.approved_additional_coach_seats&gt;(select max_coach_seats-included_coach_seats from public.commercial_plan_versions where id=t.plan_version_id) then raise exception 'BILLING_PLAN_CHANGE_CAPACITY_BLOCKED'; end if;
  if b.approved_additional_coach_seats&gt;0 and not exists(select 1 from public.billing_quantity_price_contracts where variant_mapping_id=t.id and status='active') then raise exception 'BILLING_PLAN_CHANGE_TARGET_MAPPING_UNAVAILABLE'; end if;
  if c-&gt;&gt;'effectiveTiming'='period_end' and (s.current_period_ends_at is null or s.current_period_ends_at&lt;=clock_timestamp() or (p_snapshot-&gt;&gt;'renews_at')::timestamptz is distinct from s.current_period_ends_at) then raise exception 'BILLING_PLAN_CHANGE_EFFECTIVE_DATE_INVALID'; end if;
  pf:=public.billing_plan_change_preflight(p_owner,b.billing_account_id,t.plan_version_id);
  return c||jsonb_build_object('sourcePlanKey',source_key,'sourceCadence',m.cadence,'targetPlanKey',p_target_plan,'targetCadence',p_target_cadence,'currentPriceMinor',m.unit_amount_minor+b.approved_additional_coach_seats*case m.cadence when 'monthly' then 1200 else 12000 end,'targetPriceMinor',t.unit_amount_minor+b.approved_additional_coach_seats*case t.cadence when 'monthly' then 1200 else 12000 end,'currency','USD',
    'effectiveAt',case when c-&gt;&gt;'effectiveTiming'='period_end' then s.current_period_ends_at else null end,'blockers',case when c-&gt;&gt;'effectiveTiming'='period_end' then pf-&gt;'blockers' else '[]'::jsonb end,'dataQualityIssue',pf#&gt;'{snapshot,hasAnyDataQualityIssue}');
end $function$

CREATE OR REPLACE FUNCTION public.preview_billing_seat_quantity(p_owner uuid, p_environment text, p_target integer, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ctx jsonb; b public.billing_provider_subscriptions%rowtype; s public.account_subscriptions%rowtype; m public.billing_provider_variant_mappings%rowtype;
  p public.commercial_plan_versions%rowtype; a public.commercial_addon_versions%rowtype; c public.billing_quantity_price_contracts%rowtype;
  d jsonb; code text; lim integer; unit integer; direction text;
begin
  ctx:=public.billing_seat_quantity_context(p_owner,p_environment);
  perform 1 from public.billing_accounts where id=(ctx#&gt;&gt;'{subscription,billing_account_id}')::uuid for update;
  ctx:=public.billing_seat_quantity_context(p_owner,p_environment);
  b:=jsonb_populate_record(null::public.billing_provider_subscriptions,ctx-&gt;'subscription'); s:=jsonb_populate_record(null::public.account_subscriptions,ctx-&gt;'local'); m:=jsonb_populate_record(null::public.billing_provider_variant_mappings,ctx-&gt;'mapping');
  select * into strict p from public.commercial_plan_versions where id=s.plan_version_id;
  select * into c from public.billing_quantity_price_contracts where variant_mapping_id=m.id for share;
  select * into a from public.commercial_addon_versions where id=c.addon_version_id;
  if p_target is null or p_target&lt;0 or p_target&gt;p.max_coach_seats-p.included_coach_seats then raise exception 'BILLING_SEAT_QUANTITY_TARGET_INVALID'; end if;
  if s.status&lt;&gt;'active' or s.cancel_at_period_end or b.provider_status&lt;&gt;'active' or b.provider_cancelled or b.reconciliation_status&lt;&gt;'processed' or
    p_snapshot-&gt;&gt;'status' is distinct from 'active' or (p_snapshot-&gt;&gt;'cancelled')::boolean is distinct from false or p_snapshot-&gt;&gt;'trial_ends_at' is not null then code:='BILLING_SEAT_QUANTITY_NOT_ELIGIBLE'; end if;
  if m.status&lt;&gt;'active' or c.id is null or c.status&lt;&gt;'active' or a.status&lt;&gt;'active' then code:='BILLING_SEAT_QUANTITY_MAPPING_UNAVAILABLE'; end if;
  if b.first_subscription_item_id is null then code:='BILLING_SEAT_QUANTITY_ITEM_MISSING'; end if;
  if p_snapshot-&gt;&gt;'payment_processor' is distinct from 'card' then code:=case when p_snapshot-&gt;&gt;'payment_processor'='paypal' then 'BILLING_SEAT_QUANTITY_PAYPAL_UNSUPPORTED' else 'BILLING_SEAT_QUANTITY_NOT_ELIGIBLE' end; end if;
  if (p_snapshot-&gt;&gt;'provider',p_snapshot-&gt;&gt;'environment',p_snapshot-&gt;&gt;'store_id',p_snapshot-&gt;&gt;'subscription_id',p_snapshot-&gt;&gt;'customer_id',p_snapshot-&gt;&gt;'order_id',p_snapshot-&gt;&gt;'order_item_id',p_snapshot-&gt;&gt;'product_id',p_snapshot-&gt;&gt;'variant_id',p_snapshot-&gt;&gt;'price_id',p_snapshot-&gt;&gt;'first_subscription_item_id') is distinct from
    (b.provider,b.environment,b.provider_store_id,b.provider_subscription_id,b.provider_customer_id,b.provider_order_id,b.provider_order_item_id,m.provider_product_id,m.provider_variant_id,m.provider_price_id,b.first_subscription_item_id) or
    (p_snapshot-&gt;&gt;'created_at')::timestamptz is distinct from b.provider_created_at or (p_snapshot-&gt;&gt;'updated_at') is null or (p_snapshot-&gt;&gt;'updated_at')::timestamptz&lt;b.provider_updated_at or
    (p_snapshot-&gt;&gt;'quantity')::integer is distinct from 1+b.approved_additional_coach_seats or b.quantity&lt;&gt;1+b.approved_additional_coach_seats then code:='BILLING_SEAT_QUANTITY_UNAPPROVED_DRIFT'; end if;
  if exists(select 1 from public.billing_plan_change_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed')) or
    exists(select 1 from public.billing_seat_quantity_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed')) then code:='BILLING_SEAT_QUANTITY_OPERATION_CONFLICT'; end if;
  select value into d from jsonb_array_elements(public.resolve_account_capacity(p_owner,b.billing_account_id)-&gt;'dimensions') where value-&gt;&gt;'key'='coach_seats';
  lim:=least(p.max_coach_seats,p.included_coach_seats+p_target);
  direction:=case when p_target&gt;b.approved_additional_coach_seats then 'increase' when p_target&lt;b.approved_additional_coach_seats then 'reduction' else 'no-op' end;
  if direction='reduction' and ((d-&gt;&gt;'committed')::integer&gt;lim or (d-&gt;&gt;'dataQualityIssue')::boolean) then code:='BILLING_SEAT_QUANTITY_CAPACITY_BLOCKED'; end if;
  if direction='reduction' and (s.current_period_ends_at is null or s.current_period_ends_at&lt;=clock_timestamp() or (p_snapshot-&gt;&gt;'renews_at')::timestamptz is distinct from s.current_period_ends_at) then code:='BILLING_SEAT_QUANTITY_NOT_ELIGIBLE'; end if;
  unit:=case m.cadence when 'monthly' then coalesce(a.monthly_unit_amount_minor,1200) else coalesce(a.annual_unit_amount_minor,12000) end;
  return jsonb_build_object('planKey',p.plan_key,'cadence',m.cadence,'includedSeats',p.included_coach_seats,'currentAdditionalSeats',b.approved_additional_coach_seats,
    'targetAdditionalSeats',p_target,'maximumSeats',p.max_coach_seats,'maximumAdditionalSeats',p.max_coach_seats-p.included_coach_seats,'currentProviderQuantity',b.quantity,'targetProviderQuantity',1+p_target,
    'currentEffectiveLimit',public.billing_seat_effective_limit(b.billing_account_id),'targetEffectiveLimit',lim,'actual',d-&gt;'actual','pending',d-&gt;'pending','reserved',d-&gt;'reserved','committed',d-&gt;'committed',
    'direction',direction,'timing',case when direction='reduction' then 'period_end' else 'immediate' end,'effectiveAt',case when direction='reduction' then s.current_period_ends_at else null end,
    'unitPriceMinor',unit,'currentTotalMinor',m.unit_amount_minor+unit*b.approved_additional_coach_seats,'targetTotalMinor',m.unit_amount_minor+unit*p_target,'currency','USD',
    'capacityBlocked',direction='reduction' and (d-&gt;&gt;'committed')::integer&gt;lim,'eligible',code is null,'errorCode',code,
    'disclosure','Recurring list prices exclude provider-calculated proration, taxes and credits. Increased capacity requires verified payment. Reductions take effect at renewal and limit new invitations immediately.');
end $function$

CREATE OR REPLACE FUNCTION public.preview_paddle_plan_change_v1(p_owner uuid, p_target_plan text, p_target_cadence text, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c jsonb; t public.billing_price_mappings%rowtype; classification jsonb; pf jsonb; start_at timestamptz; end_at timestamptz;
begin
 c:=public.paddle_plan_change_context_v1(p_owner);
 if not (select paddle_reconciliation_enabled from public.billing_runtime_policy where id=1) then raise exception 'BILLING_PLAN_CHANGE_NOT_ELIGIBLE'; end if;
 if p_target_cadence is distinct from c-&gt;&gt;'cadence' then raise exception 'BILLING_PLAN_CHANGE_MIXED_DIRECTION_UNSUPPORTED'; end if;
 if p_target_plan not in ('launch','growth','scale') or p_target_plan is null then raise exception 'BILLING_INVALID_INPUT'; end if;
 if exists(select 1 from public.billing_operations_v2 where subscription_id=(c-&gt;&gt;'subscriptionId')::uuid and status not in ('completed','canceled','failed')) then raise exception 'BILLING_PLAN_CHANGE_ALREADY_PENDING'; end if;
 if (p_snapshot-&gt;&gt;'subscriptionRef',p_snapshot-&gt;&gt;'customerRef',p_snapshot-&gt;&gt;'priceRef',p_snapshot-&gt;&gt;'productRef',p_snapshot-&gt;&gt;'status',p_snapshot-&gt;&gt;'cadence')
 is distinct from (c-&gt;&gt;'subscriptionRef',c-&gt;&gt;'customerRef',c-&gt;&gt;'sourcePriceRef',c-&gt;&gt;'sourceProductRef','active',c-&gt;&gt;'cadence')
 or p_snapshot-&gt;'quantity' is distinct from '1'::jsonb or p_snapshot-&gt;'cancelled' is distinct from 'false'::jsonb
 or p_snapshot-&gt;&gt;'updatedAt' is null or (p_snapshot-&gt;&gt;'updatedAt')::timestamptz&lt;(c-&gt;&gt;'providerUpdatedAt')::timestamptz
 then raise exception 'BILLING_PLAN_CHANGE_UNAPPROVED_PROVIDER_STATE'; end if;
 start_at:=public.billing_paddle_timestamp_v1(p_snapshot-&gt;'periodStart');end_at:=public.billing_paddle_timestamp_v1(p_snapshot-&gt;'periodEnd');
 if end_at&lt;=public.billing_paddle_plan_now_v1() or end_at&lt;&gt;(start_at at time zone 'UTC'+case when p_target_cadence='monthly' then interval '1 month' else interval '1 year' end) at time zone 'UTC'
 or c-&gt;&gt;'periodEnd' is null or (c-&gt;&gt;'periodEnd' is not null and ((c-&gt;&gt;'periodStart')::timestamptz,(c-&gt;&gt;'periodEnd')::timestamptz) is distinct from (start_at,end_at))
 then raise exception 'BILLING_PLAN_CHANGE_EFFECTIVE_DATE_INVALID'; end if;
 select * into t from public.billing_price_mappings where provider='paddle' and environment='test' and identity_kind='plan' and status='active'
 and canonical_key=p_target_plan and cadence=p_target_cadence and currency_code='USD' and catalogue_evidence_id is not null for share;
 if t.id is null then raise exception 'BILLING_PLAN_CHANGE_TARGET_MAPPING_UNAVAILABLE'; end if;
 classification:=public.classify_billing_plan_change(c-&gt;&gt;'sourcePlan',p_target_cadence,p_target_plan,p_target_cadence);
 pf:=public.billing_plan_change_preflight(p_owner,(c-&gt;&gt;'accountId')::uuid,t.plan_version_id);
 return jsonb_build_object('context',c,'targetMappingId',t.id,'targetPriceRef',t.provider_price_ref,'targetProductRef',t.provider_product_ref,
 'snapshot',pf-&gt;'snapshot','preview',classification||jsonb_build_object('provider','paddle','sourcePlanKey',c-&gt;&gt;'sourcePlan','sourceCadence',p_target_cadence,
 'targetPlanKey',p_target_plan,'targetCadence',p_target_cadence,'currentPriceMinor',(c-&gt;&gt;'sourceAmount')::bigint,'targetPriceMinor',t.unit_amount_minor,
 'currency','USD','effectiveAt',case when classification-&gt;&gt;'effectiveTiming'='period_end' then end_at else null end,
 'blockers',case when classification-&gt;&gt;'effectiveTiming'='period_end' then pf-&gt;'blockers' else '[]'::jsonb end,'dataQualityIssue',pf#&gt;'{snapshot,hasAnyDataQualityIssue}'));
end $function$

CREATE OR REPLACE FUNCTION public.preview_paddle_seat_quantity_v1(p_owner uuid, p_target integer, p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c jsonb;p public.commercial_plan_versions%rowtype;d jsonb;n integer;lim integer;blocked boolean;direction text;
begin
 c:=public.paddle_seat_quantity_context_v1(p_owner,p_target);n:=(c-&gt;&gt;'additionalSeats')::integer;
 if (p_snapshot-&gt;&gt;'subscriptionRef',p_snapshot-&gt;&gt;'customerRef',p_snapshot-&gt;&gt;'status',p_snapshot-&gt;&gt;'cadence',p_snapshot-&gt;&gt;'basePriceRef',p_snapshot-&gt;&gt;'seatPriceRef')
 is distinct from (c-&gt;&gt;'subscriptionRef',c-&gt;&gt;'customerRef','active',c-&gt;&gt;'cadence',c#&gt;&gt;'{base,priceRef}',case when n&gt;0 then c#&gt;&gt;'{seat,priceRef}' end)
 or p_snapshot-&gt;'additionalSeats' is distinct from to_jsonb(n) or p_snapshot-&gt;&gt;'updatedAt' is null
 or (p_snapshot-&gt;&gt;'updatedAt')::timestamptz&lt;(c-&gt;&gt;'providerUpdatedAt')::timestamptz
 or ((p_snapshot-&gt;&gt;'periodStart')::timestamptz,(p_snapshot-&gt;&gt;'periodEnd')::timestamptz) is distinct from ((c-&gt;&gt;'periodStart')::timestamptz,(c-&gt;&gt;'periodEnd')::timestamptz)
 then raise exception 'BILLING_SEAT_QUANTITY_UNAPPROVED_DRIFT';end if;
 select v.* into p from public.commercial_plan_versions v join public.account_subscriptions a on a.plan_version_id=v.id where a.id=(c-&gt;&gt;'canonicalId')::uuid;
 select value into d from jsonb_array_elements(public.resolve_account_capacity(p_owner,(c-&gt;&gt;'accountId')::uuid)-&gt;'dimensions') where value-&gt;&gt;'key'='coach_seats';
 lim:=least(p.max_coach_seats,p.included_coach_seats+p_target);
 blocked:=(d-&gt;&gt;'dataQualityIssue')::boolean or (p_target&lt;n and (d-&gt;&gt;'committed')::integer&gt;lim);
 direction:=case when p_target&gt;n then 'increase' when p_target&lt;n then 'reduction' else 'no-op' end;
 return jsonb_build_object('provider','paddle','planKey',p.plan_key,'cadence',c-&gt;'cadence','includedSeats',p.included_coach_seats,
 'currentAdditionalSeats',n,'targetAdditionalSeats',p_target,'maximumSeats',p.max_coach_seats,'maximumAdditionalSeats',p.max_coach_seats-p.included_coach_seats,
 'currentProviderQuantity',n,'targetProviderQuantity',p_target,'currentEffectiveLimit',public.billing_seat_effective_limit((c-&gt;&gt;'accountId')::uuid),'targetEffectiveLimit',lim,
 'actual',d-&gt;'actual','pending',d-&gt;'pending','reserved',d-&gt;'reserved','committed',d-&gt;'committed','unitPriceMinor',c#&gt;'{seat,amount}',
 'currentTotalMinor',(c#&gt;&gt;'{base,amount}')::bigint+n*(c#&gt;&gt;'{seat,amount}')::bigint,'targetTotalMinor',(c#&gt;&gt;'{base,amount}')::bigint+p_target*(c#&gt;&gt;'{seat,amount}')::bigint,
 'direction',direction,'timing',case when p_target&lt;n then 'period_end' else 'immediate' end,'effectiveAt',case when p_target&lt;n then c-&gt;&gt;'periodEnd' end,
 'currency','USD','capacityBlocked',blocked,'eligible',not blocked,'errorCode',case when blocked then 'BILLING_SEAT_QUANTITY_CAPACITY_BLOCKED' end,
 'disclosure','Paddle calculates proration, taxes and credits. No payment has been collected by this preview. Increased capacity requires verified payment.');
end $function$

CREATE OR REPLACE FUNCTION public.preview_workspace_team_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_user_id uuid := (select auth.uid());
  v_user_email text;
  v_token_hash text;
  v_invite public.workspace_member_invites%rowtype;
  v_workspace_name text;
  v_status text;
  v_has_client_identity boolean := false;
  v_has_pt_identity boolean := false;
begin
  if v_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  if nullif(trim(coalesce(p_token, '')), '') is null then
    perform public.workspace_team_invite_error('INVITE_NOT_FOUND');
  end if;

  select lower(email)
  into v_user_email
  from auth.users
  where id = v_user_id;

  if v_user_email is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  v_token_hash := public.hash_workspace_team_invite_token(p_token);

  select *
  into v_invite
  from public.workspace_member_invites wmi
  where wmi.token_hash = v_token_hash
  limit 1;

  if not found then
    perform public.workspace_team_invite_error('INVITE_NOT_FOUND');
  end if;

  if lower(v_invite.email) &lt;&gt; v_user_email then
    perform public.workspace_team_invite_error('INVITE_EMAIL_MISMATCH');
  end if;

  select exists (
    select 1
    from public.clients c
    where c.user_id = v_user_id
  )
  into v_has_client_identity;

  select exists (
    select 1
    from public.pt_profiles pp
    where pp.user_id = v_user_id
  ) or exists (
    select 1
    from public.pt_hub_profiles php
    where php.user_id = v_user_id
  ) or exists (
    select 1
    from public.workspace_members wm
    where wm.user_id = v_user_id
      and wm.status &lt;&gt; 'removed'
  )
  into v_has_pt_identity;

  if v_has_client_identity and not v_has_pt_identity then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  select w.name
  into v_workspace_name
  from public.workspaces w
  where w.id = v_invite.workspace_id;

  v_status := case
    when v_invite.status = 'pending' and v_invite.expires_at &lt;= now() then 'expired'
    else v_invite.status
  end;

  return jsonb_build_object(
    'inviteId', v_invite.id,
    'workspaceId', v_invite.workspace_id,
    'workspaceName', v_workspace_name,
    'invitedEmail', v_invite.email,
    'role', v_invite.role,
    'clientAccessMode', v_invite.client_access_mode,
    'status', v_status,
    'expiresAt', v_invite.expires_at,
    'requiresAuth', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_account_capacity_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'DELETE' or tg_table_name = 'account_capacity_events' then
    raise exception 'Capacity history is append-only.';
  end if;
  if old.status &lt;&gt; 'active' or (to_jsonb(new) - array['status','consumed_at','released_at','expired_at','updated_at'])
    is distinct from (to_jsonb(old) - array['status','consumed_at','released_at','expired_at','updated_at']) then
    raise exception 'Reservation identity and terminal history are immutable.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_account_commercial_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'DELETE' or tg_table_name = 'account_subscription_events' then
    raise exception 'Commercial history is append-only; deletion is not permitted.';
  end if;
  if tg_table_name = 'billing_accounts' then
    if new.id &lt;&gt; old.id or new.owner_user_id &lt;&gt; old.owner_user_id then raise exception 'Billing account identity is immutable.'; end if;
  elsif tg_table_name = 'account_subscriptions' then
    if tg_op='UPDATE' and old.status='superseded' and
      (to_jsonb(new)-array['superseded_by_subscription_id','updated_at']) is distinct from (to_jsonb(old)-array['superseded_by_subscription_id','updated_at']) then raise exception 'Superseded history is immutable.'; end if;
    if tg_op='UPDATE' and old.superseded_by_subscription_id is not null and new.superseded_by_subscription_id is distinct from old.superseded_by_subscription_id then raise exception 'Superseded history is immutable.'; end if;
    if tg_op = 'UPDATE' and
      (to_jsonb(new) - array['status','status_changed_at','canceled_at','restricted_at','expired_at','current_period_started_at','current_period_ends_at','cancel_at_period_end','superseded_at','superseded_by_subscription_id','updated_at']) is distinct from
      (to_jsonb(old) - array['status','status_changed_at','canceled_at','restricted_at','expired_at','current_period_started_at','current_period_ends_at','cancel_at_period_end','superseded_at','superseded_by_subscription_id','updated_at']) then
      raise exception 'Subscription identity and trial clock are immutable.';
    end if;
    perform 1 from public.commercial_plan_versions where id = new.plan_version_id and status in ('active','retired') for share;
    if not found then raise exception 'Subscription requires an immutable plan version.'; end if;
    if new.subscription_kind = 'trial' then
      perform 1 from public.commercial_trial_policy_versions
      where id = new.trial_policy_version_id and status in ('active','retired') and feature_plan_version_id = new.plan_version_id
        and new.trial_ends_at = new.trial_started_at + make_interval(days =&gt; duration_days)
        and new.trial_recovery_ends_at = new.trial_ends_at + make_interval(days =&gt; recovery_days) for share;
      if not found then raise exception 'Trial must match its immutable policy and dates.'; end if;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_account_override()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'Revoke overrides; do not delete history.'; end if;
  if old.revoked_at is not null or new.revoked_at is null or
     (to_jsonb(new) - 'revoked_at') is distinct from (to_jsonb(old) - 'revoked_at') then
    raise exception 'Overrides are immutable except for one-way revocation.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_billing_plan_change_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.billing_provider_variant_mappings%rowtype; t public.billing_provider_variant_mappings%rowtype; c jsonb;
begin
  if tg_op='DELETE' or tg_table_name='billing_plan_change_events' then raise exception 'Plan change history is append-only.'; end if;
  if tg_op='UPDATE' then
    if old.status in ('completed','canceled','failed') and new is distinct from old then raise exception 'BILLING_PLAN_CHANGE_OPERATION_CONFLICT'; end if;
    if (to_jsonb(new)-array['status','provider_requested_at','provider_applied_at','payment_confirmed_at','completed_at','canceled_at','failed_at','ambiguous_at','provider_updated_at','provider_snapshot_sha256','error_code','updated_at']) is distinct from
      (to_jsonb(old)-array['status','provider_requested_at','provider_applied_at','payment_confirmed_at','completed_at','canceled_at','failed_at','ambiguous_at','provider_updated_at','provider_snapshot_sha256','error_code','updated_at']) then raise exception 'BILLING_PLAN_CHANGE_OPERATION_CONFLICT'; end if;
  end if;
  select * into strict s from public.billing_provider_variant_mappings where id=new.source_variant_mapping_id for share;
  select * into strict t from public.billing_provider_variant_mappings where id=new.target_variant_mapping_id for share;
  if tg_op='INSERT' then
    perform 1 from public.billing_accounts where id=new.billing_account_id for update;
    if exists(select 1 from public.billing_seat_quantity_operations where billing_provider_subscription_id=new.billing_provider_subscription_id and status not in ('completed','canceled','failed')) then raise exception 'BILLING_PLAN_CHANGE_OPERATION_CONFLICT'; end if;
  end if;
  if tg_op='INSERT' and t.status&lt;&gt;'active' then raise exception 'BILLING_PLAN_CHANGE_TARGET_MAPPING_UNAVAILABLE'; end if;
  if s.status not in ('active','retired') or t.status not in ('active','retired') or
    (s.plan_version_id,s.cadence,s.provider,s.environment,s.provider_store_id) is distinct from
    (new.source_plan_version_id,new.source_cadence,t.provider,t.environment,t.provider_store_id) or
    (t.plan_version_id,t.cadence) is distinct from (new.target_plan_version_id,new.target_cadence) then raise exception 'BILLING_PLAN_CHANGE_OPERATION_CONFLICT'; end if;
  if not exists(select 1 from public.billing_accounts where id=new.billing_account_id and owner_user_id=new.created_by_user_id) or
    not exists(select 1 from public.account_subscriptions where id=new.source_account_subscription_id and billing_account_id=new.billing_account_id and plan_version_id=new.source_plan_version_id and subscription_kind='paid') or
    not exists(select 1 from public.billing_provider_subscriptions where id=new.billing_provider_subscription_id and billing_account_id=new.billing_account_id and environment=s.environment and provider_store_id=s.provider_store_id) then raise exception 'BILLING_PLAN_CHANGE_OWNER_REQUIRED'; end if;
  c:=public.classify_billing_plan_change((select plan_key from public.commercial_plan_versions where id=s.plan_version_id),s.cadence,(select plan_key from public.commercial_plan_versions where id=t.plan_version_id),t.cadence);
  if (new.change_kind,new.effective_timing,new.proration_mode) is distinct from (c-&gt;&gt;'changeKind',c-&gt;&gt;'effectiveTiming',c-&gt;&gt;'prorationMode') then raise exception 'BILLING_PLAN_CHANGE_OPERATION_CONFLICT'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_billing_provider_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m public.billing_provider_variant_mappings%rowtype;
begin
  if tg_op='DELETE' then raise exception 'Billing history cannot be deleted.'; end if;
  if tg_table_name='billing_provider_customers' and tg_op='UPDATE' and
    (to_jsonb(new)-array['last_seen_at','updated_at']) is distinct from (to_jsonb(old)-array['last_seen_at','updated_at']) then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
  if tg_table_name='billing_checkout_attempts' then
    -- Sale admission records an approved mapping while it is active. Hold the
    -- mapping lock through insertion so retirement cannot race this proof.
    if tg_op='INSERT' then
      select * into strict m from public.billing_provider_variant_mappings where id=new.variant_mapping_id for share;
      if m.status&lt;&gt;'active' then raise exception 'BILLING_VARIANT_MAPPING_UNAVAILABLE'; end if;
    end if;
    if tg_op='UPDATE' and (to_jsonb(new)-array['status','provider_checkout_id','provider_checkout_url','provider_expires_at','completed_provider_subscription_id','error_code','updated_at','completed_at','failed_at','expired_at']) is distinct from
      (to_jsonb(old)-array['status','provider_checkout_id','provider_checkout_url','provider_expires_at','completed_provider_subscription_id','error_code','updated_at','completed_at','failed_at','expired_at']) then raise exception 'BILLING_CHECKOUT_OPERATION_CONFLICT'; end if;
    if not exists(select 1 from public.billing_accounts where id=new.billing_account_id and owner_user_id=new.created_by_user_id) then raise exception 'BILLING_FORBIDDEN'; end if;
  end if;
  if tg_table_name='billing_provider_subscriptions' then
    if tg_op='UPDATE' and new.approved_additional_coach_seats&lt;&gt;old.approved_additional_coach_seats and not exists(
      select 1 from public.billing_seat_quantity_operations o where o.billing_provider_subscription_id=new.id
        and o.source_additional_seats=old.approved_additional_coach_seats and o.target_additional_seats=new.approved_additional_coach_seats
        and o.status in ('awaiting_payment','scheduled')) then raise exception 'BILLING_SEAT_QUANTITY_UNAPPROVED_DRIFT'; end if;
    if tg_op='UPDATE' and (to_jsonb(new)-array['quantity','approved_additional_coach_seats','account_subscription_id','variant_mapping_id','provider_product_id','provider_variant_id','provider_price_id','provider_status','provider_cancelled','provider_renews_at','provider_ends_at','provider_trial_ends_at','provider_updated_at','latest_snapshot_sha256','last_reconciled_at','reconciliation_status','reconciliation_error_code','updated_at']) is distinct from
      (to_jsonb(old)-array['quantity','approved_additional_coach_seats','account_subscription_id','variant_mapping_id','provider_product_id','provider_variant_id','provider_price_id','provider_status','provider_cancelled','provider_renews_at','provider_ends_at','provider_trial_ends_at','provider_updated_at','latest_snapshot_sha256','last_reconciled_at','reconciliation_status','reconciliation_error_code','updated_at']) then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
    select * into strict m from public.billing_provider_variant_mappings where id=new.variant_mapping_id;
    if (new.provider,new.environment,new.provider_store_id,new.provider_product_id,new.provider_variant_id,new.provider_price_id) is distinct from
      (m.provider,m.environment,m.provider_store_id,m.provider_product_id,m.provider_variant_id,m.provider_price_id) then raise exception 'BILLING_VARIANT_MAPPING_MISMATCH'; end if;
    if new.account_subscription_id is not null and not exists(select 1 from public.account_subscriptions where id=new.account_subscription_id and billing_account_id=new.billing_account_id
      and subscription_kind='paid' and (plan_version_id=m.plan_version_id or exists(
      select 1 from public.billing_plan_change_operations o where o.billing_provider_subscription_id=new.id
        and o.source_account_subscription_id=new.account_subscription_id and o.target_variant_mapping_id=new.variant_mapping_id
        and o.status in ('provider_pending','awaiting_payment','scheduled','cancel_pending','ambiguous','manual_review')))) then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
    if tg_op='UPDATE' and ((old.variant_mapping_id is distinct from new.variant_mapping_id) or (old.account_subscription_id is distinct from new.account_subscription_id)) and not exists(
      select 1 from public.billing_plan_change_operations o where o.billing_provider_subscription_id=new.id
      and o.status not in ('completed','canceled','failed') and (
        (new.variant_mapping_id=o.target_variant_mapping_id and old.variant_mapping_id in (o.source_variant_mapping_id,o.target_variant_mapping_id)
          and (new.account_subscription_id=o.source_account_subscription_id or exists(select 1 from public.account_subscriptions s where s.id=o.source_account_subscription_id and s.superseded_by_subscription_id=new.account_subscription_id)))
        or (o.status='cancel_pending' and new.variant_mapping_id=o.source_variant_mapping_id and new.account_subscription_id=o.source_account_subscription_id))) then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_billing_seat_catalogue()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m public.billing_provider_variant_mappings%rowtype; a public.commercial_addon_versions%rowtype; expected jsonb;
begin
  if tg_op='DELETE' then raise exception 'Billing seat catalogue is immutable.'; end if;
  if tg_op='UPDATE' and (old.status='retired' or (old.status='active' and
    (new.status not in ('active','retired') or (to_jsonb(new)-array['status','retired_at']) is distinct from (to_jsonb(old)-array['status','retired_at'])))) then
    raise exception 'Billing seat catalogue is immutable.';
  end if;
  if tg_table_name='billing_quantity_price_contracts' then
    select * into strict m from public.billing_provider_variant_mappings where id=new.variant_mapping_id for share;
    select * into strict a from public.commercial_addon_versions where id=new.addon_version_id for share;
    expected:=jsonb_build_object('price_id',m.provider_price_id,'variant_id',m.provider_variant_id,'category','subscription','scheme','graduated',
      'usage_aggregation',null,'setup_fee_enabled',false,'setup_fee',null,'package_size',1,
      'trial_interval_unit',null,'trial_interval_quantity',null,'renewal_interval_unit',m.renewal_interval_unit,'renewal_interval_quantity',1,
      'tiers',jsonb_build_array(jsonb_build_object('last_unit',1,'unit_price',m.unit_amount_minor,'fixed_fee',0,'unit_price_decimal',null),
        jsonb_build_object('last_unit','inf','unit_price',case m.cadence when 'monthly' then a.monthly_unit_amount_minor else a.annual_unit_amount_minor end,'fixed_fee',0,'unit_price_decimal',null)));
    if new.normalized_price_contract is distinct from expected or new.price_contract_sha256&lt;&gt;encode(extensions.digest(expected::text,'sha256'),'hex') or
      (new.status='active' and (m.status&lt;&gt;'active' or a.status&lt;&gt;'active') and (tg_op='INSERT' or old.status='draft')) then
      raise exception 'BILLING_SEAT_QUANTITY_PRICE_CONTRACT_MISMATCH'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_billing_seat_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.billing_provider_subscriptions%rowtype; p public.commercial_plan_versions%rowtype; c public.billing_quantity_price_contracts%rowtype;
begin
  if tg_op='DELETE' or tg_table_name='billing_seat_quantity_events' then raise exception 'Billing seat history is append-only.'; end if;
  perform 1 from public.billing_accounts where id=new.billing_account_id for update;
  if tg_op='UPDATE' then
    if old.status in ('completed','canceled','failed') and new is distinct from old then raise exception 'BILLING_SEAT_QUANTITY_OPERATION_CONFLICT'; end if;
    if (to_jsonb(new)-array['status','provider_applied_at','payment_confirmed_at','cancel_requested_at','completed_at','canceled_at','provider_updated_at','provider_snapshot_sha256','error_code','updated_at']) is distinct from
      (to_jsonb(old)-array['status','provider_applied_at','payment_confirmed_at','cancel_requested_at','completed_at','canceled_at','provider_updated_at','provider_snapshot_sha256','error_code','updated_at']) then raise exception 'BILLING_SEAT_QUANTITY_OPERATION_CONFLICT'; end if;
  end if;
  if tg_op='INSERT' then
    select * into strict b from public.billing_provider_subscriptions where id=new.billing_provider_subscription_id;
    select * into strict p from public.commercial_plan_versions where id=(select plan_version_id from public.account_subscriptions where id=new.account_subscription_id);
    select * into strict c from public.billing_quantity_price_contracts where id=new.quantity_price_contract_id for share;
    if (b.billing_account_id,b.account_subscription_id,b.variant_mapping_id,b.approved_additional_coach_seats,b.quantity) is distinct from
      (new.billing_account_id,new.account_subscription_id,new.variant_mapping_id,new.source_additional_seats,new.source_quantity) or
      c.variant_mapping_id&lt;&gt;new.variant_mapping_id or c.status&lt;&gt;'active' or new.target_additional_seats&gt;p.max_coach_seats-p.included_coach_seats or
      new.source_effective_limit&lt;&gt;least(p.max_coach_seats,p.included_coach_seats+new.source_additional_seats) or
      new.target_effective_limit&lt;&gt;least(p.max_coach_seats,p.included_coach_seats+new.target_additional_seats) then raise exception 'BILLING_SEAT_QUANTITY_TARGET_INVALID'; end if;
    if not exists(select 1 from public.billing_accounts where id=new.billing_account_id and owner_user_id=new.created_by_user_id) then raise exception 'BILLING_SEAT_QUANTITY_OWNER_REQUIRED'; end if;
    if exists(select 1 from public.billing_plan_change_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed')) then raise exception 'BILLING_SEAT_QUANTITY_OPERATION_CONFLICT'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_billing_variant_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p public.commercial_plan_versions%rowtype;
begin
  if tg_op='DELETE' then raise exception 'Billing history cannot be deleted.'; end if;
  if tg_op='UPDATE' and (old.status='retired' or (old.status='active' and
    (new.status not in ('active','retired') or (to_jsonb(new)-array['status','retired_at','updated_at']) is distinct from
    (to_jsonb(old)-array['status','retired_at','updated_at'])))) then raise exception 'BILLING_VARIANT_MAPPING_MISMATCH'; end if;
  select * into strict p from public.commercial_plan_versions where id=new.plan_version_id for share;
  if new.unit_amount_minor is distinct from (case new.cadence when 'monthly' then p.monthly_price_minor else p.annual_price_minor end)
    or new.currency_code&lt;&gt;p.currency_code or (new.status='active' and p.status not in ('active','retired')) then
    raise exception 'BILLING_VARIANT_MAPPING_MISMATCH'; end if;
  -- Serialize publication to enforce one Store/Product per provider environment.
  perform pg_advisory_xact_lock(hashtextextended('billing-mapping:'||new.environment,0));
  if new.status='active' and exists(select 1 from public.billing_provider_variant_mappings m where m.id&lt;&gt;new.id and m.environment=new.environment
    and m.status in ('active','retired') and (m.provider_store_id&lt;&gt;new.provider_store_id or m.provider_product_id&lt;&gt;new.provider_product_id)) then
    raise exception 'BILLING_VARIANT_MAPPING_MISMATCH'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.protect_commercial_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_old_id uuid;
  v_new_id uuid;
  v_plan record;
begin
  if tg_op &lt;&gt; 'INSERT' then v_old_id := old.plan_version_id; end if;
  if tg_op &lt;&gt; 'DELETE' then v_new_id := new.plan_version_id; end if;
  -- Lock both parents on a move. Activation and mapping edits must serialize.
  for v_plan in
    select id, status from public.commercial_plan_versions
    where id in (v_old_id, v_new_id) order by id for update
  loop
    if v_plan.status &lt;&gt; 'draft' then
      raise exception 'Commercial entitlements may only change while the plan is draft.';
    end if;
  end loop;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_commercial_feature()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Commercial features cannot be deleted.';
  end if;
  if new.feature_key is distinct from old.feature_key then
    raise exception 'Commercial feature keys are immutable.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_commercial_plan_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'Commercial plan versions cannot be deleted.';
  end if;
  if old.status = 'retired' then
    raise exception 'Retired commercial plan versions are immutable.';
  end if;
  if old.status = 'active' then
    -- Compare the whole row, including future columns, except retirement metadata.
    if (to_jsonb(new) - array['status', 'is_public', 'is_most_popular', 'retired_at', 'updated_at'])
       is distinct from
       (to_jsonb(old) - array['status', 'is_public', 'is_most_popular', 'retired_at', 'updated_at']) then
      raise exception 'Active commercial plan contracts are immutable.';
    end if;
    if new.status = 'retired' then
      if new.is_public or new.is_most_popular or new.retired_at is null then
        raise exception 'Retirement requires private, non-popular status and retired_at.';
      end if;
    elsif (to_jsonb(new) - 'updated_at') is distinct from (to_jsonb(old) - 'updated_at') then
      raise exception 'Active commercial plans may only transition to retired.';
    end if;
  elsif new.status not in ('draft', 'active') then
    raise exception 'Draft commercial plans may only transition to active.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_commercial_trial_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.status &lt;&gt; 'draft' then raise exception 'Published trial policies cannot be deleted.'; end if;
    return old;
  end if;
  if tg_op = 'UPDATE' then
    if old.status = 'retired' then raise exception 'Retired trial policies are immutable.'; end if;
    if old.status = 'active' then
      if (to_jsonb(new) - array['status','retired_at','updated_at']) is distinct from
         (to_jsonb(old) - array['status','retired_at','updated_at']) then
        raise exception 'Active trial policy contracts are immutable.';
      end if;
      if new.status not in ('active','retired') then raise exception 'Active trial policies may only retire.'; end if;
    elsif new.status not in ('draft','active') then raise exception 'Draft trial policies must activate before retirement.';
    end if;
  end if;
  perform 1 from public.commercial_plan_versions where id = new.feature_plan_version_id and status in ('active','retired') for share;
  if not found then raise exception 'Trial policy requires an immutable plan version.'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.pt_assign_performance_markers(p_client_id uuid, p_performance_marker_ids uuid[] DEFAULT '{}'::uuid[], p_workspace_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(onboarding_id uuid, baseline_id uuid, assigned_marker_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_workspace_id uuid;
  v_workspace_owner_user_id uuid;
  v_client_workspace_id uuid;
  v_onboarding public.workspace_client_onboardings;
  v_draft public.baseline_entries;
  v_now timestamptz := now();
  v_pt_workspace_count integer := 0;
begin
  if p_client_id is null then
    raise exception 'Client is required';
  end if;

  select c.workspace_id
  into v_client_workspace_id
  from public.clients c
  where c.id = p_client_id;

  if not found then
    raise exception 'Client not found';
  end if;

  if p_workspace_id is not null then
    if not public.is_pt_workspace_member(p_workspace_id) then
      raise exception 'Client not found in this workspace.';
    end if;

    v_workspace_id := p_workspace_id;

    select wco.*
    into v_onboarding
    from public.workspace_client_onboardings wco
    where wco.workspace_id = v_workspace_id
      and wco.client_id = p_client_id
    limit 1;
  else
    select wco.*
    into v_onboarding
    from public.workspace_client_onboardings wco
    join public.workspace_members wm
      on wm.workspace_id = wco.workspace_id
    where wco.client_id = p_client_id
      and wm.user_id = auth.uid()
      and wm.role::text like 'pt_%'
    order by
      case
        when v_client_workspace_id is not null
         and wco.workspace_id = v_client_workspace_id then 0
        else 1
      end,
      wco.updated_at desc
    limit 1;

    if v_onboarding.id is not null then
      v_workspace_id := v_onboarding.workspace_id;
    elsif v_client_workspace_id is not null
      and public.is_pt_workspace_member(v_client_workspace_id) then
      v_workspace_id := v_client_workspace_id;
    else
      select count(*)
      into v_pt_workspace_count
      from public.workspace_members wm
      where wm.user_id = auth.uid()
        and wm.role::text like 'pt_%';

      if v_pt_workspace_count &lt;&gt; 1 then
        raise exception 'Client not found in this workspace.';
      end if;

      select wm.workspace_id
      into v_workspace_id
      from public.workspace_members wm
      where wm.user_id = auth.uid()
        and wm.role::text like 'pt_%'
      limit 1;
    end if;
  end if;

  if v_workspace_id is null then
    raise exception 'Client not found in this workspace.';
  end if;

  if not public.is_pt_workspace_member(v_workspace_id) then
    raise exception 'Not authorized';
  end if;

  select w.owner_user_id
  into v_workspace_owner_user_id
  from public.workspaces w
  where w.id = v_workspace_id;

  if v_workspace_owner_user_id is null then
    raise exception 'Workspace owner not found.';
  end if;

  if v_client_workspace_id is not null
    and v_client_workspace_id &lt;&gt; v_workspace_id
    and v_onboarding.id is null then
    raise exception 'Client not found in this workspace.';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_performance_marker_ids, '{}'::uuid[])) as selected_ids(template_id)
    left join public.baseline_marker_templates bmt
      on bmt.id = selected_ids.template_id
    left join public.workspaces w
      on w.id = bmt.workspace_id
    where coalesce(bmt.owner_user_id, w.owner_user_id) is distinct from v_workspace_owner_user_id
       or bmt.id is null
  ) then
    raise exception 'One or more performance markers were not found in this PT marker library.';
  end if;

  if v_onboarding.id is null then
    select *
    into v_onboarding
    from public.workspace_client_onboardings wco
    where wco.workspace_id = v_workspace_id
      and wco.client_id = p_client_id
    limit 1;
  end if;

  if v_onboarding.id is null then
    insert into public.workspace_client_onboardings (
      workspace_id,
      client_id,
      source,
      status
    )
    values (
      v_workspace_id,
      p_client_id,
      'direct_invite',
      'invited'
    )
    returning *
    into v_onboarding;
  end if;

  if v_onboarding.initial_baseline_entry_id is not null then
    select *
    into v_draft
    from public.baseline_entries be
    where be.id = v_onboarding.initial_baseline_entry_id
      and be.client_id = p_client_id
      and be.status = 'draft'
    limit 1;
  end if;

  if v_draft.id is null then
    select *
    into v_draft
    from public.baseline_entries be
    where be.client_id = p_client_id
      and be.workspace_id = v_workspace_id
      and be.status = 'draft'
    order by be.created_at desc
    limit 1;
  end if;

  if v_draft.id is null then
    insert into public.baseline_entries (
      client_id,
      workspace_id,
      status,
      created_at
    )
    values (
      p_client_id,
      v_workspace_id,
      'draft',
      v_now
    )
    returning *
    into v_draft;
  end if;

  update public.workspace_client_onboardings
  set
    initial_baseline_entry_id = v_draft.id,
    status = case
      when status = 'invited' then 'in_progress'::public.onboarding_status
      else status
    end,
    started_at = coalesce(started_at, v_now),
    last_saved_at = v_now,
    updated_at = v_now
  where id = v_onboarding.id
  returning *
  into v_onboarding;

  delete from public.baseline_entry_marker_templates bet
  where bet.baseline_id = v_draft.id
    and not (bet.template_id = any(coalesce(p_performance_marker_ids, '{}'::uuid[])));

  insert into public.baseline_entry_marker_templates (baseline_id, template_id)
  select
    v_draft.id,
    selected_ids.template_id
  from unnest(coalesce(p_performance_marker_ids, '{}'::uuid[])) as selected_ids(template_id)
  on conflict on constraint baseline_entry_marker_templates_pkey do nothing;

  onboarding_id := v_onboarding.id;
  baseline_id := v_draft.id;
  assigned_marker_count := coalesce(array_length(coalesce(p_performance_marker_ids, '{}'::uuid[]), 1), 0);
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.pt_dashboard_summary(p_workspace_id uuid, p_coach_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_user_id uuid;
  v_today date := current_date;
  v_start_week date := v_today - 6;
  v_end_week date := v_today + 6;
  v_last_saturday date := v_today - ((extract(dow from v_today)::int - 6 + 7) % 7);
  v_client_ids uuid[];
  v_clients jsonb;
  v_checkins jsonb;
  v_assigned jsonb;
  v_messages jsonb;
  v_unread int;
  v_todos jsonb;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if p_coach_id is distinct from v_user_id then
    raise exception 'Not authorized';
  end if;

  if not public.can_access_workspace(p_workspace_id) then
    raise exception 'Not authorized';
  end if;

  perform public.ensure_workspace_checkins(
    p_workspace_id,
    v_today,
    v_end_week
  );

  select coalesce(array_agg(aci.client_id), '{}'::uuid[])
  into v_client_ids
  from public.accessible_client_ids(p_workspace_id) aci;

  select jsonb_agg(c) into v_clients
  from (
    select id, workspace_id, user_id, status, display_name, created_at, tags, timezone
    from public.clients
    where id = any(v_client_ids)
    order by created_at desc
  ) c;

  select jsonb_agg(a) into v_assigned
  from (
    select id, client_id, status, scheduled_date
    from public.assigned_workouts
    where client_id = any(v_client_ids)
      and scheduled_date between v_start_week and v_today
  ) a;

  select jsonb_agg(ci) into v_checkins
  from (
    select id, client_id, week_ending_saturday, submitted_at, created_at
    from public.checkins
    where client_id = any(v_client_ids)
      and week_ending_saturday between v_start_week and v_end_week
  ) ci;

  select jsonb_agg(m) into v_messages
  from (
    select
      conv.id,
      conv.last_message_at as created_at,
      conv.last_message_sender_name as sender_name,
      conv.last_message_preview as preview
    from public.conversations conv
    where conv.workspace_id = p_workspace_id
      and (
        conv.client_id is null
        or conv.client_id = any(v_client_ids)
      )
    order by conv.last_message_at desc nulls last
    limit 5
  ) m;

  select count(*) into v_unread
  from public.messages m
  join public.conversations conv on conv.id = m.conversation_id
  where m.unread = true
    and conv.workspace_id = p_workspace_id
    and (
      conv.client_id is null
      or conv.client_id = any(v_client_ids)
    );

  select jsonb_agg(t) into v_todos
  from (
    select id, title, is_done, created_at
    from public.coach_todos
    where workspace_id = p_workspace_id
      and coach_id = p_coach_id
    order by created_at asc
  ) t;

  return jsonb_build_object(
    'clients', coalesce(v_clients, '[]'::jsonb),
    'assignedWorkouts', coalesce(v_assigned, '[]'::jsonb),
    'checkins', coalesce(v_checkins, '[]'::jsonb),
    'messages', coalesce(v_messages, '[]'::jsonb),
    'unreadCount', coalesce(v_unread, 0),
    'coachTodos', coalesce(v_todos, '[]'::jsonb),
    'today', v_today::text,
    'lastSaturday', v_last_saturday::text
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.pt_hub_approve_lead(p_lead_id uuid, p_workspace_id uuid DEFAULT NULL::uuid, p_workspace_name text DEFAULT NULL::text, p_allow_transfer boolean DEFAULT false)
 RETURNS TABLE(lead_id uuid, status text, workspace_id uuid, client_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid;
  v_lead public.pt_hub_leads%rowtype;
  v_target_workspace_id uuid;
  v_target_client_id uuid;
  v_workspace_name text;
  v_was_converted boolean := false;
  v_transfer_requested boolean := false;
  v_new_workspace boolean := false;
begin
  v_actor_user_id := auth.uid();
  if v_actor_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if p_lead_id is null then
    raise exception 'Lead is required';
  end if;

  select *
  into v_lead
  from public.pt_hub_leads lead
  where lead.id = p_lead_id
  for update;

  if not found then
    raise exception 'Lead not found';
  end if;

  if v_lead.user_id &lt;&gt; v_actor_user_id then
    raise exception 'Not allowed to update this lead';
  end if;

  if v_lead.status = 'declined' then
    raise exception 'Declined leads cannot be approved';
  end if;

  v_workspace_name := nullif(btrim(coalesce(p_workspace_name, '')), '');
  v_was_converted :=
    v_lead.status = 'converted'
    and v_lead.converted_workspace_id is not null
    and v_lead.converted_client_id is not null;

  if v_was_converted then
    if p_workspace_id is null and v_workspace_name is null then
      return query
      select
        v_lead.id,
        'converted'::text,
        v_lead.converted_workspace_id,
        v_lead.converted_client_id;
      return;
    end if;

    if p_workspace_id is not null
       and p_workspace_id = v_lead.converted_workspace_id then
      return query
      select
        v_lead.id,
        'converted'::text,
        v_lead.converted_workspace_id,
        v_lead.converted_client_id;
      return;
    end if;

    v_transfer_requested :=
      (p_workspace_id is not null and p_workspace_id &lt;&gt; v_lead.converted_workspace_id)
      or v_workspace_name is not null;
  end if;

  if p_workspace_id is not null then
    select workspace.id
    into v_target_workspace_id
    from public.workspaces workspace
    where workspace.id = p_workspace_id
      and workspace.owner_user_id = v_actor_user_id
    limit 1;

    if v_target_workspace_id is null then
      raise exception 'Workspace not found';
    end if;
  elsif v_workspace_name is not null then
    if not exists(select 1 from public.pt_profiles where user_id=v_actor_user_id) then
      raise exception 'PT authentication required.' using errcode='42501';
    end if;
    v_new_workspace := true;
    v_target_workspace_id := gen_random_uuid();
    perform public.start_account_trial_for_owner(v_actor_user_id,'first_workspace');
    perform public.lock_capacity_owners(array[v_actor_user_id]);
    perform public.admit_account_capacity_subject(v_actor_user_id,'active_workspaces','workspace:' || v_target_workspace_id);
    if v_lead.applicant_user_id is not null then
      perform public.admit_account_capacity_subject(v_actor_user_id,'counted_clients','user:' || v_lead.applicant_user_id);
    end if;
    insert into public.workspaces (id, name, owner_user_id)
    values (v_target_workspace_id, v_workspace_name, v_actor_user_id)
    returning id into v_target_workspace_id;

    insert into public.workspace_members (workspace_id, user_id, role)
    values (v_target_workspace_id, v_actor_user_id, 'pt_owner')
    on conflict on constraint workspace_members_workspace_id_user_id_key
    do update
      set role = 'pt_owner';
  else
    update public.pt_hub_leads lead
    set
      status = 'approved_pending_workspace',
      converted_at = null,
      converted_workspace_id = null,
      converted_client_id = null
    where lead.id = v_lead.id;

    return query
    select v_lead.id, 'approved_pending_workspace'::text, null::uuid, null::uuid;
    return;
  end if;

  if v_lead.applicant_user_id is null then
    update public.pt_hub_leads lead
    set
      status = 'approved_pending_workspace',
      converted_workspace_id = v_target_workspace_id,
      converted_client_id = null
    where lead.id = v_lead.id;

    return query
    select
      v_lead.id,
      'approved_pending_workspace'::text,
      v_target_workspace_id,
      null::uuid;
    return;
  end if;

  if v_transfer_requested then
    if not coalesce(p_allow_transfer, false) then
      raise exception
        using
          errcode = 'P0001',
          message = 'Lead transfer requires confirmation',
          detail = 'LEAD_TRANSFER_REQUIRES_CONFIRMATION',
          hint = 'Transfer keeps previous workspace history preserved and does not copy assignments automatically.';
    end if;

    select transferred.target_client_id into v_target_client_id
    from public.pt_transfer_client_relationship(
      v_lead.converted_client_id,
      v_target_workspace_id
    ) transferred;

    perform public.ensure_workspace_client_onboarding(
      v_target_client_id,
      'converted_lead'
    );

    update public.pt_hub_leads lead
    set
      status = 'converted',
      converted_at = coalesce(lead.converted_at, now()),
      converted_workspace_id = v_target_workspace_id,
      converted_client_id = v_target_client_id
    where lead.id = v_lead.id;

    return query
    select
      v_lead.id,
      'converted'::text,
      v_target_workspace_id,
      v_target_client_id;
    return;
  end if;

  begin
    select c.id
    into v_target_client_id
    from public.clients c
    where c.workspace_id = v_target_workspace_id
      and c.user_id = v_lead.applicant_user_id
    limit 1
    for update;

    if v_target_client_id is not null then
      perform public.reactivate_removed_client_relationship_internal(v_target_client_id);
    end if;

    if v_target_client_id is null
       and v_lead.converted_client_id is not null then
      select c.id
      into v_target_client_id
      from public.clients c
      where c.id = v_lead.converted_client_id
        and c.user_id = v_lead.applicant_user_id
      limit 1
      for update;

      if v_target_client_id is not null then
        perform public.reactivate_removed_client_relationship_internal(v_target_client_id);
      end if;
    end if;

    if v_target_client_id is null then
      select c.id
      into v_target_client_id
      from public.clients c
      where c.workspace_id is null
        and c.user_id = v_lead.applicant_user_id
      order by c.created_at asc
      limit 1
      for update;

      if v_target_client_id is not null then
        perform public.reactivate_removed_client_relationship_internal(v_target_client_id);
      end if;
    end if;

    if v_target_client_id is null then
      insert into public.clients (
        workspace_id,
        user_id,
        status,
        relationship_status,
        lifecycle_state,
        lifecycle_changed_at,
        paused_reason,
        churn_reason,
        display_name,
        full_name,
        email,
        phone
      )
      values (
        v_target_workspace_id,
        v_lead.applicant_user_id,
        'active',
        'active',
        'active',
        now(),
        null,
        null,
        nullif(btrim(v_lead.full_name), ''),
        nullif(btrim(v_lead.full_name), ''),
        nullif(lower(btrim(coalesce(v_lead.email, ''))), ''),
        nullif(btrim(coalesce(v_lead.phone, '')), '')
      )
      returning id into v_target_client_id;
    else
      update public.clients c
      set
        workspace_id = v_target_workspace_id,
        status = 'active',
        relationship_status = 'active',
        removed_at = null,
        removed_by_user_id = null,
        lifecycle_state = 'active',
        lifecycle_changed_at = now(),
        paused_reason = null,
        churn_reason = null,
        display_name = coalesce(
          c.display_name,
          nullif(btrim(v_lead.full_name), '')
        ),
        full_name = coalesce(
          c.full_name,
          nullif(btrim(v_lead.full_name), '')
        ),
        email = coalesce(
          c.email,
          nullif(lower(btrim(coalesce(v_lead.email, ''))), '')
        ),
        phone = coalesce(
          c.phone,
          nullif(btrim(coalesce(v_lead.phone, '')), '')
        )
      where c.id = v_target_client_id
        and coalesce(c.relationship_status, 'active') &lt;&gt; 'transferred_out';
    end if;

    perform public.ensure_workspace_client_onboarding(
      v_target_client_id,
      'converted_lead'
    );

    update public.pt_hub_leads lead
    set
      status = 'converted',
      converted_at = coalesce(lead.converted_at, now()),
      converted_workspace_id = v_target_workspace_id,
      converted_client_id = v_target_client_id
    where lead.id = v_lead.id;

    return query
    select
      v_lead.id,
      'converted'::text,
      v_target_workspace_id,
      v_target_client_id;
    return;
  exception
    when others then
      -- SQL exceptions roll back reservation events too. Never swallow admission
      -- failures, or keep a new workspace when its client conversion failed.
      if v_new_workspace or sqlerrm='Account capacity admission failed.' then raise; end if;
      perform public.log_lead_chat_event(
        v_lead.id,
        null,
        v_actor_user_id,
        'lead_workspace_assignment_failed',
        jsonb_build_object(
          'workspace_id', v_target_workspace_id,
          'error', sqlerrm
        )
      );

      if v_was_converted then
        return query
        select
          v_lead.id,
          'converted'::text,
          v_lead.converted_workspace_id,
          v_lead.converted_client_id;
        return;
      end if;

      update public.pt_hub_leads lead
      set
        status = 'approved_pending_workspace',
        converted_workspace_id = v_target_workspace_id,
        converted_client_id = null
      where lead.id = v_lead.id;

      return query
      select
        v_lead.id,
        'approved_pending_workspace'::text,
        v_target_workspace_id,
        null::uuid;
      return;
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.pt_message_recipients(p_workspace_id uuid)
 RETURNS TABLE(id uuid, display_name text, user_id uuid, lifecycle_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  if (select auth.uid()) is null then
    raise exception 'Not authenticated';
  end if;

  if p_workspace_id is null then
    raise exception 'Workspace is required';
  end if;

  if not exists (
    select 1
    from public.workspace_access_context(p_workspace_id) ctx
    where public.has_workspace_permission(
      ctx.role,
      ctx.member_status,
      'clients.message'
    )
  ) then
    raise exception 'Not authorized';
  end if;

  return query
  select
    c.id,
    c.display_name,
    c.user_id,
    c.lifecycle_state
  from public.clients c
  where c.workspace_id = p_workspace_id
    and public.can_access_client(c.id, 'clients.message')
  order by c.display_name asc nulls last, c.created_at asc;
end;
$function$

CREATE OR REPLACE FUNCTION public.pt_set_client_manual_risk(p_client_id uuid, p_manual_risk_flag boolean DEFAULT true)
 RETURNS TABLE(id uuid, manual_risk_flag boolean, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid;
  v_workspace_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select c.workspace_id
  into v_workspace_id
  from public.clients c
  where c.id = p_client_id;

  if v_workspace_id is null then
    raise exception 'Client not found';
  end if;

  if not exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = v_workspace_id
      and wm.user_id = v_user_id
      and wm.role::text like 'pt_%'
  ) then
    raise exception 'Not authorized';
  end if;

  return query
  update public.clients c
  set
    manual_risk_flag = coalesce(p_manual_risk_flag, false),
    updated_at = now()
  where c.id = p_client_id
  returning
    c.id,
    c.manual_risk_flag,
    c.updated_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.pt_update_client_admin_fields(p_client_id uuid, p_training_type text, p_tags text)
 RETURNS public.clients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_tags text[];
  v_client public.clients;
begin
  if not public.can_access_client(p_client_id, 'clients.edit') then
    raise exception 'not allowed';
  end if;

  if p_training_type is not null
     and p_training_type not in ('online', 'hybrid', 'in_person') then
    raise exception 'invalid training_type %', p_training_type;
  end if;

  v_tags := case
    when p_tags is null or btrim(p_tags) = '' then null
    else regexp_split_to_array(p_tags, '\s*,\s*')
  end;

  update public.clients
  set
    training_type = coalesce(p_training_type, training_type),
    tags = coalesce(v_tags, tags)
  where id = p_client_id
  returning *
  into v_client;

  return v_client;
end;
$function$

CREATE OR REPLACE FUNCTION public.pt_update_client_checkin_settings(p_client_id uuid, p_checkin_template_id uuid DEFAULT NULL::uuid, p_checkin_frequency text DEFAULT 'weekly'::text, p_checkin_start_date date DEFAULT NULL::date)
 RETURNS public.clients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_client public.clients;
  v_template_workspace_id uuid;
  v_frequency text := coalesce(nullif(trim(p_checkin_frequency), ''), 'weekly');
  v_onboarding_due_date date;
begin
  if not public.can_access_client(p_client_id, 'delivery.manage') then
    raise exception 'Not authorized';
  end if;

  select c.*
  into v_client
  from public.clients c
  where c.id = p_client_id;

  if v_client.id is null then
    raise exception 'Client not found';
  end if;

  if v_frequency not in ('weekly', 'biweekly', 'monthly') then
    raise exception 'Invalid check-in frequency';
  end if;

  if p_checkin_template_id is not null then
    select ct.workspace_id
    into v_template_workspace_id
    from public.checkin_templates ct
    where ct.id = p_checkin_template_id;

    if v_template_workspace_id is null then
      raise exception 'Check-in template not found';
    end if;

    if v_template_workspace_id &lt;&gt; v_client.workspace_id then
      raise exception 'Check-in template not in client workspace';
    end if;
  end if;

  update public.clients
  set
    checkin_template_id = p_checkin_template_id,
    checkin_frequency = v_frequency,
    checkin_start_date = p_checkin_start_date
  where id = p_client_id
  returning *
  into v_client;

  if p_checkin_template_id is not null and p_checkin_start_date is not null then
    v_onboarding_due_date := public.normalize_checkin_due_date(
      p_checkin_start_date
    );
  else
    v_onboarding_due_date := null;
  end if;

  update public.workspace_client_onboardings
  set
    first_checkin_template_id = p_checkin_template_id,
    first_checkin_date = v_onboarding_due_date,
    first_checkin_scheduled_at = case
      when v_onboarding_due_date is not null then now()
      else null
    end
  where workspace_id = v_client.workspace_id
    and client_id = v_client.id
    and completed_at is null;

  return v_client;
end;
$function$

CREATE OR REPLACE FUNCTION public.reactivate_removed_client_relationship(p_client_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if auth.uid() is null or not public.can_access_client(p_client_id,'clients.edit') then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  return public.reactivate_removed_client_relationship_internal(p_client_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_account_capacity_reservations()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r record; n integer := 0; result jsonb;
begin
  -- Consistent account order and the same account-before-reservation lock order.
  for r in select id,billing_account_id from public.account_capacity_reservations where status='active' and expires_at&lt;=transaction_timestamp() order by billing_account_id,id loop
    perform 1 from public.billing_accounts where id=r.billing_account_id for update;
    if exists(select 1 from public.account_capacity_reservations where id=r.id and status='active' and expires_at&lt;=transaction_timestamp()) then
      result := public.transition_account_capacity_reservation(r.id,'expired','reconciliation','{}');
      if (result-&gt;&gt;'transitioned')::boolean then n:=n+1; end if;
    end if;
  end loop;
  return jsonb_build_object('transitions',n,'computedAt',transaction_timestamp());
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_account_subscription_state(p_billing_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.account_subscriptions%rowtype; v_transitions integer := 0;
begin
  perform 1 from public.billing_accounts where id = p_billing_account_id for update;
  select * into s from public.account_subscriptions where billing_account_id = p_billing_account_id and subscription_kind = 'trial' for update;
  if s.status = 'trialing' and now() &gt;= s.trial_ends_at then
    update public.account_subscriptions set status = 'trial_recovery',status_changed_at = now() where id = s.id;
    s.status := 'trial_recovery'; v_transitions := v_transitions + 1;
  end if;
  if s.status = 'trial_recovery' and now() &gt;= s.trial_recovery_ends_at then
    update public.account_subscriptions set status = 'expired',expired_at = now(),status_changed_at = now() where id = s.id;
    v_transitions := v_transitions + 1;
  end if;
  return jsonb_build_object('billingAccountId',p_billing_account_id,'transitions',v_transitions);
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_billing_provider_subscription(p_delivery uuid, p_snapshot jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare item jsonb:=p_snapshot-&gt;'verified_item'; seat public.billing_seat_quantity_operations%rowtype; processor text:=p_snapshot-&gt;&gt;'payment_processor'; o public.billing_plan_change_operations%rowtype; d public.billing_provider_webhook_deliveries%rowtype; b public.billing_provider_subscriptions%rowtype;
  t public.billing_checkout_attempts%rowtype; m public.billing_provider_variant_mappings%rowtype;
  a uuid; local_id uuid; old_kind text; local_status text; h text; code text; sid text; stamp timestamptz; end_at timestamptz;
  tx_at constant timestamptz:=transaction_timestamp(); cancel_pending boolean; provider_created timestamptz;
begin
  -- BILLING-DB-02 BEGIN
  perform public.billing_guard_legacy_entry('reconcile',p_delivery);
  -- BILLING-DB-02 END
  p_snapshot:=p_snapshot-array['payment_processor','verified_item'];
  select * into strict d from public.billing_provider_webhook_deliveries where id=p_delivery for update;
  if d.processing_status in ('processed','ignored') then return 'replayed'; end if;
  update public.billing_provider_webhook_deliveries set attempt_count=attempt_count+1,last_attempt_at=now(),last_error_code=null where id=d.id;
  if d.event_name not in ('subscription_plan_changed','subscription_created','subscription_updated','subscription_cancelled','subscription_resumed','subscription_expired','subscription_paused','subscription_unpaused','subscription_payment_success','subscription_payment_failed','subscription_payment_recovered') then
    update public.billing_provider_webhook_deliveries set processing_status='ignored',processed_at=now(),last_error_code='BILLING_WEBHOOK_UNSUPPORTED_EVENT' where id=d.id;
    return 'ignored';
  end if;
  -- Per-subscription lock followed by the same account lock used by capacity mutations.
  perform pg_advisory_xact_lock(hashtextextended('billing-subscription:'||d.environment||':'||d.provider_subscription_id,0));
  select * into b from public.billing_provider_subscriptions where provider=d.provider and environment=d.environment and provider_subscription_id=d.provider_subscription_id;
  if b.id is null and d.event_name&lt;&gt;'subscription_created' then
    update public.billing_provider_webhook_deliveries set processing_status='deferred',last_error_code='BILLING_RECONCILIATION_DEFERRED' where id=d.id;
    return 'deferred';
  end if;
  begin
    if p_snapshot is null or jsonb_typeof(p_snapshot)&lt;&gt;'object' or p_snapshot - array['provider','environment','store_id','subscription_id','customer_id','order_id','order_item_id','product_id','variant_id','price_id','first_subscription_item_id','quantity','status','cancelled','renews_at','ends_at','trial_ends_at','created_at','updated_at'] &lt;&gt; '{}'::jsonb then raise exception 'BILLING_RECONCILIATION_FAILED'; end if;
    if p_snapshot-&gt;&gt;'provider' is distinct from 'lemonsqueezy' or p_snapshot-&gt;&gt;'environment' is distinct from d.environment then raise exception 'BILLING_WEBHOOK_ENVIRONMENT_MISMATCH'; end if;
    if p_snapshot-&gt;&gt;'store_id' is distinct from public.get_billing_provider_store(d.environment) or p_snapshot-&gt;&gt;'store_id' is distinct from d.normalized_payload-&gt;&gt;'store_id' then raise exception 'BILLING_WEBHOOK_STORE_MISMATCH'; end if;
    sid:=p_snapshot-&gt;&gt;'subscription_id';
    if sid is distinct from d.provider_subscription_id then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
    if b.id is null then
      select * into t from public.billing_checkout_attempts where id=(d.normalized_payload-&gt;&gt;'checkout_attempt_id')::uuid;
      if t.id is null then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
      a:=t.billing_account_id;
      perform 1 from public.billing_accounts where id=a for update;
      -- Re-read under lock: checkout completion/expiry may have raced retrieval.
      select * into t from public.billing_checkout_attempts where id=t.id for update;
      if t.id is null or t.billing_account_id is distinct from (d.normalized_payload-&gt;&gt;'billing_account_id')::uuid
        or t.plan_version_id is distinct from (d.normalized_payload-&gt;&gt;'plan_version_id')::uuid or t.environment&lt;&gt;d.environment
        or t.status not in ('creating','ready','ambiguous','expired')
        or (p_snapshot-&gt;&gt;'created_at')::timestamptz not between t.created_at and t.expected_expires_at then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
      -- Delayed linkage uses the approved attempt, never a replacement sale mapping.
      select * into m from public.billing_provider_variant_mappings where id=t.variant_mapping_id for share;
      if m.id is null or m.status not in ('active','retired') or
        (m.status='retired' and (m.retired_at is null or t.created_at&gt;m.retired_at)) then raise exception 'BILLING_SUBSCRIPTION_VARIANT_MISMATCH'; end if;
    else
      a:=b.billing_account_id;
      perform 1 from public.billing_accounts where id=a for update;
      -- Existing obligations retain their exact immutable historical mapping.
      select * into m from public.billing_provider_variant_mappings where id=b.variant_mapping_id for share;
      if m.id is null or m.status not in ('active','retired') then raise exception 'BILLING_SUBSCRIPTION_VARIANT_MISMATCH'; end if;
    end if;
    if p_snapshot-&gt;&gt;'customer_id' is null or exists(select 1 from public.billing_provider_customers c where c.provider=d.provider and c.environment=d.environment and
      ((c.billing_account_id=a and c.provider_customer_id&lt;&gt;p_snapshot-&gt;&gt;'customer_id') or (c.provider_customer_id=p_snapshot-&gt;&gt;'customer_id' and c.billing_account_id&lt;&gt;a))) then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
    if b.id is not null then
      select * into o from public.billing_plan_change_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed') for update;
      -- Stale snapshots cannot turn an approved operation into manual review.
      if (p_snapshot-&gt;&gt;'updated_at')::timestamptz&lt;b.provider_updated_at then
        update public.billing_provider_webhook_deliveries set processing_status='ignored',processed_at=now(),last_error_code='BILLING_RECONCILIATION_STALE' where id=d.id;
        return 'ignored';
      end if;
      if o.id is not null and processor is distinct from 'card' then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
      if o.id is not null and (p_snapshot-&gt;&gt;'updated_at')::timestamptz&gt;=o.provider_requested_at then
        select v.* into m from public.billing_provider_variant_mappings v where
          v.id in (o.target_variant_mapping_id,case when o.status='cancel_pending' then o.source_variant_mapping_id else b.variant_mapping_id end)
          and (v.provider_product_id,v.provider_variant_id,v.provider_price_id)=(p_snapshot-&gt;&gt;'product_id',p_snapshot-&gt;&gt;'variant_id',p_snapshot-&gt;&gt;'price_id');
        if m.id is null then raise exception 'BILLING_UNAPPROVED_PLAN_CHANGE'; end if;
      end if;
    end if;
    -- Exact approved Price identity also fixes cadence: provider prices are immutable.
    -- No local plan-change operation exists in PR-PRICE-06.
    if b.id is not null and (m.provider_product_id is distinct from p_snapshot-&gt;&gt;'product_id' or
      m.provider_variant_id is distinct from p_snapshot-&gt;&gt;'variant_id' or m.provider_price_id is distinct from p_snapshot-&gt;&gt;'price_id') then
      raise exception 'BILLING_UNAPPROVED_PLAN_CHANGE'; end if;
    if m.environment&lt;&gt;d.environment or m.provider_store_id&lt;&gt;p_snapshot-&gt;&gt;'store_id' or m.provider_product_id is distinct from p_snapshot-&gt;&gt;'product_id' then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
    if m.provider_variant_id is distinct from p_snapshot-&gt;&gt;'variant_id' then raise exception 'BILLING_SUBSCRIPTION_VARIANT_MISMATCH'; end if;
    if m.provider_price_id is distinct from p_snapshot-&gt;&gt;'price_id' then raise exception 'BILLING_SUBSCRIPTION_PRICE_MISMATCH'; end if;
    if b.id is null then
      if (p_snapshot-&gt;&gt;'quantity')::integer is distinct from 1 then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
    else
      select * into seat from public.billing_seat_quantity_operations where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed') for update;
      if (p_snapshot-&gt;&gt;'quantity')::integer is distinct from 1+b.approved_additional_coach_seats and not
        (seat.id is not null and seat.variant_mapping_id=m.id and (p_snapshot-&gt;&gt;'quantity')::integer=seat.target_quantity and (p_snapshot-&gt;&gt;'updated_at')::timestamptz&gt;=seat.provider_requested_at) then
        raise exception 'BILLING_SEAT_QUANTITY_UNAPPROVED_DRIFT'; end if;
      if seat.id is not null or b.approved_additional_coach_seats&gt;0 or (p_snapshot-&gt;&gt;'quantity')::integer&gt;1 then
        if item is null or (item-&gt;&gt;'item_id',item-&gt;&gt;'subscription_id',item-&gt;&gt;'price_id',item-&gt;&gt;'quantity') is distinct from
          (b.first_subscription_item_id,b.provider_subscription_id,m.provider_price_id,p_snapshot-&gt;&gt;'quantity') or
          (item-&gt;&gt;'is_usage_based')::boolean is distinct from false or (item-&gt;&gt;'created_at') is null or (item-&gt;&gt;'updated_at') is null or
          (item-&gt;&gt;'updated_at')::timestamptz&lt;(item-&gt;&gt;'created_at')::timestamptz then raise exception 'BILLING_SEAT_QUANTITY_UNAPPROVED_DRIFT'; end if;
        if not exists(select 1 from public.billing_quantity_price_contracts where variant_mapping_id=m.id and status in ('active','retired')) then raise exception 'BILLING_SEAT_QUANTITY_PRICE_CONTRACT_MISMATCH'; end if;
      end if;
    end if;
    if p_snapshot-&gt;&gt;'status'='on_trial' or p_snapshot-&gt;&gt;'trial_ends_at' is not null then raise exception 'BILLING_SUBSCRIPTION_UNSUPPORTED_TRIAL'; end if;
    if p_snapshot-&gt;&gt;'status' is null or p_snapshot-&gt;&gt;'status' not in ('active','paused','past_due','unpaid','cancelled','expired') then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
    if jsonb_typeof(p_snapshot-&gt;'cancelled') is distinct from 'boolean' or
      (p_snapshot-&gt;&gt;'status'='cancelled' and (p_snapshot-&gt;&gt;'cancelled')::boolean is distinct from true) or
      (p_snapshot-&gt;&gt;'status' in ('active','paused','past_due','unpaid') and (p_snapshot-&gt;&gt;'cancelled')::boolean is distinct from false) then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
    stamp:=(p_snapshot-&gt;&gt;'updated_at')::timestamptz;
    if stamp is null then raise exception 'BILLING_RECONCILIATION_FAILED'; end if;
    if b.id is not null then
      if (b.provider_customer_id,b.provider_order_id,b.provider_order_item_id,b.first_subscription_item_id,b.provider_created_at) is distinct from
        (p_snapshot-&gt;&gt;'customer_id',p_snapshot-&gt;&gt;'order_id',p_snapshot-&gt;&gt;'order_item_id',p_snapshot-&gt;&gt;'first_subscription_item_id',(p_snapshot-&gt;&gt;'created_at')::timestamptz) then raise exception 'BILLING_SUBSCRIPTION_IDENTITY_MISMATCH'; end if;
      if stamp&lt;b.provider_updated_at then
        update public.billing_provider_webhook_deliveries set processing_status='ignored',processed_at=now(),last_error_code='BILLING_RECONCILIATION_STALE' where id=d.id;
        return 'ignored';
      end if;
    end if;
    h:=encode(extensions.digest(p_snapshot::text,'sha256'),'hex');
    if b.id is not null and stamp=b.provider_updated_at and h&lt;&gt;b.latest_snapshot_sha256 then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
    end_at:=(case when p_snapshot-&gt;&gt;'status' in ('cancelled','expired') then p_snapshot-&gt;&gt;'ends_at' else p_snapshot-&gt;&gt;'renews_at' end)::timestamptz;
    provider_created:=(p_snapshot-&gt;&gt;'created_at')::timestamptz;
    if provider_created is null or (b.id is null and end_at is not null and end_at&lt;=provider_created) or
      (p_snapshot-&gt;&gt;'status' in ('active','past_due','cancelled','expired') and end_at is null) then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
    local_status:=case p_snapshot-&gt;&gt;'status' when 'past_due' then 'past_due' when 'unpaid' then 'grace' when 'expired' then 'expired'
      when 'cancelled' then case when end_at&gt;tx_at then 'active' else 'expired' end else 'active' end;
    cancel_pending:=p_snapshot-&gt;&gt;'status'='cancelled' and end_at&gt;tx_at;
    if seat.id is not null then
      if processor is distinct from 'card' then raise exception 'BILLING_SEAT_QUANTITY_MANUAL_REVIEW'; end if;
      perform public.apply_verified_billing_seat_quantity(b.id,p_snapshot,d.event_name,d.normalized_payload);
    end if;
    if o.id is not null then
      perform public.apply_verified_billing_plan_change(o.id,p_snapshot,d.event_name,d.normalized_payload);
      select * into b from public.billing_provider_subscriptions where id=b.id;
    end if;

    if b.id is null then
      if exists(select 1 from public.account_subscriptions where billing_account_id=a and status in ('trialing','trial_recovery','active','past_due','grace','restricted') and subscription_kind not in ('trial','complimentary')) then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
      select subscription_kind into old_kind from public.account_subscriptions where billing_account_id=a and status in ('trialing','trial_recovery','active','past_due','grace','restricted');
      -- Cancellation terminalizes early trial access without rewriting immutable trial dates.
      update public.account_subscriptions set status='canceled',canceled_at=now(),status_changed_at=now() where billing_account_id=a and status in ('trialing','trial_recovery','active','past_due','grace','restricted');
      insert into public.account_subscriptions(billing_account_id,plan_version_id,subscription_kind,status,source,current_period_started_at,current_period_ends_at,cancel_at_period_end,expired_at)
        values(a,m.plan_version_id,'paid',local_status,'billing_provider',provider_created,end_at,cancel_pending,
          case when local_status='expired' then tx_at else null end) returning id into local_id;
      insert into public.billing_provider_customers(billing_account_id,provider,environment,provider_store_id,provider_customer_id)
        values(a,d.provider,d.environment,m.provider_store_id,p_snapshot-&gt;&gt;'customer_id') on conflict(billing_account_id,provider,environment) do update set last_seen_at=now(),updated_at=now();
      insert into public.billing_provider_subscriptions(billing_account_id,account_subscription_id,variant_mapping_id,provider,environment,provider_store_id,provider_customer_id,provider_subscription_id,provider_order_id,provider_order_item_id,provider_product_id,provider_variant_id,provider_price_id,first_subscription_item_id,quantity,provider_status,provider_cancelled,provider_renews_at,provider_ends_at,provider_trial_ends_at,provider_created_at,provider_updated_at,latest_snapshot_sha256,last_reconciled_at,reconciliation_status)
        values(a,local_id,m.id,d.provider,d.environment,m.provider_store_id,p_snapshot-&gt;&gt;'customer_id',sid,p_snapshot-&gt;&gt;'order_id',p_snapshot-&gt;&gt;'order_item_id',m.provider_product_id,m.provider_variant_id,m.provider_price_id,p_snapshot-&gt;&gt;'first_subscription_item_id',1,p_snapshot-&gt;&gt;'status',(p_snapshot-&gt;&gt;'cancelled')::boolean,
          (p_snapshot-&gt;&gt;'renews_at')::timestamptz,(p_snapshot-&gt;&gt;'ends_at')::timestamptz,null,provider_created,stamp,h,tx_at,'processed');
      update public.billing_checkout_attempts set status='completed',completed_at=now(),expired_at=null,error_code=null,provider_checkout_url=null,completed_provider_subscription_id=sid,updated_at=now() where id=t.id;
      -- A delayed creation delivery may arrive after another Checkout was opened.
      update public.billing_checkout_attempts set status='expired',expired_at=now(),provider_checkout_url=null,error_code='BILLING_CHECKOUT_EXPIRED',updated_at=now()
        where billing_account_id=a and id&lt;&gt;t.id and status in ('creating','ready','ambiguous');
    else
      local_id:=b.account_subscription_id;
      if exists(select 1 from public.account_subscriptions where billing_account_id=a and id&lt;&gt;local_id and status in ('trialing','trial_recovery','active','past_due','grace','restricted')) then raise exception 'BILLING_RECONCILIATION_MANUAL_REVIEW'; end if;
      if b.latest_snapshot_sha256&lt;&gt;h or exists(select 1 from public.account_subscriptions where id=local_id and
        (status is distinct from local_status or current_period_ends_at is distinct from end_at or cancel_at_period_end is distinct from cancel_pending)) then
        update public.account_subscriptions set status=local_status,status_changed_at=now(),
          expired_at=case when local_status='expired' then now() else null end,
          current_period_ends_at=end_at,cancel_at_period_end=cancel_pending where id=local_id;
        update public.billing_provider_subscriptions set quantity=(p_snapshot-&gt;&gt;'quantity')::integer,provider_status=p_snapshot-&gt;&gt;'status',provider_cancelled=(p_snapshot-&gt;&gt;'cancelled')::boolean,
          provider_renews_at=(p_snapshot-&gt;&gt;'renews_at')::timestamptz,provider_ends_at=(p_snapshot-&gt;&gt;'ends_at')::timestamptz,
          provider_updated_at=stamp,latest_snapshot_sha256=h,last_reconciled_at=now(),reconciliation_status='processed',reconciliation_error_code=null,updated_at=now() where id=b.id;
      end if;
      -- Health is independent of business changes. All validation and stale/equal
      -- timestamp guards have passed; do not write the local row or an event here.
      update public.billing_provider_subscriptions set reconciliation_status='processed',reconciliation_error_code=null,
        last_reconciled_at=tx_at,updated_at=tx_at where id=b.id;
    end if;
    update public.billing_provider_webhook_deliveries set processing_status='ignored',processed_at=now(),last_error_code=null
      where provider=d.provider and environment=d.environment and provider_subscription_id=sid and processing_status='deferred' and id&lt;&gt;d.id;
    update public.billing_provider_webhook_deliveries set processing_status='processed',processed_at=now(),last_error_code=null where id=d.id;
    if b.id is null then
      insert into public.account_subscription_events(billing_account_id,subscription_id,event_type,to_status,source,metadata)
        values(a,local_id,'subscription.converted_to_paid',local_status,'billing_provider',jsonb_build_object('previousKind',old_kind,'checkoutAttemptId',t.id));
    end if;
    return 'processed';
  exception when others then
    code:=sqlerrm;
    if code not in ('BILLING_SEAT_QUANTITY_UNAPPROVED_DRIFT','BILLING_SEAT_QUANTITY_PRICE_CONTRACT_MISMATCH','BILLING_SEAT_QUANTITY_MANUAL_REVIEW','BILLING_UNAPPROVED_PLAN_CHANGE','BILLING_WEBHOOK_ENVIRONMENT_MISMATCH','BILLING_WEBHOOK_STORE_MISMATCH','BILLING_SUBSCRIPTION_IDENTITY_MISMATCH','BILLING_SUBSCRIPTION_VARIANT_MISMATCH','BILLING_SUBSCRIPTION_PRICE_MISMATCH','BILLING_SUBSCRIPTION_UNSUPPORTED_TRIAL','BILLING_RECONCILIATION_MANUAL_REVIEW') then
      update public.billing_provider_webhook_deliveries set processing_status='failed',last_error_code='BILLING_RECONCILIATION_FAILED' where id=d.id;
      return 'failed';
    end if;
    update public.billing_plan_change_operations set status='manual_review',error_code='BILLING_PLAN_CHANGE_MANUAL_REVIEW',updated_at=now()
      where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed');
    update public.billing_seat_quantity_operations set status=case when status='cancel_pending' then status else 'manual_review' end,error_code='BILLING_SEAT_QUANTITY_MANUAL_REVIEW',updated_at=now()
      where billing_provider_subscription_id=b.id and status not in ('completed','canceled','failed');
    -- All activation writes above roll back together before review metadata is saved.
    update public.billing_provider_subscriptions set reconciliation_status='manual_review',reconciliation_error_code=code,
      quantity=case when code='BILLING_SEAT_QUANTITY_UNAPPROVED_DRIFT' and (p_snapshot-&gt;&gt;'quantity')::integer&gt;=1 then (p_snapshot-&gt;&gt;'quantity')::integer else quantity end where id=b.id;
    update public.billing_provider_webhook_deliveries set processing_status='ignored',processed_at=now(),last_error_code=code where id=d.id;
    return 'ignored';
  end;
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_client_checkins(p_client_id uuid, p_range_start date, p_range_end date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client record;
  v_template_id uuid;
  v_occurrence integer := 0;
  v_due_date date;
  v_due_dates date[] := '{}'::date[];
begin
  if p_client_id is null or p_range_start is null or p_range_end is null then
    return;
  end if;

  if p_range_end &lt; p_range_start then
    return;
  end if;

  select c.id, c.checkin_start_date, c.checkin_frequency
  into v_client
  from public.clients c
  where c.id = p_client_id;

  if v_client.id is null then
    return;
  end if;

  v_template_id := public.get_effective_client_checkin_template_id(p_client_id);

  if v_client.checkin_start_date is null or v_template_id is null then
    delete from public.checkins ci
    where ci.client_id = p_client_id
      and ci.submitted_at is null
      and ci.week_ending_saturday between p_range_start and p_range_end;
    return;
  end if;

  loop
    v_due_date := public.calculate_checkin_due_date(
      v_client.checkin_start_date,
      v_client.checkin_frequency,
      v_occurrence
    );

    exit when v_due_date is null or v_due_date &gt; p_range_end;

    if v_due_date &gt;= p_range_start then
      v_due_dates := array_append(v_due_dates, v_due_date);

      insert into public.checkins (client_id, template_id, week_ending_saturday)
      values (p_client_id, v_template_id, v_due_date)
      on conflict (client_id, week_ending_saturday) do update
      set template_id = excluded.template_id
      where public.checkins.submitted_at is null
        and public.checkins.template_id is distinct from excluded.template_id;
    end if;

    v_occurrence := v_occurrence + 1;
    exit when v_occurrence &gt; 1000;
  end loop;

  delete from public.checkins ci
  where ci.client_id = p_client_id
    and ci.submitted_at is null
    and ci.week_ending_saturday between p_range_start and p_range_end
    and not (ci.week_ending_saturday = any(v_due_dates));
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_paddle_initial_purchase_event_v1(p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare enabled boolean; e public.billing_webhook_events_v2%rowtype;
 o public.billing_paddle_event_observations%rowtype; s public.billing_subscriptions_v2%rowtype;
 checkout public.billing_checkouts_v2%rowtype; account uuid; counterpart text; result jsonb;
begin
 perform public.billing_guard_actor();
 select paddle_reconciliation_enabled into enabled from public.billing_runtime_policy where id=1 for share;
 if not coalesce(enabled,false) then return jsonb_build_object('status','disabled'); end if;
 select * into e from public.billing_webhook_events_v2 where id=p_event;
 select * into o from public.billing_paddle_event_observations where event_id=p_event;
 if e.id is null or o.event_id is null or e.provider&lt;&gt;'paddle' or e.environment&lt;&gt;'test' then
 raise exception 'PADDLE_AUTO_RECONCILIATION_SCOPE'; end if;
 if o.observation-&gt;&gt;'kind'='subscription.updated' or (o.observation-&gt;&gt;'kind'='transaction.completed' and o.checkout_id is null) then
 result:=public.reconcile_paddle_seat_quantity_event_v1(p_event); if result-&gt;&gt;'status'&lt;&gt;'not_applicable' then return result;end if; result:=public.reconcile_paddle_plan_change_event_v1(p_event);
 if result-&gt;&gt;'status'&lt;&gt;'not_applicable' then return result;end if;
 return public.reconcile_paddle_lifecycle_event_v1(p_event); end if;
 if o.observation-&gt;&gt;'kind' not in ('transaction.completed','subscription.created') then
 return jsonb_build_object('status','not_applicable'); end if;
 select * into checkout from public.billing_checkouts_v2 where id=o.checkout_id;
 select * into s from public.billing_subscriptions_v2 where provider='paddle' and environment='test'
 and provider_subscription_ref=e.subscription_ref;
 account:=coalesce(checkout.billing_account_id,s.billing_account_id);
 -- Same policy -&gt; account ordering as ingress. No ingress lock is acquired
 -- here, and no provider/event row is locked before the account lock.
 perform public.billing_guard_lock(account,'test');
 select * into s from public.billing_subscriptions_v2 where provider='paddle' and environment='test'
 and provider_subscription_ref=e.subscription_ref;
 if s.id is not null and s.billing_account_id&lt;&gt;account then raise exception 'PADDLE_AUTO_RECONCILIATION_IDENTITY'; end if;
 counterpart:=case when o.observation-&gt;&gt;'kind'='transaction.completed' then 'subscription.created' else 'transaction.completed' end;
 -- Include rejected/manual-review counterparts: presence must never hide a
 -- hard proof failure behind an ordering response.
 if not exists(select 1 from public.billing_paddle_event_observations other
 join public.billing_webhook_events_v2 oe on oe.id=other.event_id
 where oe.provider='paddle' and oe.environment='test' and other.observation-&gt;&gt;'kind'=counterpart
 and (other.checkout_id=checkout.id or oe.subscription_ref=e.subscription_ref
 or coalesce(other.observation-&gt;&gt;'transactionRef',other.observation-&gt;&gt;'transactionCorrelationRef')=
 coalesce(o.observation-&gt;&gt;'transactionRef',o.observation-&gt;&gt;'transactionCorrelationRef'))) then
 return jsonb_build_object('status','pending'); end if;
 if account is null or checkout.id is null or checkout.provider&lt;&gt;'paddle' or checkout.environment&lt;&gt;'test'
 or checkout.billing_account_id&lt;&gt;account or coalesce(o.observation-&gt;&gt;'transactionRef',o.observation-&gt;&gt;'transactionCorrelationRef')
 is distinct from checkout.provider_transaction_ref::text then raise exception 'PADDLE_AUTO_RECONCILIATION_CORRELATION'; end if;
 if s.id is null or s.shadow_status&lt;&gt;'current' or s.billing_account_id&lt;&gt;account then
 raise exception 'PADDLE_AUTO_RECONCILIATION_IDENTITY'; end if;
 -- An initial replay after a lifecycle transition must not restore initial state.
 if exists(select 1 from public.billing_evidence_v2 le where le.id=s.latest_evidence_id
 and le.subscription_id=s.id and le.proof_schema in ('paddle-subscription-lifecycle-v1','paddle-plan-change-v1','paddle-seat-quantity-v1')) then
  perform public.billing_paddle_reconciliation_event_v1(p_event);
  if checkout.status&lt;&gt;'completed' or checkout.completed_subscription_id is distinct from s.id
  or not exists(select 1 from public.billing_payment_applications_v2 p join public.billing_evidence_v2 pe on pe.id=p.evidence_id
   where p.subscription_id=s.id and p.checkout_id=checkout.id and p.application_kind='initial_purchase'
   and pe.proof_schema='paddle-initial-purchase-v1'
   and p_event in ((pe.proof#&gt;&gt;'{observation,subscriptionEventId}')::uuid,(pe.proof#&gt;&gt;'{observation,transactionEventId}')::uuid))
  then raise exception 'PADDLE_AUTO_RECONCILIATION_CORRELATION'; end if;
  return jsonb_build_object('status','reused');
 end if;
 result:=public.reconcile_paddle_initial_purchase_v1(s.id,'initial_purchase');
 if result-&gt;'success' is distinct from 'true'::jsonb or jsonb_typeof(result-&gt;'reused') is distinct from 'boolean' then
 raise exception 'PADDLE_AUTO_RECONCILIATION_RESULT'; end if;
 return jsonb_build_object('status',case when (result-&gt;&gt;'reused')::boolean then 'reused' else 'applied' end);
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_paddle_initial_purchase_v1(p_subscription uuid, p_operation text DEFAULT 'initial_purchase'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare facts jsonb; s public.billing_subscriptions_v2%rowtype; canonical uuid; se uuid; te uuid; payment uuid; checkout public.billing_checkouts_v2%rowtype;
 current_ids uuid[]; trial public.account_subscriptions%rowtype;
 conversion_at timestamptz:=transaction_timestamp();
begin
 perform public.billing_guard_actor();
 if p_operation is distinct from 'initial_purchase' then raise exception 'PADDLE_RECONCILIATION_OPERATION'; end if;
 facts:=public.billing_paddle_initial_proof_v1(p_subscription);
 select * into s from public.billing_subscriptions_v2 where id=p_subscription;
 select * into strict checkout from public.billing_checkouts_v2 where id=(facts-&gt;&gt;'checkoutId')::uuid;
 if checkout.status not in ('ready','completed') or
 (checkout.status='completed' and (checkout.completed_subscription_id is distinct from s.id
 or checkout.completed_at is null or s.reconciliation_status&lt;&gt;'processed')) then
 raise exception 'PADDLE_RECONCILIATION_CHECKOUT_STATE'; end if;
 if s.reconciliation_status='processed' then
 if s.account_subscription_id is null or not exists(select 1 from public.billing_evidence_v2 e
 where e.id=s.latest_evidence_id and e.proof_schema='paddle-initial-purchase-v1' and e.proof-&gt;'observation'=facts)
 or not exists(select 1 from public.billing_payment_applications_v2 p join public.billing_evidence_v2 e on e.id=p.evidence_id
 where p.subscription_id=s.id and p.billing_account_id=s.billing_account_id and p.provider='paddle' and p.environment='test'
 and p.checkout_id=(facts-&gt;&gt;'checkoutId')::uuid and p.application_kind='initial_purchase'
 and e.proof_schema='paddle-initial-purchase-v1' and e.proof-&gt;'observation'=facts)
 or not exists(select 1 from public.account_subscriptions a join public.billing_canonical_origins o on o.account_subscription_id=a.id
 where a.id=s.account_subscription_id and a.billing_account_id=s.billing_account_id and a.subscription_kind='paid'
 and a.status='active' and a.plan_version_id=(facts-&gt;&gt;'planVersionId')::uuid and o.storage_contract='billing.v2')
 or not exists(select 1 from public.billing_subscription_items_v2 where subscription_id=s.id and item_role='base_plan'
 and quantity=1 and cadence='monthly' and mapping_id=(facts-&gt;&gt;'mappingId')::uuid and evidence_id=s.latest_evidence_id)
 or (select count(*) from public.billing_subscription_items_v2 where subscription_id=s.id)&lt;&gt;1 then
 raise exception 'PADDLE_RECONCILIATION_RETRY_MISMATCH'; end if;
 -- Application lifecycle time, not a fabricated provider timestamp. The proof
 -- helper holds the account and checkout locks for this entire transaction.
 if checkout.status='ready' then
 update public.billing_checkouts_v2 set status='completed',completed_subscription_id=s.id,
 completed_at=clock_timestamp(),updated_at=clock_timestamp(),error_code=null where id=checkout.id;
 end if;
 return jsonb_build_object('success',true,'reused',true);
 end if;
 if s.account_subscription_id is not null then raise exception 'PADDLE_RECONCILIATION_CANONICAL_CONFLICT'; end if;
 -- The proof helper already owns policy -&gt; account -&gt; shadow/checkout locks.
 -- Re-read and lock canonical authority only after that account serialization.
 select array_agg(id) into current_ids from (
 select id from public.account_subscriptions where billing_account_id=s.billing_account_id
 and status in ('trialing','trial_recovery','active','past_due','grace','restricted')
 order by id for update) current_rows;
 if cardinality(current_ids)&gt;1 then raise exception 'PADDLE_RECONCILIATION_CANONICAL_CONFLICT'; end if;
 if cardinality(current_ids)=1 then
 select * into strict trial from public.account_subscriptions where id=current_ids[1];
 -- Only normal RepSync trials, including their recovery window. Immutable
 -- published policy/dates remain authoritative, even after policy retirement.
 if trial.subscription_kind&lt;&gt;'trial' or trial.status not in ('trialing','trial_recovery')
 or trial.source not in ('first_workspace','workspace_transfer')
 or trial.canceled_at is not null or trial.expired_at is not null or trial.restricted_at is not null
 or trial.current_period_started_at is not null or trial.current_period_ends_at is not null
 or trial.cancel_at_period_end or trial.trial_started_at&gt;conversion_at
 or public.effective_account_subscription_status(trial.subscription_kind,trial.status,
 trial.trial_ends_at,trial.trial_recovery_ends_at,conversion_at) not in ('trialing','trial_recovery')
 or (trial.status='trial_recovery' and conversion_at&lt;trial.trial_ends_at)
 or not exists(select 1 from public.commercial_trial_policy_versions p
 where p.id=trial.trial_policy_version_id and p.status in ('active','retired')
 and p.feature_plan_version_id=trial.plan_version_id
 and trial.trial_ends_at=trial.trial_started_at+make_interval(days=&gt;p.duration_days)
 and trial.trial_recovery_ends_at=trial.trial_ends_at+make_interval(days=&gt;p.recovery_days))
 or exists(select 1 from public.billing_canonical_origins where account_subscription_id=trial.id)
 then raise exception 'PADDLE_RECONCILIATION_CANONICAL_CONFLICT'; end if;
 end if;
 if exists(select 1 from public.billing_provider_subscriptions where billing_account_id=s.billing_account_id
 and provider_status not in ('expired','cancelled'))
 or exists(select 1 from public.billing_subscriptions_v2 where billing_account_id=s.billing_account_id and account_subscription_id is not null)
 then raise exception 'PADDLE_RECONCILIATION_CANONICAL_CONFLICT'; end if;
 if exists(select 1 from public.billing_payment_applications_v2 where checkout_id=(facts-&gt;&gt;'checkoutId')::uuid
 or provider_transaction_ref=(select provider_transaction_ref from public.billing_checkouts_v2 where id=(facts-&gt;&gt;'checkoutId')::uuid)) then
 raise exception 'PADDLE_RECONCILIATION_PAYMENT_CONSUMED'; end if;
 if exists(select 1 from public.billing_subscription_items_v2 where subscription_id=s.id) then
 raise exception 'PADDLE_RECONCILIATION_ITEMS'; end if;
 -- Terminalization and every subsequent proof/authority/audit write share this
 -- transaction. No exception handler may retain a partially converted trial.
 if trial.id is not null then
 update public.account_subscriptions set status='canceled',canceled_at=conversion_at,
 status_changed_at=conversion_at where id=trial.id;
 end if;
 se:=public.billing_paddle_initial_evidence_v1(s.id,'subscription');
 te:=public.billing_paddle_initial_evidence_v1(s.id,'transaction');
 payment:=public.billing_paddle_initial_payment_v1(s.id,te);
 -- Reuse canonical table constraints/history/audit, not LS proof semantics.
 insert into public.account_subscriptions(billing_account_id,plan_version_id,subscription_kind,status,source)
 values(s.billing_account_id,(facts-&gt;&gt;'planVersionId')::uuid,'paid','active','billing_provider') returning id into canonical;
 perform public.billing_guard_claim_canonical(s.billing_account_id,canonical,'billing.v2');
 insert into public.billing_subscription_items_v2(subscription_id,billing_account_id,provider,environment,item_role,mapping_id,cadence,mapping_kind,quantity,evidence_id)
 values(s.id,s.billing_account_id,'paddle','test','base_plan',(facts-&gt;&gt;'mappingId')::uuid,'monthly','plan',1,se);
 update public.billing_subscriptions_v2 set account_subscription_id=canonical,latest_evidence_id=se,
 latest_snapshot_sha256=(select normalized_sha256 from public.billing_evidence_v2 where id=se),
 last_reconciled_at=clock_timestamp(),reconciliation_status='processed',reconciliation_error_code=null,updated_at=clock_timestamp()
 where id=s.id;
 -- Existing deferred item-set constraints validate at commit. Any error rolls
 -- back evidence, application, canonical row, origin, item and link together.
 -- Application lifecycle time, not a fabricated provider timestamp. The proof
 -- helper holds the account and checkout locks for this entire transaction.
 if checkout.status='ready' then
 update public.billing_checkouts_v2 set status='completed',completed_subscription_id=s.id,
 completed_at=clock_timestamp(),updated_at=clock_timestamp(),error_code=null where id=checkout.id;
 end if;
 if trial.id is not null then
 -- Existing triggers record the trial status change and paid-row creation.
 -- This single semantic event links those two records without duplicating them.
 insert into public.account_subscription_events(billing_account_id,subscription_id,event_type,
 to_status,source,metadata,occurred_at)
 values(s.billing_account_id,canonical,'subscription.converted_to_paid','active','billing_provider',
 jsonb_build_object('previousKind','trial','previousSubscriptionId',trial.id,'checkoutAttemptId',checkout.id),conversion_at);
 end if;
 perform public.bootstrap_paddle_initial_period_v1(s.id);
 return jsonb_build_object('success',true,'reused',false);
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_paddle_lifecycle_event_v1(p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare o jsonb; so jsonb; s public.billing_subscriptions_v2%rowtype; e public.billing_webhook_events_v2%rowtype;
 se uuid; te uuid; evidence uuid; payment_evidence uuid; facts jsonb; matches integer; result text; applied_at timestamptz;
begin
 perform public.billing_guard_actor();
 perform 1 from public.billing_runtime_policy where id=1 for share;
 if not coalesce((select paddle_reconciliation_enabled from public.billing_runtime_policy where id=1),false) then return jsonb_build_object('status','disabled'); end if;
 select * into e from public.billing_webhook_events_v2 where id=p_event;
 select observation into o from public.billing_paddle_event_observations where event_id=p_event;
 if e.provider is distinct from 'paddle' or e.environment is distinct from 'test' or o is null then raise exception 'PADDLE_LIFECYCLE_SCOPE'; end if;
 if o-&gt;&gt;'kind' not in ('subscription.updated','transaction.completed')
 or (o-&gt;&gt;'kind'='subscription.updated' and not (o ? 'updatedAt')) then return jsonb_build_object('status','not_applicable'); end if;
 select * into s from public.billing_subscriptions_v2 where provider='paddle' and environment='test' and provider_subscription_ref=e.subscription_ref;
 perform public.billing_guard_lock(s.billing_account_id,'test');
 select * into s from public.billing_subscriptions_v2 where id=s.id for update;
 if s.account_subscription_id is null then return jsonb_build_object('status','pending'); end if;
 -- Retained immutable application evidence proves replay even after newer state.
 if exists(select 1 from public.billing_evidence_v2 where event_id=p_event and subscription_id=s.id and proof_schema='paddle-subscription-lifecycle-v1') then
 return jsonb_build_object('status','reused'); end if;
 begin
  perform public.billing_paddle_reconciliation_event_v1(p_event);
  if o-&gt;&gt;'kind'='transaction.completed' then
   if o-&gt;&gt;'origin' is distinct from 'subscription_recurring' or o-&gt;'billingPeriod' is null or o-&gt;'billingPeriod'='null'::jsonb then raise exception 'PADDLE_LIFECYCLE_PAYMENT'; end if;
   te:=p_event;
   select count(*) into matches from public.billing_paddle_event_observations po
   where po.observation-&gt;&gt;'subscriptionRef'=e.subscription_ref and po.observation-&gt;&gt;'kind'='subscription.updated'
   and po.observation-&gt;&gt;'status'='active' and public.billing_paddle_period_equal_v1(po.observation-&gt;'currentBillingPeriod',o-&gt;'billingPeriod');
   if matches=0 then return jsonb_build_object('status','pending'); end if;
   -- Only the newest matching lifecycle observation can authorize renewal.
   select po.event_id,po.observation into se,so from public.billing_paddle_event_observations po
   where po.observation-&gt;&gt;'subscriptionRef'=e.subscription_ref and po.observation-&gt;&gt;'kind'='subscription.updated'
   and po.observation-&gt;&gt;'status'='active' and public.billing_paddle_period_equal_v1(po.observation-&gt;'currentBillingPeriod',o-&gt;'billingPeriod')
   order by (po.observation-&gt;&gt;'updatedAt')::timestamptz desc nulls last,po.event_id limit 1;
  else se:=p_event; so:=o; end if;
  if exists(select 1 from public.billing_paddle_event_observations po where po.event_id&lt;&gt;se
   and po.observation-&gt;&gt;'subscriptionRef'=so-&gt;&gt;'subscriptionRef' and po.observation-&gt;&gt;'kind'='subscription.updated'
   and (po.observation-&gt;&gt;'updatedAt')::timestamptz=(so-&gt;&gt;'updatedAt')::timestamptz
   and (po.observation-array['eventRef','occurredAt'])&lt;&gt;(so-array['eventRef','occurredAt'])) then
   raise exception 'PADDLE_LIFECYCLE_AMBIGUOUS_STATE'; end if;
  if so-&gt;&gt;'status'='active' and (o-&gt;&gt;'kind'='transaction.completed' or
   (so#&gt;&gt;'{currentBillingPeriod,endsAt}')::timestamptz&gt;coalesce(s.current_period_ends_at,'-infinity'::timestamptz)) then
   select count(*),min(po.event_id::text)::uuid into matches,te from public.billing_paddle_event_observations po
   where po.observation-&gt;&gt;'subscriptionRef'=e.subscription_ref and po.observation-&gt;&gt;'kind'='transaction.completed'
   and po.checkout_id is null and public.billing_paddle_period_equal_v1(po.observation-&gt;'billingPeriod',so-&gt;'currentBillingPeriod');
   if matches&gt;1 then raise exception 'PADDLE_LIFECYCLE_AMBIGUOUS_PAYMENT'; end if;
  end if;
  facts:=public.billing_paddle_lifecycle_facts_v1(se,te);
  evidence:=public.billing_paddle_lifecycle_evidence_v1(se,te,'subscription');
  if te is not null then
   payment_evidence:=public.billing_paddle_lifecycle_evidence_v1(se,te,'transaction');
   insert into public.billing_payment_applications_v2(provider,environment,provider_transaction_ref,billing_account_id,subscription_id,evidence_id,application_kind)
   select 'paddle','test',provider_transaction_ref,s.billing_account_id,s.id,id,'renewal' from public.billing_evidence_v2 where id=payment_evidence;
  end if;
  applied_at:=clock_timestamp();
  update public.account_subscriptions set status=facts-&gt;&gt;'canonicalStatus',
   status_changed_at=case when status&lt;&gt;facts-&gt;&gt;'canonicalStatus' then applied_at else status_changed_at end,
   expired_at=case when facts-&gt;&gt;'canonicalStatus'='expired' then applied_at else expired_at end,
   current_period_started_at=(facts-&gt;&gt;'periodStart')::timestamptz,current_period_ends_at=(facts-&gt;&gt;'periodEnd')::timestamptz,
   cancel_at_period_end=facts-&gt;&gt;'scheduledCancelAt' is not null where id=s.account_subscription_id;
  update public.billing_subscriptions_v2 set approved_additional_coach_seats=(facts-&gt;&gt;'approvedSeats')::integer,provider_status=facts-&gt;&gt;'providerStatus',provider_updated_at=(facts-&gt;&gt;'providerUpdatedAt')::timestamptz,
   current_period_started_at=(facts-&gt;&gt;'periodStart')::timestamptz,current_period_ends_at=(facts-&gt;&gt;'periodEnd')::timestamptz,
   scheduled_cancel_at=(facts-&gt;&gt;'scheduledCancelAt')::timestamptz,latest_evidence_id=evidence,
   latest_snapshot_sha256=(select normalized_sha256 from public.billing_evidence_v2 where id=evidence),
   last_reconciled_at=clock_timestamp(),updated_at=clock_timestamp() where id=s.id;
  update public.billing_webhook_events_v2 set processing_status='processed',processed_at=clock_timestamp(),last_error_code=null where id in (se,te);
  update public.billing_operations_v2 set status='completed',completed_at=clock_timestamp(),updated_at=clock_timestamp()
 where subscription_id=s.id and operation_kind='seat_quantity' and status='scheduled' and effective_timing='period_end'
 and target_additional_seats=(facts-&gt;&gt;'approvedSeats')::integer and effective_at=(facts-&gt;&gt;'periodStart')::timestamptz and facts-&gt;'renewal'='true'::jsonb;
 insert into public.billing_operation_events_v2(operation_id,event_type) select id,'billing.seat_quantity_completed' from public.billing_operations_v2
 where subscription_id=s.id and operation_kind='seat_quantity' and status='completed' on conflict do nothing;
 if facts-&gt;&gt;'providerStatus'&lt;&gt;'active' or facts-&gt;&gt;'scheduledCancelAt' is not null then
  update public.billing_operations_v2 set status='manual_review',error_code='BILLING_SEAT_QUANTITY_MANUAL_REVIEW',updated_at=clock_timestamp()
  where subscription_id=s.id and operation_kind='seat_quantity' and status not in ('completed','canceled','failed');
 end if;
 result:='applied';
 exception when raise_exception then
  -- Only enumerated proof failures become review. Unexpected database errors
  -- propagate and roll back; no partial payment or canonical write survives.
  if sqlerrm='PADDLE_LIFECYCLE_PAYMENT_REQUIRED' then result:='pending';
  elsif sqlerrm like 'PADDLE_LIFECYCLE_%' or sqlerrm='PADDLE_RECONCILIATION_VERIFIED_EVENT_REQUIRED' then
   update public.billing_webhook_events_v2 set processing_status='manual_review',last_error_code='PADDLE_LIFECYCLE_REVIEW' where id=p_event;
   result:='manual_review';
  else raise; end if;
 end;
 return jsonb_build_object('status',result);
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_paddle_plan_change_event_v1(p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.billing_subscriptions_v2%rowtype;op public.billing_operations_v2%rowtype;o jsonb;so jsonb;se uuid;te uuid;matches integer;
 facts jsonb;v_evidence uuid;payment uuid;target uuid;stamp timestamptz;pf jsonb; result text;
begin
 perform public.billing_guard_actor();perform 1 from public.billing_runtime_policy where id=1 for share;
 if not (select paddle_reconciliation_enabled from public.billing_runtime_policy where id=1) then return jsonb_build_object('status','disabled'); end if;
 select observation into o from public.billing_paddle_event_observations where event_id=p_event;
 select * into s from public.billing_subscriptions_v2 where provider='paddle' and environment='test' and provider_subscription_ref=o-&gt;&gt;'subscriptionRef';
 perform public.billing_guard_lock(s.billing_account_id,'test');
 select * into s from public.billing_subscriptions_v2 where id=s.id for update;
 select * into op from public.billing_operations_v2 where subscription_id=s.id and operation_kind='plan_change' and status not in ('completed','canceled','failed') for update;
 if exists(select 1 from public.billing_evidence_v2 where event_id=p_event and proof_schema='paddle-plan-change-v1')
 and not coalesce(op.status='scheduled' and public.billing_paddle_plan_now_v1()&gt;=op.effective_at,false) then return jsonb_build_object('status','reused');end if;
 if op.id is null then return jsonb_build_object('status','not_applicable'); end if;
 -- Finalize the already verified schedule using its original paid period first.
 -- A new-period event must still pass the existing lifecycle payment proof.
 if op.status='scheduled' and public.billing_paddle_plan_now_v1()&gt;=op.effective_at
 and (o-&gt;&gt;'origin'='subscription_recurring' or (o#&gt;&gt;'{currentBillingPeriod,startsAt}')::timestamptz=op.effective_at) then
  perform public.reconcile_paddle_plan_change_event_v1((select event_id from public.billing_evidence_v2 where id=op.last_evidence_id));
  if (select status from public.billing_operations_v2 where id=op.id)='completed' then return jsonb_build_object('status','not_applicable');end if;
  return jsonb_build_object('status','manual_review');
 end if;
 if (o-&gt;&gt;'occurredAt')::timestamptz&lt;op.provider_requested_at or (o-&gt;&gt;'updatedAt')::timestamptz&lt;=s.provider_updated_at then return jsonb_build_object('status','reused'); end if;
 begin
  perform public.billing_paddle_reconciliation_event_v1(p_event);
  if o-&gt;&gt;'kind'='transaction.completed' then
   if o-&gt;&gt;'origin'='subscription_recurring' then return jsonb_build_object('status','not_applicable'); end if;
   te:=p_event;
   select po.event_id,po.observation into se,so from public.billing_paddle_event_observations po
   where po.observation-&gt;&gt;'subscriptionRef'=s.provider_subscription_ref and po.observation-&gt;&gt;'kind'='subscription.updated'
   and po.observation-&gt;&gt;'planChangeOperationId'=op.operation_id::text
   order by (po.observation-&gt;&gt;'updatedAt')::timestamptz desc,po.event_id limit 1;
   if se is null then return jsonb_build_object('status','pending'); end if;
  elsif o-&gt;&gt;'kind'='subscription.updated' then se:=p_event;so:=o;
  else return jsonb_build_object('status','not_applicable'); end if;
  -- Cancellation wins; never turn a cancellation into plan authority.
  if so-&gt;&gt;'status'='canceled' or so#&gt;&gt;'{scheduledChange,action}'='cancel' then
   update public.billing_operations_v2 set status='manual_review',error_code='BILLING_PLAN_CHANGE_MANUAL_REVIEW',updated_at=public.billing_paddle_plan_now_v1() where id=op.id;
   return jsonb_build_object('status','not_applicable');
  end if;
  if exists(select 1 from public.billing_paddle_event_observations po where po.event_id&lt;&gt;se and po.observation-&gt;&gt;'subscriptionRef'=s.provider_subscription_ref
   and po.observation-&gt;&gt;'kind'='subscription.updated' and (po.observation-&gt;&gt;'updatedAt')::timestamptz&gt;=(so-&gt;&gt;'updatedAt')::timestamptz
   and (po.observation-array['eventRef','occurredAt'])&lt;&gt;(so-array['eventRef','occurredAt'])
   and not coalesce((op.status='scheduled' and public.billing_paddle_plan_now_v1()&gt;=op.effective_at
    and po.observation-&gt;'planChangeOperationId'=so-&gt;'planChangeOperationId' and po.observation-&gt;'items'=so-&gt;'items'
    and po.observation-&gt;&gt;'status'='active' and po.observation-&gt;'scheduledChange'='null'::jsonb
    and po.observation-&gt;'canceledAt'='null'::jsonb and po.observation-&gt;'pausedAt'='null'::jsonb
    and (po.observation#&gt;&gt;'{currentBillingPeriod,startsAt}')::timestamptz=op.effective_at),false)) then raise exception 'PADDLE_PLAN_STATE'; end if;
  if op.effective_timing='immediate' then
   select count(*),min(po.event_id::text)::uuid into matches,te from public.billing_paddle_event_observations po
   where po.observation-&gt;&gt;'subscriptionRef'=s.provider_subscription_ref and po.observation-&gt;&gt;'kind'='transaction.completed'
   and po.observation-&gt;&gt;'planChangeOperationId'=op.operation_id::text and po.observation-&gt;&gt;'origin'='subscription_update';
   if matches&gt;1 then raise exception 'PADDLE_PLAN_PAYMENT'; end if;
  end if;
  facts:=public.billing_paddle_plan_facts_v1(op.id,se,te);
  if op.effective_timing='immediate' and (te is null or so-&gt;&gt;'status'&lt;&gt;'active') then
   update public.billing_operations_v2 set status='awaiting_payment',error_code=case when so-&gt;&gt;'status'='past_due' then 'BILLING_PLAN_CHANGE_PAYMENT_FAILED' end,updated_at=public.billing_paddle_plan_now_v1() where id=op.id;
   return jsonb_build_object('status','pending');
  end if;
  v_evidence:=public.billing_paddle_plan_evidence_v1(op.id,se,te,'subscription');
  if te is not null then
   payment:=public.billing_paddle_plan_evidence_v1(op.id,se,te,'transaction');
   insert into public.billing_payment_applications_v2(provider,environment,provider_transaction_ref,billing_account_id,subscription_id,evidence_id,application_kind,operation_id)
   select 'paddle','test',provider_transaction_ref,op.billing_account_id,s.id,id,'plan_change',op.id from public.billing_evidence_v2 where id=payment;
  end if;
  update public.billing_operations_v2 set status=case when effective_timing='period_end' then 'scheduled' else 'awaiting_payment' end,
  provider_applied_at=coalesce(provider_applied_at,public.billing_paddle_plan_now_v1()),last_evidence_id=v_evidence,updated_at=public.billing_paddle_plan_now_v1(),error_code=null where id=op.id;
  if op.effective_timing='immediate' or public.billing_paddle_plan_now_v1()&gt;=op.effective_at then
   pf:=public.billing_plan_change_preflight(op.created_by_user_id,op.billing_account_id,(facts-&gt;&gt;'targetPlanVersionId')::uuid);
   if op.effective_timing='period_end' and (pf-&gt;'blockers'&lt;&gt;'[]'::jsonb or pf#&gt;'{snapshot,hasAnyDataQualityIssue}'='true'::jsonb) then raise exception 'PADDLE_PLAN_CAPACITY'; end if;
   target:=gen_random_uuid();stamp:=public.billing_paddle_plan_now_v1();
   update public.account_subscriptions set status='superseded',superseded_at=stamp,superseded_by_subscription_id=target,status_changed_at=stamp where id=op.source_account_subscription_id;
   insert into public.account_subscriptions(id,billing_account_id,plan_version_id,subscription_kind,status,source,current_period_started_at,current_period_ends_at)
   values(target,op.billing_account_id,(facts-&gt;&gt;'targetPlanVersionId')::uuid,'paid',facts-&gt;&gt;'providerStatus','billing_provider',(facts-&gt;&gt;'periodStart')::timestamptz,(facts-&gt;&gt;'periodEnd')::timestamptz);
   update public.billing_subscriptions_v2 set account_subscription_id=target,provider_status=facts-&gt;&gt;'providerStatus',provider_updated_at=(facts-&gt;&gt;'providerUpdatedAt')::timestamptz,
   current_period_started_at=(facts-&gt;&gt;'periodStart')::timestamptz,current_period_ends_at=(facts-&gt;&gt;'periodEnd')::timestamptz,
   latest_evidence_id=v_evidence,latest_snapshot_sha256=(select normalized_sha256 from public.billing_evidence_v2 where id=v_evidence),last_reconciled_at=stamp,updated_at=stamp where id=s.id;
   update public.billing_operations_v2 set status='completed',completed_at=stamp,payment_confirmed_at=case when payment is not null then stamp end,updated_at=stamp where id=op.id;
   insert into public.billing_operation_events_v2(operation_id,event_type) values(op.id,'billing.plan_change_completed') on conflict do nothing;
  else
   insert into public.billing_operation_events_v2(operation_id,event_type) values(op.id,'billing.plan_change_scheduled') on conflict do nothing;
  end if;
  update public.billing_webhook_events_v2 set processing_status='processed',processed_at=public.billing_paddle_plan_now_v1(),last_error_code=null where id in (se,te);
  result:='applied';
 exception when raise_exception then
  if sqlerrm like 'PADDLE_PLAN_%' or sqlerrm like 'PADDLE_LIFECYCLE_%' or sqlerrm='PADDLE_RECONCILIATION_VERIFIED_EVENT_REQUIRED' then
   update public.billing_operations_v2 set status='manual_review',error_code='BILLING_PLAN_CHANGE_MANUAL_REVIEW',updated_at=public.billing_paddle_plan_now_v1() where id=op.id;
   update public.billing_webhook_events_v2 set processing_status='manual_review',last_error_code='PADDLE_PLAN_REVIEW' where id=p_event;
   result:='manual_review';
  else raise; end if;
 end;
 return jsonb_build_object('status',result);
end $function$

CREATE OR REPLACE FUNCTION public.reconcile_paddle_seat_quantity_event_v1(p_event uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.billing_subscriptions_v2%rowtype;op public.billing_operations_v2%rowtype;o jsonb;so jsonb;se uuid;te uuid;n integer;
 facts jsonb;e uuid;pay uuid;result text;begin
 perform public.billing_guard_actor();perform 1 from public.billing_runtime_policy where id=1 for share;
 if not (select paddle_reconciliation_enabled from public.billing_runtime_policy where id=1) then return jsonb_build_object('status','disabled');end if;
 select observation into o from public.billing_paddle_event_observations where event_id=p_event;
 select * into s from public.billing_subscriptions_v2 where provider='paddle' and environment='test' and provider_subscription_ref=o-&gt;&gt;'subscriptionRef';
 perform public.billing_guard_lock(s.billing_account_id,'test');select * into s from public.billing_subscriptions_v2 where id=s.id for update;
 if exists(select 1 from public.billing_evidence_v2 where event_id=p_event and proof_schema='paddle-seat-quantity-v1') then return jsonb_build_object('status','reused');end if;
 select * into op from public.billing_operations_v2 where subscription_id=s.id and operation_kind='seat_quantity' and status not in ('completed','canceled','failed') for update;
 if op.id is null then return jsonb_build_object('status','not_applicable');end if;
 -- A verified schedule's subsequent lifecycle evidence uses the existing paired
 -- renewal/degradation pipeline. It never re-enters immediate settlement.
 if op.status='scheduled' or (o-&gt;&gt;'kind'='subscription.updated' and (o-&gt;&gt;'status'&lt;&gt;'active' or o-&gt;'scheduledChange'&lt;&gt;'null'::jsonb)) then return jsonb_build_object('status','not_applicable');end if;
 if op.status='manual_review' then return jsonb_build_object('status','manual_review');end if;
 begin
  perform public.billing_paddle_reconciliation_event_v1(p_event);
  if o-&gt;&gt;'seatQuantityOperationId' is distinct from op.operation_id::text or o ? 'planChangeOperationId' then raise exception 'PADDLE_SEAT_CORRELATION';end if;
  if o-&gt;&gt;'kind'='subscription.updated' then se:=p_event;so:=o;
  elsif o-&gt;&gt;'kind'='transaction.completed' then
   if o-&gt;&gt;'origin' is distinct from 'subscription_update' then raise exception 'PADDLE_SEAT_PAYMENT';end if;
   select count(*),min(event_id::text)::uuid into n,se from public.billing_paddle_event_observations
   where observation-&gt;&gt;'subscriptionRef'=s.provider_subscription_ref and observation-&gt;&gt;'kind'='subscription.updated'
   and observation-&gt;&gt;'status'='active' and observation-&gt;&gt;'seatQuantityOperationId'=op.operation_id::text
   and (observation-&gt;&gt;'updatedAt')::timestamptz&gt;=op.provider_requested_at;
   if n=0 then return jsonb_build_object('status','pending');end if;
   if n&lt;&gt;1 then raise exception 'PADDLE_SEAT_AMBIGUOUS_EVIDENCE';end if;
   select observation into so from public.billing_paddle_event_observations where event_id=se;
  else return jsonb_build_object('status','not_applicable');end if;
  select count(*),min(event_id::text)::uuid into n,te from public.billing_paddle_event_observations
  where observation-&gt;&gt;'subscriptionRef'=s.provider_subscription_ref and observation-&gt;&gt;'kind'='transaction.completed'
  and observation-&gt;&gt;'seatQuantityOperationId'=op.operation_id::text;
  if n&gt;1 then raise exception 'PADDLE_SEAT_AMBIGUOUS_PAYMENT';end if;
  if op.effective_timing='period_end' and n&lt;&gt;0 then raise exception 'PADDLE_SEAT_UNEXPECTED_PAYMENT';end if;
  facts:=public.billing_paddle_seat_facts_v1(op.id,se,te);
  if op.effective_timing='immediate' and te is null then
   update public.billing_operations_v2 set status='awaiting_payment',provider_applied_at=clock_timestamp(),error_code='BILLING_SEAT_QUANTITY_AWAITING_PAYMENT',updated_at=clock_timestamp() where id=op.id;
   return jsonb_build_object('status','pending');
  end if;
  e:=public.billing_paddle_seat_evidence_v1(op.id,se,te,'subscription');
  if te is not null then
   pay:=public.billing_paddle_seat_evidence_v1(op.id,se,te,'transaction');
   insert into public.billing_payment_applications_v2(provider,environment,provider_transaction_ref,billing_account_id,subscription_id,evidence_id,application_kind,operation_id)
   select 'paddle','test',provider_transaction_ref,s.billing_account_id,s.id,id,'seat_increase',op.id from public.billing_evidence_v2 where id=pay;
  end if;
  update public.billing_operations_v2 set status=case when te is null then 'scheduled' else 'awaiting_payment' end,
   provider_applied_at=clock_timestamp(),last_evidence_id=e,error_code=null,updated_at=clock_timestamp() where id=op.id;
  update public.billing_subscriptions_v2 set approved_additional_coach_seats=case when te is null then approved_additional_coach_seats else op.target_additional_seats end,
   provider_updated_at=(facts-&gt;&gt;'providerUpdatedAt')::timestamptz,latest_evidence_id=e,
   latest_snapshot_sha256=(select normalized_sha256 from public.billing_evidence_v2 where id=e),last_reconciled_at=clock_timestamp(),updated_at=clock_timestamp() where id=s.id;
  if te is not null then
   update public.billing_operations_v2 set status='completed',completed_at=clock_timestamp(),payment_confirmed_at=clock_timestamp(),updated_at=clock_timestamp() where id=op.id;
  end if;
  insert into public.billing_operation_events_v2(operation_id,event_type) values(op.id,case when te is null then 'billing.seat_quantity_scheduled' else 'billing.seat_quantity_completed' end) on conflict do nothing;
  update public.billing_webhook_events_v2 set processing_status='processed',processed_at=clock_timestamp(),last_error_code=null where id in (se,te);
  result:='applied';
 exception when raise_exception then
  if sqlerrm like 'PADDLE_SEAT_%' or sqlerrm='PADDLE_RECONCILIATION_VERIFIED_EVENT_REQUIRED' then
   update public.billing_operations_v2 set status='manual_review',error_code='BILLING_SEAT_QUANTITY_MANUAL_REVIEW',updated_at=clock_timestamp() where id=op.id;
   update public.billing_webhook_events_v2 set processing_status='manual_review',last_error_code='PADDLE_SEAT_REVIEW' where id=p_event;result:='manual_review';
  else raise;end if;
 end;
 return jsonb_build_object('status',result);
end $function$

CREATE OR REPLACE FUNCTION public.record_billing_webhook_delivery(p_environment text, p_event_name text, p_object_type text, p_object_id text, p_payload_sha256 text, p_fingerprint text, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d uuid;
begin
  if p_fingerprint&lt;&gt;encode(extensions.digest(p_environment||chr(10)||p_event_name||chr(10)||p_payload_sha256,'sha256'),'hex') then raise exception 'BILLING_RECONCILIATION_FAILED'; end if;
  insert into public.billing_provider_webhook_deliveries(provider,environment,event_name,object_type,object_id,provider_subscription_id,provider_customer_id,provider_created_at,provider_updated_at,payload_sha256,delivery_fingerprint,processing_status,normalized_payload)
    values('lemonsqueezy',p_environment,p_event_name,p_object_type,p_object_id,p_payload-&gt;&gt;'subscription_id',p_payload-&gt;&gt;'customer_id',(p_payload-&gt;&gt;'created_at')::timestamptz,(p_payload-&gt;&gt;'updated_at')::timestamptz,p_payload_sha256,p_fingerprint,'received',p_payload)
    on conflict(provider,environment,delivery_fingerprint) do nothing returning id into d;
  if d is null then select id into d from public.billing_provider_webhook_deliveries where provider='lemonsqueezy' and environment=p_environment and delivery_fingerprint=p_fingerprint; end if;
  return d;
end $function$

CREATE OR REPLACE FUNCTION public.record_verified_paddle_catalogue_v1(p_proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p jsonb; sha text; e public.billing_catalogue_evidence_v1%rowtype;
begin
  perform public.billing_catalogue_authorize_v1();
  p:=public.billing_catalogue_validate_v1(p_proof);
  sha:=encode(extensions.digest(p::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended(jsonb_build_array('catalogue-observation-v1',p-&gt;&gt;'provider',p-&gt;&gt;'environment',p-&gt;&gt;'verificationRef',p#&gt;&gt;'{catalogue,priceRef}')::text,0));
  select * into e from public.billing_catalogue_evidence_v1 where provider=p-&gt;&gt;'provider' and environment=p-&gt;&gt;'environment'
    and verification_ref=p-&gt;&gt;'verificationRef' and provider_price_ref=p#&gt;&gt;'{catalogue,priceRef}';
  if found then
    if e.normalized_sha256&lt;&gt;sha then raise exception 'BILLING_CATALOGUE_REPLAY_CONFLICT'; end if;
    return jsonb_build_object('id',e.id,'digest',e.normalized_sha256,'reused',true);
  end if;
  insert into public.billing_catalogue_evidence_v1(provider,environment,verification_ref,provider_price_ref,proof,normalized_sha256,observed_at)
    values(p-&gt;&gt;'provider',p-&gt;&gt;'environment',p-&gt;&gt;'verificationRef',p#&gt;&gt;'{catalogue,priceRef}',p,sha,(p-&gt;&gt;'observedAt')::timestamptz) returning * into e;
  return jsonb_build_object('id',e.id,'digest',e.normalized_sha256,'reused',false);
end $function$

CREATE OR REPLACE FUNCTION public.resend_workspace_team_invite(p_workspace_id uuid, p_invite_id uuid, p_base_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_invite public.workspace_member_invites%rowtype;
  v_token text;
  v_token_hash text;
  v_base_url text := nullif(regexp_replace(trim(coalesce(p_base_url, '')), '/+$', ''), '');
  v_accept_url text;
begin
  if v_actor_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  if not public.can_manage_workspace_team(p_workspace_id) then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  select *
  into v_invite
  from public.workspace_member_invites wmi
  where wmi.id = p_invite_id
    and wmi.workspace_id = p_workspace_id
  for update;

  if not found then
    perform public.workspace_team_invite_error('INVITE_NOT_FOUND');
  end if;

  if v_invite.expires_at&lt;=transaction_timestamp() or v_invite.status='expired' then
    perform public.workspace_team_invite_error('INVITE_EXPIRED');
  end if;

  if v_invite.status &lt;&gt; 'pending' then
    perform public.workspace_team_invite_error('INVITE_NOT_PENDING');
  end if;

  if exists (
    select 1
    from public.workspace_team_email_deliveries wted
    where wted.invite_id = v_invite.id
      and wted.notification_type = 'team_invite_received'
      and wted.created_at &gt; now() - interval '1 minute'
  ) then
    perform public.workspace_team_operational_error('RATE_LIMITED');
  end if;

  v_token := encode(gen_random_bytes(32), 'hex');
  v_token_hash := public.hash_workspace_team_invite_token(v_token);

  update public.workspace_member_invites
  set token_hash = v_token_hash,
      status = 'pending',
      expires_at = now() + interval '14 days'
  where id = v_invite.id
  returning * into v_invite;

  v_accept_url := coalesce(v_base_url, '') || '/team-invites/' || v_token;

  perform public.set_workspace_team_invite_notification_route(
    v_invite.id,
    v_token
  );

  perform public.queue_workspace_team_email(
    p_workspace_id,
    v_invite.id,
    v_invite.email,
    'team_invite_received',
    'workspace_team_invite',
    jsonb_build_object(
      'expiresAt', v_invite.expires_at,
      'mustUseEmail', v_invite.email
    ),
    'workspace-team-invite:' || v_invite.id::text || ':resent:' || extract(epoch from v_invite.updated_at)::text
  );

  perform public.record_workspace_team_audit_event(
    p_workspace_id,
    v_actor_user_id,
    'team.invite_resent',
    'workspace_member_invite',
    v_invite.id,
    v_invite.email,
    jsonb_build_object('expiresAt', v_invite.expires_at, 'emailQueued', true)
  );

  return jsonb_build_object(
    'inviteId', v_invite.id,
    'workspaceId', p_workspace_id,
    'email', v_invite.email,
    'status', v_invite.status,
    'expiresAt', v_invite.expires_at,
    'acceptUrl', v_accept_url
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_account_capacity(p_billing_account_id uuid, p_dimension text, p_quantity integer, p_idempotency_key text, p_subject_type text, p_subject_key text, p_workspace_id uuid DEFAULT NULL::uuid, p_source text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare a public.billing_accounts%rowtype; r public.account_capacity_reservations%rowtype; d jsonb; s jsonb;
  t timestamptz := transaction_timestamp(); h text; canonical text; delta bigint; reason text;
begin
  perform public.validate_account_capacity_metadata(p_source,p_metadata);
  if p_dimension is null or p_dimension not in ('counted_clients','coach_seats','active_workspaces','published_packages') or p_quantity is null or p_quantity&lt;=0
    or p_idempotency_key is null or btrim(p_idempotency_key)='' or length(p_idempotency_key)&gt;200
    or p_subject_type is null or p_subject_type not in ('user','client','email','workspace','package','operation') or p_subject_key is null
    or not (p_subject_key ~ ('^' || p_subject_type || ':' || case when p_subject_type='email' then '[0-9a-f]{64}' else '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' end || '$'))
    or (p_subject_type &lt;&gt; 'operation' and p_quantity&lt;&gt;1)
    or (p_dimension='counted_clients' and p_subject_type not in ('user','client','email','operation'))
    or (p_dimension='coach_seats' and p_subject_type not in ('user','email','operation'))
    or (p_dimension='active_workspaces' and p_subject_type not in ('workspace','operation'))
    or (p_dimension='published_packages' and p_subject_type not in ('package','operation')) then raise exception 'Invalid reservation.' using errcode='22023'; end if;
  select * into a from public.billing_accounts where id=p_billing_account_id for update;
  if not found then raise exception 'Unknown billing account.' using errcode='22023'; end if;
  -- VOLATILE statements after the lock see prior writers under READ COMMITTED.
  select * into r from public.account_capacity_reservations where billing_account_id=a.id and dimension=p_dimension and idempotency_key=p_idempotency_key;
  if found then
    if (r.quantity,r.subject_type,r.subject_key,r.workspace_id) is distinct from (p_quantity,p_subject_type,p_subject_key,p_workspace_id) then raise exception 'Idempotency payload conflict.' using errcode='22023'; end if;
    return jsonb_build_object('granted',true,'reservationId',r.id,'status',r.status,'expiresAt',r.expires_at);
  end if;
  h := encode(extensions.digest(p_idempotency_key,'sha256'),'hex');
  select metadata-&gt;&gt;'reasonCode' into reason from public.account_capacity_events where billing_account_id=a.id and dimension=p_dimension and event_type='capacity.reservation_denied' and metadata-&gt;&gt;'idempotencyHash'=h;
  if found then return jsonb_build_object('granted',false,'reservationId',null,'reasonCode',reason); end if;
  if p_expires_at is null or p_expires_at&lt;=t or p_expires_at&gt;t+interval '5 minutes' then raise exception 'Reservation TTL must be positive and at most five minutes.' using errcode='22023'; end if;
  if p_workspace_id is not null and not exists(select 1 from public.workspaces where id=p_workspace_id and owner_user_id=a.owner_user_id) then raise exception 'Workspace is outside account.' using errcode='22023'; end if;
  canonical := public.account_capacity_subject_key(p_dimension,p_subject_key);
  s := public.resolve_account_capacity(a.owner_user_id,a.id);
  select value into d from jsonb_array_elements(s-&gt;'dimensions') where value-&gt;&gt;'key'=p_dimension;
  -- Match aliases to the one requested identity, rather than re-hashing every
  -- auth user for every existing email reservation.
  delta := greatest(p_quantity-coalesce((select max(held.quantity) from public.account_capacity_reservations held
    where held.billing_account_id=a.id and held.dimension=p_dimension and held.status='active' and held.expires_at&gt;t
      and (held.subject_key=canonical or (left(canonical,5)='user:' and (
        held.subject_key=(select public.account_capacity_email_key(u.email) from auth.users u
          where u.id=case when left(canonical,5)='user:' then substring(canonical from 6)::uuid end)
        or (p_dimension='counted_clients' and held.subject_type='client' and exists(
          select 1 from public.clients c where 'client:' || c.id=held.subject_key and 'user:' || c.user_id=canonical))
      )))),0),0);
  if exists(select 1 from public.account_capacity_subjects(a.owner_user_id,t) x where x.dimension=p_dimension and x.subject_key=canonical) then delta:=0; end if;
  if p_dimension='coach_seats' then d:=jsonb_set(d,'{limit}',to_jsonb(least((d-&gt;&gt;'limit')::integer,public.billing_seat_effective_limit(a.id,true)))); end if;
  if d-&gt;&gt;'state'='unavailable' or ((d-&gt;&gt;'limit')::integer is not null and (d-&gt;&gt;'committed')::bigint+delta&gt;(d-&gt;&gt;'limit')::integer) then
    reason := case when d-&gt;&gt;'state'='unavailable' then 'capacity_unavailable' else 'capacity_would_exceed' end;
    insert into public.account_capacity_events(billing_account_id,dimension,event_type,quantity,source,metadata)
      values(a.id,p_dimension,'capacity.reservation_denied',p_quantity,p_source,p_metadata || jsonb_build_object('idempotencyHash',h,'reasonCode',reason));
    return jsonb_build_object('granted',false,'reservationId',null,'reasonCode',reason);
  end if;
  insert into public.account_capacity_reservations(billing_account_id,dimension,quantity,idempotency_key,subject_type,subject_key,workspace_id,source,expires_at,metadata,created_by_user_id,admission_transaction_id)
    values(a.id,p_dimension,p_quantity,p_idempotency_key,p_subject_type,p_subject_key,p_workspace_id,p_source,p_expires_at,p_metadata,auth.uid(),case when p_source='domain.admission' then pg_current_xact_id() end) returning * into r;
  insert into public.account_capacity_events(billing_account_id,reservation_id,dimension,event_type,quantity,source,metadata)
    values(a.id,r.id,p_dimension,'capacity.reservation_created',p_quantity,p_source,p_metadata);
  return jsonb_build_object('granted',true,'reservationId',r.id,'status',r.status,'expiresAt',r.expires_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_account_commercial_access(p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a uuid; s jsonb; m text; reason text; until_at timestamptz; actions jsonb;
begin
  select id into a from public.billing_accounts where owner_user_id=p_owner;
  s:=public.resolve_account_entitlements(a)-&gt;'subscription';
  m:=s-&gt;&gt;'accessMode'; reason:=s-&gt;&gt;'effectiveStatus';
  if m is null or m not in ('onboarding','full','existing_delivery_only','read_only','none')
    or (m='onboarding' and exists(select 1 from public.workspaces where owner_user_id=p_owner)) then
    m:='read_only'; reason:='owner_recovery_required';
  end if;
  until_at:=case reason when 'trialing' then (s-&gt;&gt;'trialEndsAt')::timestamptz
    when 'trial_recovery' then (s-&gt;&gt;'trialRecoveryEndsAt')::timestamptz
    else (s-&gt;&gt;'currentPeriodEndsAt')::timestamptz end;
  select jsonb_object_agg(k,public.is_commercial_action_allowed(m,k)) into actions
  from unnest(array['billing_manage','account_security','data_export','remediation','workspace_read','delivery_write','business_configuration_write','acquisition_write','capacity_growth','client_self_service','client_coached_read','client_coached_write']) k;
  return jsonb_build_object('schemaVersion',1,'accessMode',m,'reason',reason,'effectiveUntil',until_at,
    'actions',actions,'canManageBilling',true,'recoveryRequired',m&lt;&gt;'full' or reason='past_due',
    'recoveryAction',case when reason='owner_recovery_required' then 'contact_support' when m='full' and reason&lt;&gt;'past_due' then 'none' when m='onboarding' then 'start_trial' else 'review_billing' end,
    'recoveryPath',case when reason='owner_recovery_required' then '/contact' else '/pt-hub/settings/billing' end,'computedAt',transaction_timestamp());
end $function$

CREATE OR REPLACE FUNCTION public.resolve_account_entitlements(p_billing_account_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.account_subscriptions%rowtype; p public.commercial_plan_versions%rowtype; t public.commercial_trial_policy_versions%rowtype;
  v_status text; v_mode text; v_label text; v_targets jsonb := '[]'; v_enabled jsonb := '[]';
begin
  select * into s from public.account_subscriptions where billing_account_id = p_billing_account_id and status&lt;&gt;'superseded'
    order by (status in ('trialing','trial_recovery','active','past_due','grace','restricted')) desc,created_at desc,id desc limit 1;
  select * into p from public.commercial_plan_versions where id = s.plan_version_id;
  -- Read-time target resolution avoids dependence on a punctual renewal webhook.
  if s.subscription_kind='paid' and not s.cancel_at_period_end and s.status not in ('canceled','superseded') then
    select cp.* into p from public.commercial_plan_versions cp where cp.id=coalesce((
      select o.target_plan_version_id from public.billing_plan_change_operations o join public.billing_provider_subscriptions b on b.id=o.billing_provider_subscription_id
      where o.source_account_subscription_id=s.id and o.status='scheduled' and o.effective_timing='period_end'
        and o.effective_at&lt;=now() and o.provider_applied_at is not null and b.variant_mapping_id=o.target_variant_mapping_id
        and not b.provider_cancelled and b.reconciliation_status='processed'),coalesce(public.billing_paddle_scheduled_plan_v1(s.id,now()),s.plan_version_id));
  end if;
  select * into t from public.commercial_trial_policy_versions where id = s.trial_policy_version_id;
  v_status := public.effective_account_subscription_status(s.subscription_kind,s.status,s.trial_ends_at,s.trial_recovery_ends_at);
  if s.subscription_kind='paid' and s.cancel_at_period_end and s.current_period_ends_at&lt;=now() then v_status:='expired'; end if;
  v_mode := public.account_subscription_access_mode(v_status);
  v_label := case v_status when 'no_subscription' then 'Trial not started' when 'trialing' then 'Growth trial'
    when 'trial_recovery' then 'Trial ended' when 'expired' then case when s.subscription_kind = 'trial' then 'Trial expired' else 'Subscription expired' end
    when 'restricted' then 'Restricted' when 'canceled' then 'Canceled' when 'grace' then 'Grace period'
    when 'past_due' then 'Past due' else case when s.subscription_kind = 'complimentary' then 'Complimentary beta access' else p.display_name end end;
  if s.id is not null then
    select coalesce(jsonb_agg(feature_key order by feature_key),'[]') into v_targets from public.commercial_plan_feature_entitlements where plan_version_id = p.id;
    select coalesce(jsonb_agg(f.feature_key order by f.feature_key),'[]') into v_enabled
    from public.commercial_features f
    where f.readiness_status = 'COMMERCIALLY_SALEABLE'
      and (exists(select 1 from public.commercial_plan_feature_entitlements e where e.plan_version_id = p.id and e.feature_key = f.feature_key)
        or exists(select 1 from public.account_feature_entitlement_overrides o where o.billing_account_id = p_billing_account_id and o.feature_key = f.feature_key
          and o.effect = 'enable' and o.starts_at &lt;= now() and (o.expires_at is null or o.expires_at &gt; now()) and o.revoked_at is null))
      and not exists(select 1 from public.account_feature_entitlement_overrides o where o.billing_account_id = p_billing_account_id and o.feature_key = f.feature_key
        and o.effect = 'disable' and o.starts_at &lt;= now() and (o.expires_at is null or o.expires_at &gt; now()) and o.revoked_at is null);
  end if;
  return jsonb_build_object('schemaVersion',1,
    'subscription',jsonb_build_object('id',s.id,'kind',s.subscription_kind,'storedStatus',coalesce(s.status,'no_subscription'),
      'effectiveStatus',v_status,'accessMode',v_mode,'accessLabel',v_label,'planKey',p.plan_key,'planVersion',p.version,'planDisplayName',p.display_name,
      'trialStartedAt',s.trial_started_at,'trialEndsAt',s.trial_ends_at,'trialRecoveryEndsAt',s.trial_recovery_ends_at,
      'currentPeriodStartedAt',s.current_period_started_at,'currentPeriodEndsAt',s.current_period_ends_at,'cancelAtPeriodEnd',coalesce(s.cancel_at_period_end,false)),
    'limits',jsonb_build_object(
      'countedClients',case when s.subscription_kind = 'trial' then t.max_counted_clients else p.max_counted_clients end,
      'includedCoachSeats',case when s.subscription_kind = 'trial' then t.included_coach_seats else p.included_coach_seats end,
      'maxCoachSeats',case when s.subscription_kind = 'trial' then t.max_coach_seats else p.max_coach_seats end,
      'activeWorkspaces',case when s.subscription_kind = 'trial' then t.max_active_workspaces else p.max_active_workspaces end,
      'publishedPackages',case when s.subscription_kind = 'trial' then t.max_published_packages else p.max_published_packages end),
    'targetFeatureKeys',v_targets,'enabledFeatureKeys',v_enabled,'computedAt',now());
end;
$function$

CREATE OR REPLACE FUNCTION public.retire_paddle_catalogue_mapping_v1(p_mapping_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m public.billing_price_mappings%rowtype;
begin
  perform public.billing_catalogue_authorize_v1();
  perform pg_advisory_xact_lock(hashtextextended('paddle-catalogue-publication-v1:test',0));
  select * into m from public.billing_price_mappings where id=p_mapping_id for update;
  if not found or m.catalogue_evidence_id is null or m.environment&lt;&gt;'test' then raise exception 'BILLING_CATALOGUE_EVIDENCE_REQUIRED'; end if;
  if m.status&lt;&gt;'retired' then update public.billing_price_mappings set status='retired',retired_at=clock_timestamp(),updated_at=clock_timestamp() where id=m.id; end if;
  return m.id;
end $function$

CREATE OR REPLACE FUNCTION public.review_checkin(p_checkin_id uuid, p_pt_feedback text DEFAULT NULL::text, p_mark_reviewed boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_id uuid;
  v_submitted_at timestamptz;
  v_feedback text := nullif(trim(p_pt_feedback), '');
begin
  select ci.client_id, ci.submitted_at
  into v_client_id, v_submitted_at
  from public.checkins ci
  where ci.id = p_checkin_id;

  if v_client_id is null then
    raise exception 'Check-in not found';
  end if;

  if not public.can_write_client_delivery(v_client_id) then
    raise exception 'Not authorized';
  end if;

  if v_submitted_at is null then
    raise exception 'Check-in must be submitted before review';
  end if;

  if p_mark_reviewed and v_feedback is null then
    raise exception 'Review notes are required before marking a check-in reviewed';
  end if;

  update public.checkins
  set pt_feedback = v_feedback,
      reviewed_at = case
        when p_mark_reviewed then coalesce(reviewed_at, now())
        else reviewed_at
      end,
      reviewed_by_user_id = case
        when p_mark_reviewed then coalesce(reviewed_by_user_id, auth.uid())
        else reviewed_by_user_id
      end
  where id = p_checkin_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.review_workspace_client_onboarding(p_client_id uuid, p_coach_review_notes text DEFAULT NULL::text)
 RETURNS public.workspace_client_onboardings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.workspace_client_onboardings;
  v_next_status public.onboarding_status;
begin
  if p_client_id is null then
    raise exception 'Client is required';
  end if;

  select *
  into v_row
  from public.workspace_client_onboardings wco
  where wco.client_id = p_client_id
  limit 1
  for update;

  if v_row.id is null then
    raise exception 'Onboarding row not found';
  end if;

  if not public.is_pt_workspace_member(v_row.workspace_id) then
    raise exception 'Not authorized';
  end if;

  v_next_status :=
    case
      when v_row.completed_at is not null then 'completed'::public.onboarding_status
      else 'submitted'::public.onboarding_status
    end;

  update public.workspace_client_onboardings
  set
    coach_review_notes = coalesce(p_coach_review_notes, coach_review_notes),
    reviewed_at = now(),
    reviewed_by_user_id = auth.uid(),
    status = v_next_status,
    activated_at = case when v_next_status = 'completed' then activated_at else null end
  where id = v_row.id
  returning *
  into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_workspace_team_invite(p_workspace_id uuid, p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_invite public.workspace_member_invites%rowtype;
begin
  if v_actor_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  if not public.can_manage_workspace_team(p_workspace_id) then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  select *
  into v_invite
  from public.workspace_member_invites wmi
  where wmi.id = p_invite_id
    and wmi.workspace_id = p_workspace_id
  for update;

  if not found then
    perform public.workspace_team_invite_error('INVITE_NOT_FOUND');
  end if;

  if v_invite.status = 'revoked' then
    return jsonb_build_object(
      'inviteId', v_invite.id,
      'workspaceId', p_workspace_id,
      'status', v_invite.status
    );
  end if;

  if v_invite.status &lt;&gt; 'pending' then
    perform public.workspace_team_invite_error('INVITE_NOT_PENDING');
  end if;

  update public.workspace_member_invites
  set status = 'revoked'
  where id = v_invite.id
  returning * into v_invite;

  update public.workspace_team_email_deliveries
  set status = 'cancelled',
      updated_at = now()
  where invite_id = v_invite.id
    and status in ('queued', 'sending');

  perform public.record_workspace_team_audit_event(
    p_workspace_id,
    v_actor_user_id,
    'team.invite_revoked',
    'workspace_member_invite',
    v_invite.id,
    v_invite.email,
    '{}'::jsonb
  );

  return jsonb_build_object(
    'inviteId', v_invite.id,
    'workspaceId', p_workspace_id,
    'status', v_invite.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.save_client_program_day_override(p_client_program_id uuid, p_override_date date, p_workout_template_id uuid, p_is_rest boolean DEFAULT false, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_client_id uuid;
  v_workspace_id uuid;
  v_program_template_id uuid;
  v_program_start_date date;
  v_template_workspace_id uuid;
  v_assigned_workout_id uuid;
  v_override_id uuid;
  v_program_day_index integer;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_client_program_id is null or p_override_date is null then
    raise exception 'client_program_id and override_date are required';
  end if;

  if coalesce(p_is_rest, false) = false and p_workout_template_id is null then
    raise exception 'workout_template_id is required unless override is a rest day';
  end if;

  select cp.client_id, c.workspace_id, cp.program_template_id, cp.start_date
  into v_client_id, v_workspace_id, v_program_template_id, v_program_start_date
  from public.client_programs cp
  join public.clients c on c.id = cp.client_id
  where cp.id = p_client_program_id
    and cp.is_active = true;

  if v_client_id is null then
    raise exception 'Active client program not found';
  end if;

  if not public.can_write_client_delivery(v_client_id) then
    raise exception 'Not authorized';
  end if;

  if p_override_date &lt; v_program_start_date then
    raise exception 'Override date is before the active program start date';
  end if;

  if coalesce(p_is_rest, false) = false then
    select wt.workspace_id
    into v_template_workspace_id
    from public.workout_templates wt
    where wt.id = p_workout_template_id;

    if v_template_workspace_id is null then
      raise exception 'Workout template not found';
    end if;

    if v_template_workspace_id &lt;&gt; v_workspace_id then
      raise exception 'Template not in client workspace';
    end if;
  end if;

  if exists (
    select 1
    from public.assigned_workouts aw
    where aw.client_id = v_client_id
      and aw.scheduled_date = p_override_date
      and aw.status = 'completed'
  ) then
    raise exception 'Cannot override a completed workout day';
  end if;

  insert into public.client_program_overrides (
    client_program_id,
    override_date,
    workout_template_id,
    is_rest,
    notes
  )
  values (
    p_client_program_id,
    p_override_date,
    case when coalesce(p_is_rest, false) then null else p_workout_template_id end,
    coalesce(p_is_rest, false),
    nullif(btrim(p_notes), '')
  )
  on conflict (client_program_id, override_date)
  do update set
    workout_template_id = excluded.workout_template_id,
    is_rest = excluded.is_rest,
    notes = excluded.notes
  returning id into v_override_id;

  v_program_day_index := p_override_date - v_program_start_date;

  select aw.id
  into v_assigned_workout_id
  from public.assigned_workouts aw
  where aw.client_id = v_client_id
    and aw.scheduled_date = p_override_date
    and aw.status &lt;&gt; 'completed'
  order by
    case when aw.program_id = v_program_template_id then 0 else 1 end,
    aw.created_at asc
  limit 1;

  if v_assigned_workout_id is null then
    insert into public.assigned_workouts (
      client_id,
      workout_template_id,
      scheduled_date,
      status,
      day_type,
      program_id,
      program_day_index,
      coach_note
    )
    values (
      v_client_id,
      case when coalesce(p_is_rest, false) then null else p_workout_template_id end,
      p_override_date,
      'planned',
      case when coalesce(p_is_rest, false) then 'rest' else 'workout' end,
      v_program_template_id,
      v_program_day_index,
      nullif(btrim(p_notes), '')
    )
    returning id into v_assigned_workout_id;
  else
    update public.assigned_workouts
    set workout_template_id = case when coalesce(p_is_rest, false) then null else p_workout_template_id end,
        status = 'planned',
        completed_at = null,
        day_type = case when coalesce(p_is_rest, false) then 'rest' else 'workout' end,
        program_id = v_program_template_id,
        program_day_index = v_program_day_index,
        coach_note = nullif(btrim(p_notes), '')
    where id = v_assigned_workout_id;
  end if;

  delete from public.assigned_workouts aw
  where aw.client_id = v_client_id
    and aw.scheduled_date = p_override_date
    and aw.status &lt;&gt; 'completed'
    and aw.id &lt;&gt; v_assigned_workout_id;

  perform public.materialize_assigned_workout_exercises(v_assigned_workout_id);

  return v_assigned_workout_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_conversation_message(p_conversation_id uuid, p_sender_user_id uuid, p_sender_role text, p_sender_name text, p_body text, p_unread boolean DEFAULT false)
 RETURNS TABLE(id uuid, conversation_id uuid, sender_user_id uuid, sender_role text, sender_name text, body text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_body text := trim(coalesce(p_body, ''));
  v_user_id uuid := (select auth.uid());
  v_message public.messages%rowtype;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if p_sender_user_id is distinct from v_user_id then
    raise exception 'Not authorized';
  end if;

  if v_body = '' then
    raise exception 'Message body is required';
  end if;

  if p_sender_role = 'pt' then
    if not public.can_access_conversation(p_conversation_id, 'clients.message') then
      raise exception 'Not authorized';
    end if;
  elsif p_sender_role = 'client' then
    if not public.can_access_conversation(p_conversation_id, 'clients.view') then
      raise exception 'Not authorized';
    end if;
  else
    raise exception 'Invalid sender role';
  end if;

  insert into public.messages (
    conversation_id,
    sender_user_id,
    sender_role,
    sender_name,
    body,
    preview,
    unread
  )
  values (
    p_conversation_id,
    p_sender_user_id,
    p_sender_role,
    p_sender_name,
    v_body,
    left(v_body, 140),
    coalesce(p_unread, false)
  )
  returning *
  into v_message;

  return query
  select
    v_message.id,
    v_message.conversation_id,
    v_message.sender_user_id,
    v_message.sender_role,
    v_message.sender_name,
    v_message.body,
    v_message.created_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_requested_paid_plan(p_plan_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_user uuid := auth.uid(); v_account uuid;
begin
  if v_user is null or not exists(select 1 from public.pt_profiles where user_id = v_user) then
    raise exception 'PT authentication required.' using errcode = '42501';
  end if;
  if p_plan_key is null or p_plan_key not in ('launch','growth','scale') then raise exception 'Invalid requested plan.' using errcode = '22023'; end if;
  v_account := public.ensure_commercial_billing_account(v_user,'signup');
  update public.billing_accounts set requested_plan_key = p_plan_key,requested_plan_source = 'signup_rpc',requested_plan_updated_at = now()
  where id = v_account and requested_plan_key is distinct from p_plan_key;
  return jsonb_build_object('billingAccountId',v_account,'requestedPaidPlanKey',p_plan_key);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_pt_profile_publication(p_publish boolean)
 RETURNS TABLE(is_published boolean, published_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_profile public.pt_hub_profiles%rowtype;
  v_settings public.pt_hub_settings%rowtype;
  v_missing text[] := array[]::text[];
  v_slug text;
  v_reserved_slugs constant text[] := array[
    'admin',
    'api',
    'app',
    'login',
    'signup',
    'settings',
    'billing',
    'support',
    'help',
    'coach',
    'coaches',
    'pt',
    'profile',
    'marketplace',
    'dashboard',
    'workspaces',
    'clients',
    'messages',
    'terms',
    'privacy'
  ];
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  select *
  into v_profile
  from public.pt_hub_profiles
  where user_id = v_user_id;

  if not found then
    raise exception 'PT Hub profile not found';
  end if;

  select *
  into v_settings
  from public.pt_hub_settings
  where user_id = v_user_id;

  if p_publish then
    v_slug := btrim(coalesce(v_profile.slug, ''));

    if v_slug = '' then
      v_missing := array_append(v_missing, 'Public URL slug');
    elsif length(v_slug) &lt; 3
       or length(v_slug) &gt; 40
       or v_slug &lt;&gt; lower(v_slug)
       or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
       or v_slug = any (v_reserved_slugs) then
      v_missing := array_append(v_missing, 'Valid public URL slug');
    elsif exists (
      select 1
      from public.pt_hub_profiles profile
      where lower(profile.slug) = v_slug
        and profile.user_id &lt;&gt; v_user_id
    ) then
      v_missing := array_append(v_missing, 'Public URL slug is already taken');
    end if;

    if coalesce(btrim(v_profile.display_name), '') = '' then
      v_missing := array_append(v_missing, 'Display name');
    end if;

    if coalesce(btrim(v_profile.headline), '') = '' then
      v_missing := array_append(v_missing, 'Headline');
    end if;

    if coalesce(btrim(v_profile.short_bio), '') = '' then
      v_missing := array_append(v_missing, 'Bio');
    end if;

    if coalesce(array_length(v_profile.specialties, 1), 0) = 0 then
      v_missing := array_append(v_missing, 'Specialties');
    end if;

    if coalesce(array_length(v_profile.certifications, 1), 0) = 0 then
      v_missing := array_append(v_missing, 'Certifications');
    end if;

    if coalesce(btrim(v_profile.coaching_style), '') = '' then
      v_missing := array_append(v_missing, 'Coaching style');
    end if;

    if coalesce(btrim(v_profile.profile_photo_url), '') = '' then
      v_missing := array_append(v_missing, 'Profile photo');
    end if;

    if coalesce(btrim(v_profile.banner_image_url), '') = '' then
      v_missing := array_append(v_missing, 'Banner image');
    end if;

    if not exists (
      select 1
      from jsonb_array_elements(coalesce(v_profile.social_links, '[]'::jsonb)) as item
      where coalesce(btrim(item -&gt;&gt; 'url'), '') &lt;&gt; ''
    ) then
      v_missing := array_append(v_missing, 'At least one social link');
    end if;

    if coalesce(btrim(v_settings.contact_email), '') = ''
       and coalesce(btrim(v_settings.support_email), '') = '' then
      v_missing := array_append(v_missing, 'Public contact path');
    end if;

    if coalesce(array_length(v_missing, 1), 0) &gt; 0 then
      raise exception
        using
          message = 'Profile is not ready to publish',
          detail = array_to_string(v_missing, ', ');
    end if;

    update public.pt_hub_profiles profile
    set
      is_published = true,
      published_at = coalesce(profile.published_at, now())
    where profile.user_id = v_user_id;
  else
    update public.pt_hub_profiles profile
    set
      is_published = false,
      published_at = null
    where profile.user_id = v_user_id;
  end if;

  return query
  select profile.is_published, profile.published_at
  from public.pt_hub_profiles profile
  where profile.user_id = v_user_id;
end;
$function$

