CREATE OR REPLACE FUNCTION public.start_account_trial_for_owner(p_owner_user_id uuid, p_source text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_account uuid; v_policy public.commercial_trial_policy_versions%rowtype; v_start timestamptz := transaction_timestamp();
begin
  if p_owner_user_id is null then return; end if;
  if p_source not in ('first_workspace','workspace_transfer') then raise exception 'Invalid trial source.'; end if;
  v_account := public.ensure_commercial_billing_account(p_owner_user_id,p_source);
  -- All first-access writers take the same lock. A waiting writer observes the
  -- committed history before deciding; unique indexes provide a second guard.
  perform 1 from public.billing_accounts where id = v_account for update;
  if exists(select 1 from public.account_subscriptions where billing_account_id = v_account) then return; end if;
  select * into strict v_policy from public.commercial_trial_policy_versions where version = 1 and status = 'active';
  insert into public.account_subscriptions(billing_account_id,plan_version_id,trial_policy_version_id,subscription_kind,status,source,
    trial_started_at,trial_ends_at,trial_recovery_ends_at)
  values(v_account,v_policy.feature_plan_version_id,v_policy.id,'trial','trialing',p_source,
    v_start,v_start + make_interval(days =&gt; v_policy.duration_days),v_start + make_interval(days =&gt; v_policy.duration_days + v_policy.recovery_days));
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_public_pt_application(p_slug text, p_full_name text, p_phone text, p_goal_summary text, p_training_experience text, p_package_interest_id uuid DEFAULT NULL::uuid, p_package_interest_label_snapshot text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_profile record;
  v_lead_id uuid;
  v_slug text;
  v_applicant_user_id uuid;
  v_email text;
  v_full_name text;
  v_package_interest_label text;
  v_selected_package record;
  v_latest_lead record;
begin
  v_applicant_user_id := auth.uid();
  if v_applicant_user_id is null then
    raise exception 'Sign in is required before applying.';
  end if;

  v_slug := lower(btrim(coalesce(p_slug, '')));
  if v_slug = '' then
    raise exception 'Profile slug is required';
  end if;

  select
    profile.user_id,
    profile.slug
  into v_profile
  from public.pt_hub_profiles profile
  join public.pt_hub_settings settings
    on settings.user_id = profile.user_id
  where lower(profile.slug) = v_slug
    and profile.is_published = true
    and settings.profile_visibility = 'listed'
  limit 1;

  if not found then
    raise exception 'Published profile not found';
  end if;

  if v_profile.user_id = v_applicant_user_id then
    raise exception 'You cannot apply to your own public profile.';
  end if;

  if not public.is_coach_accepting_applications(v_profile.user_id) then
    raise exception 'PUBLIC_COACH_NOT_ACCEPTING_APPLICATIONS' using errcode='42501',detail='{"code":"PUBLIC_COACH_NOT_ACCEPTING_APPLICATIONS","audience":"public"}';
  end if;

  v_email := lower(nullif(btrim(coalesce(auth.jwt() -&gt;&gt; 'email', '')), ''));
  if v_email is null then
    raise exception 'Your account email is missing.';
  end if;

  v_full_name := coalesce(
    nullif(btrim(coalesce(p_full_name, '')), ''),
    nullif(
      btrim(
        coalesce(
          auth.jwt() -&gt; 'user_metadata' -&gt;&gt; 'full_name',
          auth.jwt() -&gt; 'user_metadata' -&gt;&gt; 'name',
          ''
        )
      ),
      ''
    )
  );

  if v_full_name is null then
    raise exception 'Full name is required';
  end if;

  if coalesce(btrim(p_goal_summary), '') = '' then
    raise exception 'Goal summary is required';
  end if;

  perform public.enforce_rate_limit(
    'public_pt_application_burst',
    1,
    300,
    v_applicant_user_id,
    null,
    public.hash_rate_limit_key(v_slug),
    'You recently submitted an application. Please wait a few minutes before trying again.'
  );

  perform public.enforce_rate_limit(
    'public_pt_application_hourly',
    3,
    3600,
    v_applicant_user_id,
    null,
    null,
    'Too many applications were submitted from this account recently. Please try again later.'
  );

  if p_package_interest_id is not null then
    select
      pkg.id,
      pkg.title
    into v_selected_package
    from public.pt_packages pkg
    where pkg.id = p_package_interest_id
      and pkg.pt_user_id = v_profile.user_id
      and pkg.status = 'active'
      and pkg.is_public = true
    limit 1;

    if not found then
      raise exception 'Selected package is no longer available.';
    end if;

    v_package_interest_label := nullif(
      btrim(coalesce(v_selected_package.title, '')),
      ''
    );

    if v_package_interest_label is null then
      raise exception 'Selected package is no longer available.';
    end if;
  else
    v_package_interest_label := nullif(
      btrim(coalesce(p_package_interest_label_snapshot, '')),
      ''
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    hashtextextended(
      format(
        'public_pt_application:%s:%s',
        v_profile.user_id::text,
        v_applicant_user_id::text
      ),
      0
    )
  );

  select
    lead.id,
    lead.status
  into v_latest_lead
  from public.pt_hub_leads lead
  where lead.user_id = v_profile.user_id
    and lead.applicant_user_id = v_applicant_user_id
  order by lead.submitted_at desc nulls last, lead.id desc
  limit 1
  for update;

  if v_latest_lead.id is not null
     and coalesce(v_latest_lead.status, 'new') &lt;&gt; 'declined' then
    raise exception 'You already have an application with this coach. You can apply again only if they decline it.';
  end if;

  insert into public.pt_hub_leads (
    user_id,
    applicant_user_id,
    full_name,
    email,
    phone,
    goal_summary,
    training_experience,
    budget_interest,
    package_interest,
    package_interest_id,
    package_interest_label_snapshot,
    status,
    submitted_at,
    source,
    source_slug
  )
  values (
    v_profile.user_id,
    v_applicant_user_id,
    v_full_name,
    v_email,
    nullif(btrim(coalesce(p_phone, '')), ''),
    btrim(p_goal_summary),
    nullif(btrim(coalesce(p_training_experience, '')), ''),
    null,
    v_package_interest_label,
    p_package_interest_id,
    v_package_interest_label,
    'new',
    now(),
    'public_profile',
    v_profile.slug
  )
  returning id into v_lead_id;

  return v_lead_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_support_request(p_request_id uuid, p_name text, p_email text, p_workspace_name text, p_topic text, p_message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_name text := btrim(coalesce(p_name, ''));
  v_workspace text := btrim(coalesce(p_workspace_name, ''));
  v_message text := btrim(coalesce(p_message, ''));
  v_existing public.support_requests;
begin
  if p_request_id is null
     or char_length(v_name) not between 1 and 120
     or char_length(v_email) &gt; 254
     or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or char_length(v_workspace) &gt; 160
     or coalesce(p_topic, '') not in ('account', 'billing', 'technical', 'other')
     or char_length(v_message) not between 20 and 5000 then
    raise exception 'Please check the form details and try again.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('support-request:' || p_request_id::text, 0));
  select * into v_existing from public.support_requests where id = p_request_id;
  if found then
    if v_existing.email = v_email and v_existing.name = v_name
       and v_existing.workspace_name = v_workspace and v_existing.topic = p_topic
       and v_existing.message = v_message
       and v_existing.user_id is not distinct from auth.uid() then
      return p_request_id;
    end if;
    raise exception 'Please start a new support request.' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('support-email:' || v_email, 0));
  if auth.uid() is not null then
    perform pg_advisory_xact_lock(hashtextextended('support-user:' || auth.uid()::text, 0));
  end if;
  perform public.enforce_rate_limit(
    'support-request', 5, 3600, auth.uid(), public.hash_rate_limit_key(v_email), null,
    'Too many support requests. Please try again in an hour.'
  );

  insert into public.support_requests (id, user_id, name, email, workspace_name, topic, message)
  values (p_request_id, auth.uid(), v_name, v_email, v_workspace, p_topic, v_message);
  return p_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_workspace_client_onboarding(p_client_id uuid)
 RETURNS public.workspace_client_onboardings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row public.workspace_client_onboardings;
  v_baseline_id uuid;
  v_client public.clients%rowtype;
  v_full_name text;
  v_phone text;
  v_sex text;
  v_dob date;
  v_height numeric;
  v_weight numeric;
begin
  v_row := public.ensure_workspace_client_onboarding(p_client_id, 'direct_invite');

  select *
  into v_client
  from public.clients c
  where c.id = p_client_id
  limit 1;

  if v_row.status = 'completed' then
    raise exception 'Onboarding is already completed';
  end if;

  v_full_name := coalesce(
    nullif(trim(v_client.full_name), ''),
    nullif(trim(v_client.display_name), ''),
    nullif(trim(v_row.basics -&gt;&gt; 'display_name'), '')
  );
  v_phone := coalesce(
    nullif(trim(v_client.phone), ''),
    nullif(trim(v_row.basics -&gt;&gt; 'phone'), '')
  );
  v_sex := coalesce(
    nullif(trim(v_client.sex), ''),
    nullif(trim(v_client.gender), ''),
    nullif(trim(v_row.basics -&gt;&gt; 'gender'), '')
  );
  v_dob := coalesce(
    v_client.date_of_birth,
    v_client.dob,
    nullif(v_row.basics -&gt;&gt; 'date_of_birth', '')::date
  );
  v_height := coalesce(
    v_client.height_value,
    v_client.height_cm,
    nullif(v_row.basics -&gt;&gt; 'height_value', '')::numeric
  );
  v_weight := coalesce(
    v_client.weight_value_current,
    v_client.current_weight,
    nullif(v_row.basics -&gt;&gt; 'weight_value_current', '')::numeric
  );

  if v_full_name is null then
    raise exception 'Client profile full name is incomplete';
  end if;

  if v_phone is null then
    raise exception 'Client profile phone is incomplete';
  end if;

  if v_sex is null then
    raise exception 'Client profile sex/gender is incomplete';
  end if;

  if v_dob is null then
    raise exception 'Client profile date of birth is incomplete';
  end if;

  if v_height is null then
    raise exception 'Client profile height is incomplete';
  end if;

  if v_weight is null then
    raise exception 'Client profile current weight is incomplete';
  end if;

  if v_row.goals = '{}'::jsonb then
    raise exception 'Onboarding goals are incomplete';
  end if;

  if v_row.training_history = '{}'::jsonb then
    raise exception 'Onboarding training history is incomplete';
  end if;

  if v_row.injuries_limitations = '{}'::jsonb then
    raise exception 'Onboarding injuries/limitations are incomplete';
  end if;

  if v_row.nutrition_lifestyle = '{}'::jsonb then
    raise exception 'Onboarding nutrition/lifestyle is incomplete';
  end if;

  v_baseline_id := v_row.initial_baseline_entry_id;

  if v_baseline_id is null then
    select be.id
    into v_baseline_id
    from public.baseline_entries be
    where be.client_id = p_client_id
      and be.status = 'submitted'
    order by coalesce(be.submitted_at, be.created_at) desc
    limit 1;
  end if;

  if v_baseline_id is null then
    raise exception 'Submitted baseline is required before onboarding can be submitted';
  end if;

  if not exists (
    select 1
    from public.baseline_entries be
    where be.id = v_baseline_id
      and be.client_id = p_client_id
      and be.status = 'submitted'
  ) then
    raise exception 'Linked baseline must be submitted before onboarding can be submitted';
  end if;

  update public.workspace_client_onboardings
  set
    initial_baseline_entry_id = coalesce(initial_baseline_entry_id, v_baseline_id),
    status = 'review_needed',
    submitted_at = now()
  where id = v_row.id
  returning *
  into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_pt_package_archive_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.title := nullif(btrim(coalesce(new.title, '')), '');
  if new.title is null then
    raise exception 'Package title is required';
  end if;

  if new.status = 'archived' then
    new.archived_at := coalesce(new.archived_at, now());
    new.is_public := false;
  elsif new.status in ('draft', 'active') then
    new.archived_at := null;
  end if;

  if new.sort_order is null then
    new.sort_order := 0;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_account_capacity_reservation(p_reservation_id uuid, p_status text, p_source text, p_metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.account_capacity_reservations%rowtype; a uuid; t timestamptz := transaction_timestamp();
begin
  perform public.validate_account_capacity_metadata(p_source,p_metadata);
  if p_status not in ('consumed','released','expired') or p_status is null then raise exception 'Invalid terminal status.' using errcode='22023'; end if;
  select billing_account_id into a from public.account_capacity_reservations where id=p_reservation_id;
  perform 1 from public.billing_accounts where id=a for update;
  select * into r from public.account_capacity_reservations where id=p_reservation_id for update;
  if not found then raise exception 'Unknown reservation.' using errcode='22023'; end if;
  if r.status=p_status then return jsonb_build_object('reservationId',r.id,'status',r.status,'transitioned',false); end if;
  if r.status&lt;&gt;'active' or (p_status='consumed' and r.expires_at&lt;=t) or (p_status='expired' and r.expires_at&gt;t) then raise exception 'Conflicting reservation state.' using errcode='22023'; end if;
  update public.account_capacity_reservations set status=p_status,
    consumed_at=case when p_status='consumed' then t end,released_at=case when p_status='released' then t end,expired_at=case when p_status='expired' then t end where id=r.id;
  insert into public.account_capacity_events(billing_account_id,reservation_id,dimension,event_type,quantity,source,metadata)
    values(r.billing_account_id,r.id,r.dimension,'capacity.reservation_' || p_status,r.quantity,p_source,p_metadata);
  return jsonb_build_object('reservationId',r.id,'status',p_status,'transitioned',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_pt_package(p_package_id uuid, p_input jsonb)
 RETURNS public.pt_packages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.pt_packages; patch jsonb;
begin
  if auth.uid() is null then raise exception 'Not authenticated' using errcode='42501'; end if;
  perform public.lock_capacity_owners(array[auth.uid()]);
  select * into r from public.pt_packages where id=p_package_id and pt_user_id=auth.uid() for update;
  if not found then raise exception 'Package not found' using errcode='42501'; end if;
  -- Explicit allowlist: owner, ID, timestamps and reservation context are never inputs.
  patch:=to_jsonb(r) || coalesce(p_input,'{}'::jsonb);
  update public.pt_packages set title=patch-&gt;&gt;'title',subtitle=patch-&gt;&gt;'subtitle',
    description=patch-&gt;&gt;'description',price_label=patch-&gt;&gt;'price_label',currency_code=patch-&gt;&gt;'currency_code',
    billing_cadence_label=patch-&gt;&gt;'billing_cadence_label',cta_label=patch-&gt;&gt;'cta_label',features=patch-&gt;'features',
    status=patch-&gt;&gt;'status',is_public=(patch-&gt;&gt;'is_public')::boolean,sort_order=(patch-&gt;&gt;'sort_order')::integer
    where id=r.id returning * into r;
  return r;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_workspace_team_member_clients(p_workspace_id uuid, p_member_id uuid, p_client_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_member public.workspace_members%rowtype;
  v_client_ids uuid[];
  v_valid_client_count int;
  v_added_client_ids uuid[];
  v_removed_client_ids uuid[];
begin
  if v_actor_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  if not public.can_manage_workspace_team(p_workspace_id) then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  select *
  into v_member
  from public.workspace_members wm
  where wm.id = p_member_id
    and wm.workspace_id = p_workspace_id
    and public.normalize_workspace_role(wm.role::text) &lt;&gt; 'owner'
  for update;

  if not found then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  select coalesce(array_agg(distinct client_id), '{}'::uuid[])
  into v_client_ids
  from unnest(coalesce(p_client_ids, '{}'::uuid[])) as client_id
  where client_id is not null;

  if cardinality(v_client_ids) &gt; 0 then
    select count(*)
    into v_valid_client_count
    from public.clients c
    where c.workspace_id = p_workspace_id
      and c.id = any(v_client_ids);

    if v_valid_client_count is distinct from cardinality(v_client_ids) then
      perform public.workspace_team_invite_error('INVALID_CLIENT_ASSIGNMENT');
    end if;
  end if;

  select coalesce(array_agg(existing.client_id), '{}'::uuid[])
  into v_removed_client_ids
  from public.workspace_member_client_assignments existing
  where existing.workspace_id = p_workspace_id
    and existing.member_id = p_member_id
    and not (existing.client_id = any(v_client_ids));

  select coalesce(array_agg(new_client_id), '{}'::uuid[])
  into v_added_client_ids
  from unnest(v_client_ids) as new_client_id
  where not exists (
    select 1
    from public.workspace_member_client_assignments existing
    where existing.workspace_id = p_workspace_id
      and existing.member_id = p_member_id
      and existing.client_id = new_client_id
  );

  delete from public.workspace_member_client_assignments wmca
  where wmca.workspace_id = p_workspace_id
    and wmca.member_id = p_member_id
    and not (wmca.client_id = any(v_client_ids));

  insert into public.workspace_member_client_assignments (
    workspace_id,
    member_id,
    client_id,
    assigned_by_user_id
  )
  select
    p_workspace_id,
    p_member_id,
    client_id,
    v_actor_user_id
  from unnest(v_client_ids) as client_id
  on conflict (workspace_id, member_id, client_id) do nothing;

  if cardinality(v_added_client_ids) &gt; 0 then
    perform public.record_workspace_team_audit_event(
      p_workspace_id,
      v_actor_user_id,
      'team.client_assigned',
      'workspace_member',
      p_member_id,
      null,
      jsonb_build_object(
        'clientIds', v_added_client_ids,
        'clientCount', cardinality(v_added_client_ids)
      )
    );

    perform public.notify_workspace_team_user(
      p_workspace_id,
      v_member.user_id,
      'team_clients_assigned',
      'Clients assigned',
      cardinality(v_added_client_ids)::text || ' client' ||
        case when cardinality(v_added_client_ids) = 1 then '' else 's' end ||
        ' assigned to you.',
      '/workspace/' || p_workspace_id::text,
      'workspace_member',
      p_member_id,
      jsonb_build_object('clientCount', cardinality(v_added_client_ids))
    );
  end if;

  if cardinality(v_removed_client_ids) &gt; 0 then
    perform public.record_workspace_team_audit_event(
      p_workspace_id,
      v_actor_user_id,
      'team.client_unassigned',
      'workspace_member',
      p_member_id,
      null,
      jsonb_build_object(
        'clientIds', v_removed_client_ids,
        'clientCount', cardinality(v_removed_client_ids)
      )
    );
  end if;

  return jsonb_build_object(
    'memberId', p_member_id,
    'workspaceId', p_workspace_id,
    'assignedClientCount', cardinality(v_client_ids)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_workspace_team_member_role(p_workspace_id uuid, p_member_id uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_member public.workspace_members%rowtype;
  v_previous_role text;
  v_next_role text := trim(coalesce(p_role, ''));
begin
  if v_actor_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  if not public.can_manage_workspace_team(p_workspace_id) then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  if v_next_role not in ('admin', 'coach', 'assistant_coach', 'viewer') then
    perform public.workspace_team_invite_error('INVALID_INVITE_ROLE');
  end if;

  select *
  into v_member
  from public.workspace_members wm
  where wm.id = p_member_id
    and wm.workspace_id = p_workspace_id
  for update;

  if not found then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  v_previous_role := public.normalize_workspace_role(v_member.role::text);
  if v_previous_role = 'owner' then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  if v_previous_role = v_next_role then
    return jsonb_build_object(
      'memberId', p_member_id,
      'workspaceId', p_workspace_id,
      'role', v_next_role
    );
  end if;

  update public.workspace_members
  set role = v_next_role::public.workspace_role,
      updated_at = now()
  where id = p_member_id
  returning * into v_member;

  perform public.record_workspace_team_audit_event(
    p_workspace_id,
    v_actor_user_id,
    'team.role_changed',
    'workspace_member',
    p_member_id,
    null,
    jsonb_build_object('previousRole', v_previous_role, 'nextRole', v_next_role)
  );

  perform public.notify_workspace_team_user(
    p_workspace_id,
    v_member.user_id,
    'team_role_changed',
    'Workspace role updated',
    'Your workspace role is now ' || replace(v_next_role, '_', ' ') || '.',
    '/workspace/' || p_workspace_id::text,
    'workspace_member',
    p_member_id,
    jsonb_build_object('previousRole', v_previous_role, 'nextRole', v_next_role)
  );

  return jsonb_build_object(
    'memberId', p_member_id,
    'workspaceId', p_workspace_id,
    'role', v_next_role
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_workspace_team_member_status(p_workspace_id uuid, p_member_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_member public.workspace_members%rowtype;
  v_previous_status text;
  v_next_status text := trim(coalesce(p_status, ''));
  v_event_type text;
  v_notification_type text;
begin
  if v_actor_user_id is null then
    perform public.workspace_team_invite_error('UNAUTHENTICATED');
  end if;

  if not public.can_manage_workspace_team(p_workspace_id) then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  if v_next_status not in ('active', 'suspended', 'removed') then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  select *
  into v_member
  from public.workspace_members wm
  where wm.id = p_member_id
    and wm.workspace_id = p_workspace_id
  for update;

  if not found then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  if public.normalize_workspace_role(v_member.role::text) = 'owner' then
    perform public.workspace_team_invite_error('WORKSPACE_PERMISSION_DENIED');
  end if;

  v_previous_status := coalesce(v_member.status, 'active');

  if v_previous_status = v_next_status then
    return jsonb_build_object(
      'memberId', p_member_id,
      'workspaceId', p_workspace_id,
      'status', v_next_status
    );
  end if;

  update public.workspace_members
  set status = v_next_status,
      updated_at = now()
  where id = p_member_id
  returning * into v_member;

  v_event_type := case
    when v_next_status = 'suspended' then 'team.member_suspended'
    when v_next_status = 'removed' then 'team.member_removed'
    else 'team.member_reactivated'
  end;
  v_notification_type := case
    when v_next_status = 'suspended' then 'team_member_suspended'
    when v_next_status = 'removed' then 'team_member_removed'
    else 'team_member_reactivated'
  end;

  perform public.record_workspace_team_audit_event(
    p_workspace_id,
    v_actor_user_id,
    v_event_type,
    'workspace_member',
    p_member_id,
    null,
    jsonb_build_object('previousStatus', v_previous_status, 'nextStatus', v_next_status)
  );

  perform public.notify_workspace_team_user(
    p_workspace_id,
    v_member.user_id,
    v_notification_type,
    'Workspace access updated',
    case
      when v_next_status = 'active' then 'Your workspace access is active again.'
      else 'Your access to this workspace is no longer active. Contact the workspace owner if this looks incorrect.'
    end,
    '/pt-hub/workspaces',
    'workspace_member',
    p_member_id,
    jsonb_build_object('previousStatus', v_previous_status, 'nextStatus', v_next_status)
  );

  return jsonb_build_object(
    'memberId', p_member_id,
    'workspaceId', p_workspace_id,
    'status', v_next_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_checkin_submission_requirements(p_checkin_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_checkin record;
  v_effective_template_id uuid;
  v_missing_questions text[];
  v_missing_photos text[];
begin
  select ci.id,
         ci.client_id,
         ci.template_id,
         ci.week_ending_saturday,
         c.checkin_start_date,
         c.checkin_frequency
  into v_checkin
  from public.checkins ci
  join public.clients c on c.id = ci.client_id
  where ci.id = p_checkin_id;

  if v_checkin.id is null then
    raise exception 'Check-in not found';
  end if;

  if v_checkin.checkin_start_date is null then
    raise exception 'Check-in start date is required before submission';
  end if;

  v_effective_template_id := public.get_effective_client_checkin_template_id(
    v_checkin.client_id
  );

  if v_effective_template_id is null then
    raise exception 'Check-in template is required before submission';
  end if;

  if v_checkin.template_id is distinct from v_effective_template_id then
    raise exception 'Check-in template is out of date for this client';
  end if;

  if not public.is_client_checkin_due_date(
    v_checkin.client_id,
    v_checkin.week_ending_saturday
  ) then
    raise exception 'Check-in due date does not match the client schedule';
  end if;

  select array_agg(
           coalesce(
             nullif(trim(q.question_text), ''),
             nullif(trim(q.prompt), ''),
             q.id::text
           )
           order by coalesce(q.sort_order, q.position, 0), q.id
         )
  into v_missing_questions
  from public.checkin_questions q
  left join public.checkin_answers a
    on a.checkin_id = v_checkin.id
   and a.question_id = q.id
  where q.template_id = v_checkin.template_id
    and q.is_required
    and nullif(btrim(coalesce(a.value_text, '')), '') is null
    and a.value_number is null;

  if coalesce(array_length(v_missing_questions, 1), 0) &gt; 0 then
    raise exception 'Required check-in answers are missing';
  end if;

  select array_agg(req.photo_type order by req.photo_type)
  into v_missing_photos
  from (values ('front'), ('side'), ('back')) as req(photo_type)
  left join public.checkin_photos cp
    on cp.checkin_id = v_checkin.id
   and cp.photo_type = req.photo_type
  where cp.id is null;

  if coalesce(array_length(v_missing_photos, 1), 0) &gt; 0 then
    raise exception 'Required progress photos are missing';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_paddle_catalogue_v1(p_environment text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare m public.billing_price_mappings%rowtype; total integer:=0;
begin
  perform public.billing_catalogue_authorize_v1();
  if p_environment is distinct from 'test' then raise exception 'BILLING_CATALOGUE_ENVIRONMENT'; end if;
  perform pg_advisory_xact_lock(hashtextextended('paddle-catalogue-publication-v1:test',0));
  for m in select * from public.billing_price_mappings where provider='paddle' and environment=p_environment and status='active' order by id for share loop
    perform public.billing_catalogue_assert_mapping_v1(m);
    if m.identity_kind='plan' then
      perform 1 from public.commercial_plan_versions where id=m.plan_version_id and status='active' for share;
    else
      perform 1 from public.commercial_addon_versions where id=m.addon_version_id and status='active' for share;
    end if;
    if not found then raise exception 'BILLING_CATALOGUE_INCOMPLETE'; end if;
    total:=total+1;
  end loop;
  -- Existing unique(provider,environment,key,cadence) for active rows plus the
  -- closed four-key/two-cadence whitelist proves each pair occurs exactly once.
  if total&lt;&gt;8 then raise exception 'BILLING_CATALOGUE_INCOMPLETE'; end if;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.verify_invite(p_token text)
 RETURNS TABLE(is_valid boolean, reason text, invite_id uuid, workspace_id uuid, workspace_name text, workspace_logo_url text, role text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_invite record;
begin
  if p_token is null or trim(p_token) = '' then
    return query
    select false, 'missing_token', null::uuid, null::uuid, null::text, null::text, null::text, null::timestamptz;
    return;
  end if;

  select
    i.id,
    i.workspace_id,
    i.role::text as role,
    i.expires_at,
    i.used_at,
    i.max_uses,
    coalesce(i.uses, 0) as uses
  into v_invite
  from public.invites i
  where i.token = p_token or i.code = p_token
  order by i.created_at desc
  limit 1;

  if v_invite.id is null then
    return query
    select false, 'not_found', null::uuid, null::uuid, null::text, null::text, null::text, null::timestamptz;
    return;
  end if;

  if v_invite.role &lt;&gt; 'client' then
    return query
    select false, 'invalid_role', v_invite.id, v_invite.workspace_id, null::text, null::text, v_invite.role, v_invite.expires_at;
    return;
  end if;

  if v_invite.used_at is not null then
    return query
    select false, 'already_used', v_invite.id, v_invite.workspace_id, null::text, null::text, v_invite.role, v_invite.expires_at;
    return;
  end if;

  if v_invite.expires_at is not null and v_invite.expires_at &lt;= now() then
    return query
    select false, 'expired', v_invite.id, v_invite.workspace_id, null::text, null::text, v_invite.role, v_invite.expires_at;
    return;
  end if;

  if v_invite.max_uses is not null and v_invite.uses &gt;= v_invite.max_uses then
    return query
    select false, 'max_uses_reached', v_invite.id, v_invite.workspace_id, null::text, null::text, v_invite.role, v_invite.expires_at;
    return;
  end if;

  return query
  select
    true,
    null::text,
    v_invite.id,
    v_invite.workspace_id,
    w.name,
    coalesce(w.logo_url, null)::text,
    v_invite.role,
    v_invite.expires_at
  from public.workspaces w
  where w.id = v_invite.workspace_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.workspace_invite_branding(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_invite record;
begin
  select * into v_invite from public.verify_invite(p_token);
  if not coalesce(v_invite.is_valid, false) then return null; end if;
  return (select jsonb_build_object(
    'id', w.id, 'name', w.name, 'logo_url', w.logo_url,
    'accent_color', w.accent_color, 'client_welcome_title', w.client_welcome_title,
    'client_welcome_message', w.client_welcome_message,
    'invite_sender_name', w.invite_sender_name
  ) from public.workspaces w where w.id = v_invite.workspace_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.workspace_start_account_trial()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'INSERT' then perform public.start_account_trial_for_owner(new.owner_user_id,'first_workspace');
  elsif new.owner_user_id is distinct from old.owner_user_id then perform public.start_account_trial_for_owner(new.owner_user_id,'workspace_transfer'); end if;
  return new;
end;
$function$
